"use strict";(self.webpackChunkhb_scaffold=self.webpackChunkhb_scaffold||[]).push([["31829"],{50320(e,t,s){s.r(t),s.d(t,{metadata:()=>n,default:()=>l,frontMatter:()=>o,contentTitle:()=>i,toc:()=>h,assets:()=>d});var n=JSON.parse('{"id":"part-12-ai-networking/c12-21","title":"12.21 Storage networks, Ultra Ethernet and scale-up fabrics","description":"Design and verify AI storage networks (NVMe-o-TCP, NVMe-o-RDMA, parallel file systems, InfiniBand storage), Ultra Ethernet Consortium (UEC v1.0 UET, PDS/SES, ROD/RUD/RUDI/UUD, NSCC, RCCC, CBFC, LLR, INC), and open scale-up fabrics (OCP SUE-T/ESUN and UALink 1.0).","source":"@site/docs/part-12-ai-networking/21-storage-networks-ultra-ethernet-and-scale-up-fabrics.md","sourceDirName":"part-12-ai-networking","slug":"/part-12-ai-networking/c12-21","permalink":"/ai-infra-handbook/part-12-ai-networking/c12-21","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":21,"frontMatter":{"id":"c12-21","title":"12.21 Storage networks, Ultra Ethernet and scale-up fabrics","sidebar_label":"12.21 Storage networks, Ultra Ethernet and scale-up fabrics","sidebar_position":21,"description":"Design and verify AI storage networks (NVMe-o-TCP, NVMe-o-RDMA, parallel file systems, InfiniBand storage), Ultra Ethernet Consortium (UEC v1.0 UET, PDS/SES, ROD/RUD/RUDI/UUD, NSCC, RCCC, CBFC, LLR, INC), and open scale-up fabrics (OCP SUE-T/ESUN and UALink 1.0).","status":"drafted","tier":"2","level":"A","lab_venue":"Nebius GPU"},"sidebar":"tutorialSidebar","previous":{"title":"12.20 SHARP and in-network computing","permalink":"/ai-infra-handbook/part-12-ai-networking/c12-20"},"next":{"title":"12.22 AI network telemetry and KPIs","permalink":"/ai-infra-handbook/part-12-ai-networking/c12-22"}}'),a=s(74848),r=s(28453);let o={id:"c12-21",title:"12.21 Storage networks, Ultra Ethernet and scale-up fabrics",sidebar_label:"12.21 Storage networks, Ultra Ethernet and scale-up fabrics",sidebar_position:21,description:"Design and verify AI storage networks (NVMe-o-TCP, NVMe-o-RDMA, parallel file systems, InfiniBand storage), Ultra Ethernet Consortium (UEC v1.0 UET, PDS/SES, ROD/RUD/RUDI/UUD, NSCC, RCCC, CBFC, LLR, INC), and open scale-up fabrics (OCP SUE-T/ESUN and UALink 1.0).",status:"drafted",tier:"2",level:"A",lab_venue:"Nebius GPU"},i="12.21 Storage networks, Ultra Ethernet and scale-up fabrics",d={},h=[{value:"Why this matters for AI infrastructure",id:"why-this-matters-for-ai-infrastructure",level:2},{value:"Prerequisites and outcomes",id:"prerequisites-and-outcomes",level:2},{value:"Prerequisites",id:"prerequisites",level:3},{value:"Outcomes",id:"outcomes",level:3},{value:"1. AI Storage Network Lifecycle, Topologies, and Access Models",id:"1-ai-storage-network-lifecycle-topologies-and-access-models",level:2},{value:"1.1 The Four-Stage AI Data Lifecycle and Storage Access Tiers",id:"11-the-four-stage-ai-data-lifecycle-and-storage-access-tiers",level:3},{value:"1.2 Four Storage Fabric Topologies: Physical Fab A/B, Logical Fab A/B, Collapsed Spine, and Hybrid Cloud",id:"12-four-storage-fabric-topologies-physical-fab-ab-logical-fab-ab-collapsed-spine-and-hybrid-cloud",level:3},{value:"1.3 PCIe-Attached Drives vs Network-Attached Storage: Latency and When Each Fits",id:"13-pcie-attached-drives-vs-network-attached-storage-latency-and-when-each-fits",level:3},{value:"1.4 Checkpoints and Fast Writes During Training",id:"14-checkpoints-and-fast-writes-during-training",level:3},{value:"1.5 Redundancy, Path Diversity, and Inter-Site Replication",id:"15-redundancy-path-diversity-and-inter-site-replication",level:3},{value:"1.6 Logical Fab A/B With EVPN-VXLAN Overlays",id:"16-logical-fab-ab-with-evpn-vxlan-overlays",level:3},{value:"1.7 Hot and Cold Data Across On-Premises Storage and Object Storage",id:"17-hot-and-cold-data-across-on-premises-storage-and-object-storage",level:3},{value:"2. NVMe-oF State Machines (NVMe-o-TCP vs NVMe-o-RDMA), Parallel File Systems, and InfiniBand Storage",id:"2-nvme-of-state-machines-nvme-o-tcp-vs-nvme-o-rdma-parallel-file-systems-and-infiniband-storage",level:2},{value:"2.1 NVMe-oF Architecture: Queues, Capsules, NSID, and PRP vs SGL",id:"21-nvme-of-architecture-queues-capsules-nsid-and-prp-vs-sgl",level:3},{value:"2.2 NVMe-o-TCP State Machine, PDUs, and Jumbo-Frame Packing",id:"22-nvme-o-tcp-state-machine-pdus-and-jumbo-frame-packing",level:3},{value:"2.3 NVMe-o-RDMA (RoCEv2) State Machine: TCP 8009 -&gt; UDP 4420 -&gt; UDP 4791",id:"23-nvme-o-rdma-rocev2-state-machine-tcp-8009---udp-4420---udp-4791",level:3},{value:"2.4 High-Performance Parallel File Systems and GPUDirect Storage Integration",id:"24-high-performance-parallel-file-systems-and-gpudirect-storage-integration",level:3},{value:"2.5 InfiniBand for Storage: 16-Bit LID (48,000 Nodes), Frame Format, and 64B CBFC Credits",id:"25-infiniband-for-storage-16-bit-lid-48000-nodes-frame-format-and-64b-cbfc-credits",level:3},{value:"2.6 GPUDirect Storage: Logical View and CUDA API Orchestration",id:"26-gpudirect-storage-logical-view-and-cuda-api-orchestration",level:3},{value:"3. Ultra Ethernet Consortium (UEC Specification v1.0): Architecture, PDS/SES, Encapsulations, and Delivery Modes",id:"3-ultra-ethernet-consortium-uec-specification-v10-architecture-pdsses-encapsulations-and-delivery-modes",level:2},{value:"3.1 UEC Working Groups, Service Profiles (AI Base, AI Full, HPC), and Core Terminology",id:"31-uec-working-groups-service-profiles-ai-base-ai-full-hpc-and-core-terminology",level:3},{value:"3.2 PDC Session Handshake, UDP-Based Encapsulation for UET (UDP Port 49150), and UET over IP (IP Protocol 253)",id:"32-pdc-session-handshake-udp-based-encapsulation-for-uet-udp-port-49150-and-uet-over-ip-ip-protocol-253",level:3},{value:"3.3 The Four UEC Packet Delivery Modes (ROD, RUD, RUDI, UUD)",id:"33-the-four-uec-packet-delivery-modes-rod-rud-rudi-uud",level:3},{value:"3.4 Protocol Stack, Network Architectures, and Existing Ethernet",id:"34-protocol-stack-network-architectures-and-existing-ethernet",level:3},{value:"4. UEC Congestion Management (NSCC, RCCC, CBFC), Packet Trimming, LLR, and In-Network Collectives (INC)",id:"4-uec-congestion-management-nscc-rccc-cbfc-packet-trimming-llr-and-in-network-collectives-inc",level:2},{value:"4.1 Two-Tier Congestion Management: NSCC, RCCC (256B Credits), and Link-Level CBFC (32 VCs)",id:"41-two-tier-congestion-management-nscc-rccc-256b-credits-and-link-level-cbfc-32-vcs",level:3},{value:"4.2 Fast Retransmission via DSCP Packet Trimming and Hop-by-Hop Link Layer Reliability (LLR)",id:"42-fast-retransmission-via-dscp-packet-trimming-and-hop-by-hop-link-layer-reliability-llr",level:3},{value:"4.3 In-Network Collectives (INC) vs User-Space xCCL, Management, Interoperability, and Compliance",id:"43-in-network-collectives-inc-vs-user-space-xccl-management-interoperability-and-compliance",level:3},{value:"4.4 Comparing UEC to InfiniBand and RoCEv2",id:"44-comparing-uec-to-infiniband-and-rocev2",level:3},{value:"5. Scale-Up Systems: Architecture, OCP SUE-T (ESUN), UALink 1.0, and Memory Coherence",id:"5-scale-up-systems-architecture-ocp-sue-t-esun-ualink-10-and-memory-coherence",level:2},{value:"5.1 Why Scale-Up Pods Exist: Latency, Bandwidth, and the 4-Rack / 1,000-xPU Boundary",id:"51-why-scale-up-pods-exist-latency-bandwidth-and-the-4-rack--1000-xpu-boundary",level:3},{value:"5.2 Open Compute Project (OCP) Scale-Up Ethernet Transport (SUE-T / ESUN)",id:"52-open-compute-project-ocp-scale-up-ethernet-transport-sue-t--esun",level:3},{value:"5.3 Ultra Accelerator Link (UALink 1.0): 6.4 Tbps Stations, 64B/640B Flits, UPLI, and GVA -&gt; NPA -&gt; SPA",id:"53-ultra-accelerator-link-ualink-10-64-tbps-stations-64b640b-flits-upli-and-gva---npa---spa",level:3},{value:"5.4 Hardware Directory Coherence vs Software PGAS Coherence and Scale-Up Comparison",id:"54-hardware-directory-coherence-vs-software-pgas-coherence-and-scale-up-comparison",level:3},{value:"5.5 Pod Building Blocks, HBM Placement, and Vendor Scope",id:"55-pod-building-blocks-hbm-placement-and-vendor-scope",level:3},{value:"5.6 Single-Hop Mesh Wiring and Attaching Pods to Fabric Planes",id:"56-single-hop-mesh-wiring-and-attaching-pods-to-fabric-planes",level:3},{value:"5.7 Full Scale-Up Comparison and Why Open Standards Matter",id:"57-full-scale-up-comparison-and-why-open-standards-matter",level:3},{value:"5.8 UALink Flit Layout, Station Wiring, and Address Handles",id:"58-ualink-flit-layout-station-wiring-and-address-handles",level:3},{value:"Commands and configurations that matter",id:"commands-and-configurations-that-matter",level:2},{value:"1. NVMe-o-TCP (Port 8009) and NVMe-o-RDMA (RoCEv2 Ports 8009 -&gt; 4420 -&gt; 4791) Host Operations",id:"1-nvme-o-tcp-port-8009-and-nvme-o-rdma-rocev2-ports-8009---4420---4791-host-operations",level:3},{value:"2. Inspecting NVMe-o-RDMA, UET-over-UDP (49150), and UET-over-IP (Proto 253) on the Wire",id:"2-inspecting-nvme-o-rdma-uet-over-udp-49150-and-uet-over-ip-proto-253-on-the-wire",level:3},{value:"3. InfiniBand Storage Subnet (LID &amp; 16 VLs) and GPUDirect Storage Verification",id:"3-infiniband-storage-subnet-lid--16-vls-and-gpudirect-storage-verification",level:3},{value:"How it fails",id:"how-it-fails",level:2},{value:"Hands-on lab",id:"hands-on-lab",level:2},{value:"Venue and Scope",id:"venue-and-scope",level:3},{value:"Run the Verification Lab",id:"run-the-verification-lab",level:3},{value:"Common first mistakes",id:"common-first-mistakes",level:2},{value:"Exercises",id:"exercises",level:2},{value:"Interview angles",id:"interview-angles",level:2},{value:"Checkpoint questions (20)",id:"checkpoint-questions-20",level:2},{value:"Sources and review notes",id:"sources-and-review-notes",level:2}];function c(e){let t={code:"code",em:"em",h1:"h1",h2:"h2",h3:"h3",header:"header",hr:"hr",li:"li",mermaid:"mermaid",ol:"ol",p:"p",pre:"pre",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,r.R)(),...e.components},{Details:s}=t;return s||function(e,t){throw Error("Expected "+(t?"component":"object")+" `"+e+"` to be defined: you likely forgot to import, pass, or provide it.")}("Details",!0),(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"1221-storage-networks-ultra-ethernet-and-scale-up-fabrics",children:"12.21 Storage networks, Ultra Ethernet and scale-up fabrics"})}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Field"}),(0,a.jsx)(t.th,{children:"Value"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Level"}),(0,a.jsx)(t.td,{children:"Advanced"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Priority tier"}),(0,a.jsx)(t.td,{children:"2"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Lab venue"}),(0,a.jsxs)(t.td,{children:["Nebius GPU + Local Python Verification Lab (",(0,a.jsx)(t.code,{children:"code/part12/storage_uec_scaleup_lab.py"}),")"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Part"}),(0,a.jsx)(t.td,{children:"Part 12: Complete AI networking"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Primary sources"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," (Chapters 9, 12, 13)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Coverage file"}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"planning/coverage/chapters/12-21.md"})})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Claim & number ledger"}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"planning/ledgers/12-21.md"})})]})]})]}),"\n",(0,a.jsx)(t.h2,{id:"why-this-matters-for-ai-infrastructure",children:"Why this matters for AI infrastructure"}),"\n",(0,a.jsx)(t.p,{children:'Picture a training job that was fast last week and now crawls. The GPUs sit idle for long stretches, the compute dashboards look normal, and nobody sees an error. The cause is often the network, but "the network" is not one thing. An AI factory runs three distinct fabrics. Each one has its own latency target, bandwidth scale, and failure boundary. Think of the three fabrics as three different roads: a neighborhood street, a regional highway, and a racetrack inside a pit lane. Each road has its own speed limit and its own pattern of accidents, so a traffic plan that works on one road can jam the others. Think of the three fabrics as three different roads: a neighborhood street, a regional highway, and a racetrack inside a pit lane. Each road has its own speed limit and its own pattern of accidents, so a traffic plan that works on one road can jam the others. Treat them as interchangeable byte pipes and you will see checkpoint stalls, packet-retransmission storms, or sub-microsecond tensor starvation, and you will not know which fabric to blame. The first step in any investigation is to name the fabric that owns the symptom.'}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"AI storage networks."})," Curated training datasets must stream continuously into GPU memory. Multi-terabyte checkpoints must also flush to flash without pausing the training steps. A local PCIe drive responds in roughly a hundred nanoseconds. That speed is excellent, but it only reaches the one server that holds the drive, which is the limit the next sentences describe. That speed is excellent, but it only reaches the one server that holds the drive, which is the limit the next sentences describe. But a drive inside one server cannot hold a petabyte-scale corpus, and it cannot give thousands of nodes a shared namespace. Dedicated storage fabrics bridge that gap. They connect compute servers to shared flash arrays using NVMe-o-TCP, NVMe-o-RDMA over RoCEv2, and parallel file systems with GPUDirect Storage. Think of a shared flash array as a central library that every reader can walk into, rather than a separate bookshelf in each house. Think of a shared flash array as a central library that every reader can walk into, rather than a separate bookshelf in each house."]}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:["\n",(0,a.jsxs)(t.p,{children:[(0,a.jsx)(t.strong,{children:"Ultra Ethernet Consortium scale-out fabrics."})," Production RoCEv2 clusters have grown past 100,000 GPUs. Even so, RoCEv2 still inherits legacy InfiniBand Queue Pair semantics and static flow hashing. It also suffers from Go-Back-N retransmission amplification and fragile PFC pause tuning."]}),"\n",(0,a.jsx)(t.p,{children:"The Ultra Ethernet work starts from a simple complaint. RoCEv2 was built by stretching an older design onto Ethernet, and each stretch shows at scale. The rest of this bullet explains what the new specification changes, and it names the parts that matter most for a storage or training fabric."}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"UEC Specification v1.0 replaces the RoCEv2 transport stack with Ultra Ethernet Transport over UDP or native IP. The work is split between a Packet Delivery Sublayer and a Semantic Sublayer that is driven by Libfabric. UEC adds four packet delivery modes, built-in AES-GCM security, and both sender and receiver congestion control. It also brings link-level Credit-Based Flow Control, DSCP packet trimming, Link Layer Reliability, and In-Network Collectives."}),"\n",(0,a.jsxs)(t.ol,{start:"3",children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Scale-up super-accelerator fabrics."})," Tensor parallelism, Mixture-of-Experts token routing, multi-step reasoning, and diffusion micro-batching exchange activations at a sub-microsecond cadence. That cadence overwhelms PCIe and scale-out NICs. Proprietary scale-up fabrics such as NVIDIA NVLink 5 tie the buyer to one vendor. Two open standards have emerged to break that lock-in: the Open Compute Project Scale-Up Ethernet Transport under ESUN, and the Ultra Accelerator Link."]}),"\n"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Three AI Fabric Domains - Reference Latency, Bandwidth, and Protocol Numbers:\n1. AI Storage Networks (100 Gbps-800 Gbps per server, 1:3 leaf-to-spine oversubscription):\n   - Local PCIe Gen5/Gen6 SSD: ~100 ns device latency (32 GT/s per lane, ~63 Gbps / 64 GB/s unidirectional across x16 lanes, 3.94 GB/s per lane)\n   - Network storage switch latency: ~300 ns on InfiniBand switches vs 700-900 ns (~800 ns) port-to-port on Ethernet switches\n   - Storage protocols: NVMe-o-TCP (TCP port 8009), NVMe-o-RDMA over RoCEv2 (TCP 8009 discovery, UDP 4420 RDMA CM, UDP 4791 BTH/RETH data plane with up to 66% lower write latency), parallel file systems (WekaFS, VAST, Lustre, GPFS, BeeGFS) with GPUDirect Storage (GDS)\n2. Ultra Ethernet Consortium (UEC Specification v1.0, released June 11, 2025, 400 Gbps-1.6 Tbps scale-out up to 1 million endpoints):\n   - Transport encapsulations: UET over UDP port 49150 (IP protocol 17) or native IP protocol 253\n   - Sublayers & APIs: Packet Delivery Sublayer (PDS) + Semantic Sublayer (SES: JobID, PIDonFEP, Resource Index) via Libfabric (fi_mr, fi_collective)\n   - Delivery modes & security: ROD, RUD, RUDI, UUD + Transport Security Sublayer (TSS with AES-GCM + ICV)\n   - Congestion & reliability: NSCC (window/RTT/ECN), RCCC (256-byte receiver credits in a 24-bit ACK field), link-level CBFC (32 Virtual Channels with PCS CtlOS CP_Update), DSCP packet trimming, Link Layer Reliability (LLR), and In-Network Collectives (INC)\n3. Scale-Up Fabrics (100-300 ns latency, up to 6.4 Tbps per xPU, 72 to 1,000 accelerators across 1-4 racks):\n   - Baseline comparison: PCIe 5.0 (500 ns-1 us latency) vs NVLink 5 (1.8 Tbps / 1,800 Gbps bidirectional per GPU across 18 NVLink switches in 72-GPU NVL72)\n   - OCP SUE-T / ESUN: 6-byte compressed and 12-byte non-compressed AI Fabric Header (AFH Gen 2), Reliability Header (RH), LLR, CBFC, and on-die FIFO or ARM AXI 4.0 5-channel interfaces\n   - UALink 1.0: 8 stations x 4 x 200 Gbps lanes = 32 lanes = 6.4 Tbps per xPU, 64-byte Transaction Layer (TL) flits packed 10:1 into 640-byte Data Link (DL) flits + 40-byte FEC = 680-byte wire units aligned 1:1 to RS(544, 514) PCS codewords, 1-way/2-way interleaving, GVA -> NPA -> SPA MMU address handles, and software PGAS coherence\n"})}),"\n",(0,a.jsx)(t.p,{children:"Each of the three domains answers a different question, so a single design rule will not fit all of them. Decide which domain a new cluster needs first, because each one has its own latency, bandwidth, and failure rules. A storage plan that borrows the training fabric's rules will look fine on paper and fail under a checkpoint burst."}),"\n",(0,a.jsx)(t.h2,{id:"prerequisites-and-outcomes",children:"Prerequisites and outcomes"}),"\n",(0,a.jsx)(t.p,{children:"This chapter builds on the RoCEv2 and InfiniBand material earlier in this part. Think of those earlier chapters as the road map you already studied, and this chapter as the set of new streets built on top of it. Read it first if any of the terms below feel unfamiliar, because the storage and scale-up designs reuse them directly."}),"\n",(0,a.jsx)(t.h3,{id:"prerequisites",children:"Prerequisites"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"You should know RoCEv2 over UDP port 4791, including Base Transport Headers, PFC, ECN, and DCQCN, from earlier chapters in this part."}),"\n",(0,a.jsx)(t.li,{children:"You should understand InfiniBand addressing, including LID, GUID, GID, and Virtual Lanes, from earlier chapters in this part."}),"\n",(0,a.jsxs)(t.li,{children:["You should be familiar with GPUDirect RDMA and GPUDirect Storage, including ",(0,a.jsx)(t.code,{children:"cuFile"})," and BAR1 apertures, from earlier chapters in this part."]}),"\n"]}),"\n",(0,a.jsx)(t.h3,{id:"outcomes",children:"Outcomes"}),"\n",(0,a.jsx)(t.p,{children:"Picture a storage team that has been asked to size a fabric for a new training cluster and a backup site. This chapter walks that job from the storage side to the scale-up side. It starts with storage topologies, including physical and logical Fab A and Fab B, collapsed spines, and hybrid cloud S3 replication. It then traces the protocol state machines and packet headers of NVMe-o-TCP, NVMe-o-RDMA over RoCEv2, and native InfiniBand storage. Next it decodes the Ultra Ethernet scale-out pieces, including the UET-over-UDP and UET-over-IP encapsulations, SES addressing, delivery modes, and congestion and reliability mechanisms. The last part sizes scale-up super-accelerator fabrics up to 4 racks and 1,000 xPUs, and it contrasts SUE-T under ESUN, UALink 1.0, and NVLink 5."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"1-ai-storage-network-lifecycle-topologies-and-access-models",children:"1. AI Storage Network Lifecycle, Topologies, and Access Models"}),"\n",(0,a.jsx)(t.h3,{id:"11-the-four-stage-ai-data-lifecycle-and-storage-access-tiers",children:"1.1 The Four-Stage AI Data Lifecycle and Storage Access Tiers"}),"\n",(0,a.jsx)(t.p,{children:"Think about a run that streams data well for days and then stalls every time it saves a checkpoint. A storage network built only for sequential dataset reads has no room for that write burst. Synchronous checkpoints fill the write buffers, and thousands of GPUs sit idle while they wait. Every large language model or multimodal pipeline passes through four data-lifecycle phases. Think of them as the stages of a factory line, where raw material enters at one end and finished parts leave at the other. Each station needs its own tools, and a jam at one station slows the whole line. Each phase has its own I/O sizes, concurrency patterns, and latency budgets. As you read the phases, notice that each one stresses storage in a different way. Ingestion is a steady stream, checkpointing is a sudden flood, and retrieval is a scatter of small reads. A single storage design has to survive all three in the same week."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Data ingestion:"})," Raw structured and unstructured datasets are pulled from external repositories, web crawls, or enterprise lakes into high-capacity staging pools."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Data processing and curation:"})," Tokenization, deduplication, quality filtering, and format conversion turn raw assets into training shards. This phase needs high sequential and random read and write throughput across distributed workers."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"AI model training and checkpointing:"})," Training servers stream curated batches into GPU HBM over dedicated 100 Gbps to 200 Gbps storage NICs. Converged pods use 400 Gbps to 800 Gbps NICs instead. Servers also pause compute from time to time to flush multi-terabyte checkpoints of weights and optimizer states to flash arrays."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Post-training data warehouse, archival, and RAG inference:"})," Trained checkpoints, evaluation artifacts, and vector corpora move into long-term repositories and feeds for Retrieval-Augmented Generation. These workloads need low-latency random reads and continuous live updates."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"To serve these four phases, operators combine three logical storage architectures: Object, Block, and File. Their protocol and fabric characteristics are summarized below. Before you read the table, ask which of the four phases will hit each storage type hardest, because the answer tells you which column matters most for your job."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Characteristic"}),(0,a.jsx)(t.th,{children:"Object Storage (S3)"}),(0,a.jsx)(t.th,{children:"Block Storage (NVMe-oF / SAN)"}),(0,a.jsx)(t.th,{children:"File Storage ((P)NFS / Parallel FS / NAS)"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Data organization"})}),(0,a.jsx)(t.td,{children:"Flat objects with rich metadata and object IDs"}),(0,a.jsx)(t.td,{children:"Fixed-size logical blocks addressed by NSID + LBA"}),(0,a.jsx)(t.td,{children:"Hierarchical files and directories (POSIX namespace)"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Access method"})}),(0,a.jsxs)(t.td,{children:["HTTP/HTTPS REST API calls (",(0,a.jsx)(t.code,{children:"GET"}),", ",(0,a.jsx)(t.code,{children:"PUT"}),")"]}),(0,a.jsx)(t.td,{children:"Block-level commands (NVMe SQE/CQE capsules)"}),(0,a.jsxs)(t.td,{children:["File-level POSIX syscalls (",(0,a.jsx)(t.code,{children:"open"}),", ",(0,a.jsx)(t.code,{children:"read"}),", ",(0,a.jsx)(t.code,{children:"write"}),", ",(0,a.jsx)(t.code,{children:"stat"}),", ",(0,a.jsx)(t.code,{children:"unlink"}),")"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Transport protocols"})}),(0,a.jsx)(t.td,{children:"TCP/HTTPS over lossy Ethernet/IP"}),(0,a.jsx)(t.td,{children:"NVMe-o-TCP, NVMe-o-RDMA (RoCEv2/IB), NVMe-o-FC, FCoIP"}),(0,a.jsx)(t.td,{children:"Ethernet/IP (TCP or RDMA over RoCEv2) or InfiniBand"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"OS page-cache usage"})}),(0,a.jsx)(t.td,{children:"Not used on compute host (application buffers)"}),(0,a.jsx)(t.td,{children:"Bypassed (raw block device / direct DMA)"}),(0,a.jsxs)(t.td,{children:["Supported by OS page cache or bypassed via ",(0,a.jsx)(t.code,{children:"O_DIRECT"})," / GDS"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Scalability & cost"})}),(0,a.jsx)(t.td,{children:"Highest scale (exabytes); lowest cost per TB"}),(0,a.jsx)(t.td,{children:"High performance per array; higher cost per TB"}),(0,a.jsx)(t.td,{children:"High parallel scale (WekaFS, VAST, Lustre, GPFS); moderate cost"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Primary AI domain"})}),(0,a.jsx)(t.td,{children:"Post-training cloud replication, cold archives, RAG / agentic RAG"}),(0,a.jsx)(t.td,{children:"High-IOPS local/on-prem datasets, raw block volumes, fast checkpoint targets"}),(0,a.jsx)(t.td,{children:"Shared multi-node training datasets, synchronous checkpointing, hybrid cloud tiering"})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"Read the table as a set of trade-offs, not a ranking. Think of object storage as a warehouse that holds almost anything at low cost, block storage as a fast workbench with limited space, and file storage as a shared office where many people open the same folders at once. Object storage reaches the largest scale at the lowest cost per terabyte. That makes it a good home for archives and long-term copies, even though each read takes more time than a block read. Block storage gives the most performance per array, and it costs more per terabyte. File storage sits in the middle, and it is the one that lets many training nodes share the same files. That shared view is why most training datasets live on a file system during the run. Consider the column that matches your access pattern before you pick a tier. A reader who scans a dataset once has different needs from a job that writes a checkpoint every hour, so write down the pattern first."}),"\n",(0,a.jsx)(t.h3,{id:"12-four-storage-fabric-topologies-physical-fab-ab-logical-fab-ab-collapsed-spine-and-hybrid-cloud",children:"1.2 Four Storage Fabric Topologies: Physical Fab A/B, Logical Fab A/B, Collapsed Spine, and Hybrid Cloud"}),"\n",(0,a.jsx)(t.p,{children:"A single top-of-rack switch failure on a non-redundant storage network drops every active mount, and the training jobs on it crash. The failure is not dramatic in the logs, which is why the redundancy has to be designed in before anything breaks. Storage availability therefore depends on path diversity across Fabric A and Fabric B. Two paths that share one power feed or one rack switch are not really two paths, so check what each path depends on, not only its name. If Fabric A fails or goes down for maintenance, Fabric B must carry 100% of the storage workload. It cannot lose IOPS, bandwidth, or latency while it does that. Picture a bridge that carries two lanes of traffic. When one lane closes, the other lane has to carry the full load, or the jam spreads back to every car on the road. Backend GPU training fabrics need strict 1:1 non-blocking bandwidth. Picture a road where every car can keep moving at full speed at the same moment, with no merge that slows anyone down. Training traffic is that kind of road, because every GPU sends at the same time in a synchronized step. You can see why a storage design differs from a training design. A training fabric is built for a short burst of perfectly timed traffic, while a storage fabric must stay calm through many uneven requests over a long day. Dedicated storage leaf-spine fabrics can run at 1:3 oversubscription instead, because storage flows are shorter and less synchronized than AllReduce collectives. A storage read is a single conversation between a client and an array, so the traffic arrives in waves rather than all at once."}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart TB\n  subgraph Phys["1. Physical Fab A / Fab B (Air-Gapped)"]\n    PA_Srv["AI Server<br/>NIC A & NIC B"] --\x3e PA_L1["Fab A Leaf 1<br/>& Spines A"]\n    PA_Srv --\x3e PA_L3["Fab B Leaf 3<br/>& Spines B"]\n    PA_L1 --\x3e PA_Arr["Storage Array<br/>Ctrl A & Ctrl B"]\n    PA_L3 --\x3e PA_Arr\n  end\n  subgraph Logi["2. Logical Fab A / Fab B (Shared Clos)"]\n    LA_Srv["AI Server<br/>NIC A & NIC B"] --\x3e LA_L12["Leaves 1-2<br/>EVPN RT5 / MAC-VRF"]\n    LA_L12 --\x3e LA_Sp["Shared Spines 1-4<br/>Dark/Light Underlay"]\n    LA_Sp --\x3e LA_L34["Leaves 3-4<br/>Storage Controllers"]\n  end\n  subgraph Coll["3. Collapsed & 4. Hybrid Cloud"]\n    CA_Srv["Edge / Inference Host<br/>NIC A & NIC B"] --\x3e CA_Sw["Back-to-Back<br/>Collapsed Leaves 1-2"]\n    CA_Sw --\x3e CA_Arr["Local NVMe Array<br/>+ Firewall / DCI"]\n    CA_Arr --\x3e CA_Cld["Cloud 1 & Cloud 2<br/>IPsec / HTTPS S3"]\n  end'}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Topology Pattern"}),(0,a.jsx)(t.th,{children:"Physical & Control-Plane Architecture"}),(0,a.jsx)(t.th,{children:"Oversubscription & Distance Rules"}),(0,a.jsx)(t.th,{children:"Best-Fit AI Use Case"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"1. Physical Fab A / Fab B Separation"})}),(0,a.jsx)(t.td,{children:"Two completely independent physical leaf-spine fabrics (Fabric A and Fabric B). NIC A connects only to Fab A ToR (Leaf 1), and NIC B connects only to Fab B ToR (Leaf 3). Storage array controllers mirror this physical split."}),(0,a.jsx)(t.td,{children:"Identical leaf-to-spine link counts and speeds on both fabrics (typically 1:3 oversubscribed) so failover preserves 100% capacity."}),(0,a.jsx)(t.td,{children:"Mission-critical enterprise and large-scale training clusters requiring blast-radius demarcation and hitless single-fabric upgrades."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"2. Logical Fab A / Fab B Separation"})}),(0,a.jsx)(t.td,{children:"A single physical 3-stage IP Clos (Leaves 1\u20134 full-mesh to Spines 1\u20134, at least 2 links per leaf-spine pair for ASIC local repair). L2 stays confined to each ToR; Fab A and Fab B are isolated via two EVPN-VXLAN Route Type 5 (RT5) IP-VRF instances or two MAC-VRF instances pinned to disjoint underlay paths."}),(0,a.jsx)(t.td,{children:"1:3 leaf-to-spine oversubscription is standard; multi-tenant managed training services isolate tenants via EVPN RT5 VXLAN tunnels across the shared storage underlay."}),(0,a.jsx)(t.td,{children:"Medium-scale or multi-tenant AI clusters seeking dual-path resilience without paying for two physical spine planes."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"3. Collapsed Fab A / Fab B Spine"})}),(0,a.jsx)(t.td,{children:"Just two switches (Leaf 1 and Leaf 2) connected back-to-back, with both AI servers (NIC A/NIC B) and storage targets dual-homed directly to the collapsed pair."}),(0,a.jsxs)(t.td,{children:["No spine tier; when replicating across sites over ",(0,a.jsx)(t.strong,{children:"40 km+"})," WAN/DCI links, use ",(0,a.jsx)(t.strong,{children:"deep-buffer Ethernet switches"})," and ",(0,a.jsx)(t.strong,{children:"NVMe-o-TCP"}),", avoiding long-haul lossless DCQCN/PFC."]}),(0,a.jsx)(t.td,{children:"Geographically distributed inference POPs, regional RAG caches, and compact edge pods."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"4. Hybrid On-Prem + Multi-Cloud Fabric"})}),(0,a.jsx)(t.td,{children:"Local Fab A / Fab B IP Clos (Leaves 1\u20134, Spines 1\u20134) extended via border leaves (Leaves 5\u20136), a firewall cluster, and dual DCI gateways to two public clouds (Cloud 1, Cloud 2)."}),(0,a.jsx)(t.td,{children:"On-premises hot data runs over NVMe-o-RDMA / parallel FS (Tier 1); cold checkpoints and multi-cloud backups traverse IPsec or TLS/HTTPS (S3 REST API, Tier 2)."}),(0,a.jsx)(t.td,{children:"Disaster recovery of expensive LLM training checkpoints and unified on-prem/cloud namespace tiering."})]})]})]}),"\n",(0,a.jsxs)(t.p,{children:["Each row describes a different answer to the same question: how do you keep storage alive when one path fails? Read the rows as four different insurance policies, each with its own premium and its own coverage. Physical separation gives the clearest blast-radius boundary, and ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," describes its cost as high. Logical separation keeps one physical fabric and isolates the two paths with EVPN-VXLAN overlays. Pick the topology that matches your scale and your tolerance for cost before you draw the first cable. A design that fits a single site can look very different once a second site joins it, so check the plan against the growth you expect."]}),"\n",(0,a.jsx)(t.h3,{id:"13-pcie-attached-drives-vs-network-attached-storage-latency-and-when-each-fits",children:"1.3 PCIe-Attached Drives vs Network-Attached Storage: Latency and When Each Fits"}),"\n",(0,a.jsx)(t.p,{children:"Every GPU server already has drives, so you might ask why a separate storage network is needed at all. The answer starts inside the server. Local drives sit on the PCIe bus, the same internal bus that carries the CPU and the network card. That layout works well for one machine. It cannot share one dataset across many servers at the same time."}),"\n",(0,a.jsx)(t.p,{children:"Picture two ways to hand a library to a team of readers. One way puts a copy of every book on every desk. The other keeps one shared shelf in the hall that everyone walks to. The two figures below show those two layouts for storage inside a server."}),"\n",(0,a.jsx)(t.p,{children:"Figure 9-1, labeled PCIe-connected SSD/HDD, shows this first design. A horizontal bar stands for the PCIe bus, which is peripheral component interconnect express. The central processing unit sits above the bus, and a network interface card sits below it. A line runs from that NIC to the data center local area network. On the right side of the bus, four cylindrical storage devices are labeled local hard disk drive or solid state drive. Every component connects to the bus, which shows that networking and storage share one internal connection inside the server."}),"\n",(0,a.jsx)(t.p,{children:"Figure 9-2, labeled network-connected SSD/HDD storage, shows the second design. A dedicated storage network interface card plugs into the PCIe bus and reaches a separate storage network. That network connects to disk arrays. In both designs, the server keeps a central processing unit and a LAN data center NIC as standard parts. Think of the LAN NIC as the front door that serves users and the cluster's management tools. The storage path is the loading dock beside it, and the two should not share the same door. That LAN is the frontend part of an AI data center."}),"\n",(0,a.jsx)(t.p,{children:"From the application's point of view, reads and writes work the same way in both designs. The difference is distance. A PCIe-attached SSD reaches its local array in about 100 nanoseconds on generation 5. A network-attached array adds about 300 nanoseconds through an InfiniBand switch, or about 800 nanoseconds through an Ethernet switch. When you compare the two, the application sees the same reads and writes, so only the timing changes. That is good news for software, because a storage change does not require a code change, only a new set of timings to plan around."}),"\n",(0,a.jsx)(t.p,{children:"Suppose a team worries that an extra switch hop will slow every read in a training job. The arithmetic below answers that worry, and it shows why the hop is smaller than it first looks."}),"\n",(0,a.jsx)(t.p,{children:"Those few hundred nanoseconds matter less than they seem. When the network is only one to three hops away, and each switch adds only nanoseconds, IOPS can come close to PCIe-attached storage. A port-to-port switch latency of 700 to 900 nanoseconds still delivers high bus bandwidth for reads and writes. Latency and bandwidth are different measures. A long pipe can still carry a lot of water, even when the first drop takes a moment to arrive."}),"\n",(0,a.jsx)(t.p,{children:"In AI training, both types are often used together. A typical pattern keeps hot data on local flash for speed and uses the shared file system for the copy that every node must see. Think of the local drive as a personal notebook and the shared file system as the team's common binder. Local storage can run a file system that is backed by an NVMe-oF system. Parallel file systems let many nodes share the same files, and they keep extra metadata. That metadata helps during training and when regular snapshots of a training job are taken. If you run both, you need to know where each file lives."}),"\n",(0,a.jsxs)(t.p,{children:["Putting the front-end LAN to work for storage would cut infrastructure cost. ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," notes that AI data centers rarely do this. The reason is practical: a storage burst on the same LAN can slow the users and the services that share it. They deploy dedicated front-end and backend storage systems and storage networks instead. Keep the LAN for users, and give training data its own network."]}),"\n",(0,a.jsx)(t.h3,{id:"14-checkpoints-and-fast-writes-during-training",children:"1.4 Checkpoints and Fast Writes During Training"}),"\n",(0,a.jsx)(t.p,{children:"Training is the phase where storage most often becomes the bottleneck. It follows the data preparation phase, and it is the stage where you must save and restore model checkpoints. A checkpoint is a snapshot of the model's weights and optimizer state, so a restore brings the training run back to a known point after a failure. Those saves and restores have to be designed on purpose. A checkpoint that nobody planned for tends to land in the middle of the busiest hour, and then it costs the most. A good checkpoint system protects the training investment already made, and it keeps GPUs free for new jobs."}),"\n",(0,a.jsx)(t.p,{children:"Picture a checkpoint save that pauses every GPU in a large job while the write finishes. Each second of that pause is a second the cluster is paid for and not training. That is why the storage path has to be designed as carefully as the compute path."}),"\n",(0,a.jsx)(t.p,{children:"Storage work should not steal time from the GPUs. As you plan a cluster, keep the storage path off the GPU's critical path. A dedicated data storage system keeps those storage tasks off the GPU path. An efficient storage system in the backend network offers quicker access, so it shortens the time needed to save checkpoint data. Shorter saves reduce how often training pauses and how long each pause lasts. Pauses hold back progress, so keep their frequency and duration low. A short save every hour is easier to live with than a long save every ten minutes, even when both add up to the same total time. Fast-write storage is therefore a core part of cluster efficiency, not an extra. A slow save is a tax that the whole job pays every time it runs, and a fast save is a rebate that returns that time to the GPUs."}),"\n",(0,a.jsx)(t.h3,{id:"15-redundancy-path-diversity-and-inter-site-replication",children:"1.5 Redundancy, Path Diversity, and Inter-Site Replication"}),"\n",(0,a.jsx)(t.p,{children:"Suppose a switch in the storage rack reboots in the middle of a checkpoint. If the design has only one path, the save fails and the job may need to roll back. If the design has two paths, the save continues on the other path, and nobody notices the reboot."}),"\n",(0,a.jsx)(t.p,{children:"Storage needs the same care as the compute network. Each storage network must offer node and link redundancy. Active storage A and backup storage B should form two paths to the same data. If path A fails, path B must carry the full load without losing IOPS, bandwidth, or latency. This is called path diversity. Think of it as having two roads to the same town, so a closed road does not cut the town off. When you audit a design, check each path on its own. Ask what happens to the load when that path is gone, and whether the other path can carry it without losing any of the three measures."}),"\n",(0,a.jsx)(t.p,{children:"Replication across sites follows the same rule. A copy in a second building is only useful if it is current, and a copy that lags behind the primary can lose the last hours of training. Plan the replication lag as carefully as the path itself. Both storage domains need local site-level redundancy, plus inter-site replication after each read or write. Inter-site traffic often uses a different transport. When Fibre Channel storage runs inside a site, Fibre Channel over IP, or FCoIP, is a common choice for replication. Dedicated site-to-site replication gateways still play a role."}),"\n",(0,a.jsx)(t.p,{children:"When a design uses NFS instead of a SAN, one disaster recovery design can cover both the application and the storage. A SAN is a separate block network, so it usually needs its own recovery plan, while an NFS share travels with the same network that the applications already use. Inter-site data redundancy can then ride on the same data center interconnect link as the applications. If the site already runs RoCEv2 for storage, inter-site RDMA is the usual replication method. Lossless inter-site RDMA is rare, though. If you plan that link, budget time for the extra care it needs. Keeping DCQCN working over a link of 40 km or more is hard. The control loop depends on feedback that arrives quickly, and a long link delays that feedback until the reaction comes too late to help."}),"\n",(0,a.jsx)(t.p,{children:"Long-distance replication is harder than local replication because every extra kilometer adds delay. Lossless transports depend on tight timing, so they become fragile over long links. A transport that tolerates loss and delay is easier to keep running across a city or a region."}),"\n",(0,a.jsx)(t.p,{children:"NVMe over TCP takes a different path for long-distance replication. It can run on a lossy IP core network. It does not engage DCQCN pushback mechanisms such as Priority Flow Control, or PFC. Instead, it adapts to network conditions. It uses reliable transport, and its maximum segment size, or MSS, requirements are more adaptable and less restrictive than those of the training cluster storage. That is why many teams choose it for distant copies."}),"\n",(0,a.jsx)(t.h3,{id:"16-logical-fab-ab-with-evpn-vxlan-overlays",children:"1.6 Logical Fab A/B With EVPN-VXLAN Overlays"}),"\n",(0,a.jsx)(t.p,{children:"Imagine a building with two sets of elevators that serve the same floors. If one set stops, the other set keeps people moving, but the building pays for both. The physical split works the same way, which is why the logical version exists."}),"\n",(0,a.jsx)(t.p,{children:"Physical separation uses two independent sets of switches, and the cost is high. Logical separation keeps one physical fabric and splits it into two paths. In a physical design, each ToR switch connects to only NIC A or only NIC B. In a logical design, leaves 1 and 2 carry separate dark and light gray fabric connections. The storage SSD controllers follow the same split, either physically or logically. When you draw the design, show both versions on one page so the difference is visible. A reviewer who sees the two drawings side by side can spot a shared failure point in seconds, while a single drawing hides it."}),"\n",(0,a.jsx)(t.p,{children:"Logical separation usually runs an EVPN-VXLAN overlay. An overlay is a set of tunnels that ride on top of the existing physical network, so each tunnel behaves like its own private road even though the cars share the same pavement. Fabric A and fabric B control traffic can use two separate RT5 EVPN instances. Think of each instance as a separate routing table that lives inside the shared fabric. Each table knows only its own routes, so traffic on one path does not leak into the other. The same bridging domain can also carry two separate MAC-VRF instances. Each instance gets its own IP address at the VXLAN tunnel termination point, and a separate underlay path carries each one. Replication between sites can use the same idea, with a Path A and a Path B through controlled overlay-to-underlay paths."}),"\n",(0,a.jsx)(t.h3,{id:"17-hot-and-cold-data-across-on-premises-storage-and-object-storage",children:"1.7 Hot and Cold Data Across On-Premises Storage and Object Storage"}),"\n",(0,a.jsx)(t.p,{children:"Think about a dataset your team read every day last month and then did not touch once this month. Its value to the training run did not change, but its place in the storage hierarchy should."}),"\n",(0,a.jsx)(t.p,{children:"Not all data is accessed the same way, so storage designs usually split it into hot data and cold data. In a hybrid design, hot data stays on on-premises backend servers. Those servers connect to a storage IP fabric or an InfiniBand fabric. Cold data sits off-premises in object storage. You decide which tier a dataset belongs in by how often you read it."}),"\n",(0,a.jsx)(t.p,{children:"Picture an ML developer who writes the same training script for a local dataset and for one stored in the cloud. The script should not need two versions. The storage layer must make the two locations look alike to the code."}),"\n",(0,a.jsx)(t.p,{children:"Applications reach both tiers with S3 calls over an HTTPS API. In hybrid deployments, that means TLS over HTTP using the S3 REST API. A framework such as TensorFlow or PyTorch still uses plain POSIX file calls. The parallel file system understands those calls. It moves files between the fast local SSD flash tier, which uses NVMe-o-PCIe, and a scale-optimized tier in the cloud. The ML developer does not need to change the code. For example, a training script keeps the same POSIX calls whichever tier holds the file."}),"\n",(0,a.jsx)(t.p,{children:"Figure 9-8 shows a hybrid layout. Each AI server has two storage network interface cards. Card A connects to leaf1 and card B connects to leaf2, so a failed leaf does not cut the server off from storage. Both connections carry reads and writes."}),"\n",(0,a.jsx)(t.p,{children:"On the on-premises side, Fabric A holds leaves 1 and 2 and connects to spines 1 and 2. Fabric B holds spines 3 and 4, with leaves 3 and 4 leading to the storage arrays. Leaves 5 and 6 reach a firewall cluster, and two data center gateways connect on to cloud1 and cloud2 storage. Replication to the cloud keeps snapshots of the local training cluster from being lost. If the building that holds the arrays is damaged, the cloud copy is the one that lets the team restart the job. That is the business reason for the extra cost of the cloud path."}),"\n",(0,a.jsxs)(t.p,{children:["The cloud path is not the same as the local path. Every request to the cloud has a longer trip, a tunnel to build, and a bill attached. Treat the cloud copy as a backup and an archive, not as the place where the training job reads its batches. Access goes through the firewall cluster, so an extra security tunnel is needed. ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," names IPsec or HTTPS for that tunnel. Plan for that extra layer before you rely on the cloud copy."]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"2-nvme-of-state-machines-nvme-o-tcp-vs-nvme-o-rdma-parallel-file-systems-and-infiniband-storage",children:"2. NVMe-oF State Machines (NVMe-o-TCP vs NVMe-o-RDMA), Parallel File Systems, and InfiniBand Storage"}),"\n",(0,a.jsx)(t.h3,{id:"21-nvme-of-architecture-queues-capsules-nsid-and-prp-vs-sgl",children:"2.1 NVMe-oF Architecture: Queues, Capsules, NSID, and PRP vs SGL"}),"\n",(0,a.jsx)(t.p,{children:"Picture a database server whose local drives are full, while a second team wants the same data on a shared array. The question is whether the shared array can feel as fast as the local drive. NVMe-oF is the answer the industry built, and the parts below explain how it keeps the NVMe behavior while crossing a network."}),"\n",(0,a.jsx)(t.p,{children:"Local NVMe SSDs are fast because the host talks to them directly over PCIe, using circular Submission Queues and Completion Queues. The catch is that those local queues cannot cross an Ethernet or InfiniBand switch. NVMe over Fabrics keeps the NVMe base specification, the I/O command sets, the management interface, and the queue semantics. Only the transport changes. The PCIe bus gives way to a network binding such as NVMe-o-TCP, NVMe-o-RDMA, or NVMe-o-FC."}),"\n",(0,a.jsx)(t.p,{children:"NVMe-oF wraps each command and response in a network unit called a capsule. Two kinds of capsule carry most of the traffic. Think of a capsule as a sealed envelope that travels through the network. The command envelope goes out with the request, and the response envelope comes back with the answer. Each envelope carries the same identifier, so the two halves of one operation can be matched later."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Command Capsule:"})," Sent from the host initiator to the target controller. It carries a 64-byte Submission Queue Entry plus optional in-capsule write data."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Response Capsule:"})," Sent from the target controller back to the host initiator. It carries a 16-byte Completion Queue Entry that reports the status for the matching Command ID."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"The two addressing constructs can look similar in a capture, so it helps to picture them as two different labels on one parcel. One label says which room the parcel belongs in. The other label says where the contents sit inside the parcel. Both labels travel with every read and write, and both have to be read correctly."}),"\n",(0,a.jsxs)(t.p,{children:["Every NVMe-oF read (",(0,a.jsx)(t.code,{children:"opcode 0x02"}),") or write (",(0,a.jsx)(t.code,{children:"opcode 0x01"}),") command carries two addressing constructs. They do different jobs, and mixing them up is a common source of confusion. When you read a capture, check which one you are looking at before you draw a conclusion. A quick look at the opcode and the field names usually settles the question, and it saves you from debugging the wrong layer."]}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"NSID:"})," The Namespace Identifier selects the logical storage volume or partition that the remote NVMe target exposes. One flash array controller can expose several NSIDs, each with its own capacity, block size, or tenant permissions."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"PRP1 and PRP2 vs SGL:"})," These descriptors tell the controller where the data lives in host or GPU BAR1 memory. DMA places read data there, or fetches write data from there. PRP1 and PRP2 are two 64-bit Physical Region Page pointers. PRP1 points to the first memory page, and PRP2 points to the second page or to a PRP list. A Scatter-Gather List, or SGL, describes several non-contiguous memory segments inside one 64-byte NVMe command header. SGL is the preferred choice for network fabrics."]}),"\n"]}),"\n",(0,a.jsx)(t.h3,{id:"22-nvme-o-tcp-state-machine-pdus-and-jumbo-frame-packing",children:"2.2 NVMe-o-TCP State Machine, PDUs, and Jumbo-Frame Packing"}),"\n",(0,a.jsx)(t.p,{children:"Suppose a storage team wants one shared volume across a building, and the network team says the fabric is not tuned for PFC pauses. NVMe-o-TCP is the transport built for that situation. It accepts some loss and delay in exchange for simpler network rules."}),"\n",(0,a.jsx)(t.p,{children:"Operators choose NVMe-o-TCP when they need shared NVMe block storage over a lossy IP network, or over a link of 40 km or more, without tuning PFC. Each CPU core on the host opens its own TCP connection, and each connection maps 1:1 to a target queue pair. All of these connections use destination TCP port 8009. If you tune a host, count those connections per core. A host with many cores opens many connections, and each connection needs queue depth on the target. A setting that works on a small host can overwhelm the array when the same setting runs on a large one."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"NVMe-o-TCP Protocol Data Unit (PDU) Types, Opcodes, and MTU 9000 Packing Math:\n- Destination transport port: TCP port 8009\n- Capsule / Data PDU Type Codes:\n  0x01 = CapsuleCmd (Host-to-controller command capsule carrying 64B SQE: Command ID, opcode, NSID, length, PRP1/PRP2 or SGL)\n  0x02 = CapsuleResp (Controller-to-host response capsule carrying 16B CQE)\n  0x03 = H2CData (Host-to-controller off-capsule write data PDU)\n  0x04 = C2HData (Controller-to-host read data PDU)\n- NVMe I/O Opcodes:\n  opcode 0x01 = Write (supports in-capsule write with SQE + Data + LAST-PDU flag, or off-capsule write with H2CData 0x03 PDUs)\n  opcode 0x02 = Read (CapsuleCmd 0x01 -> sequential C2HData 0x04 PDUs #1..#N -> CapsuleResp 0x02)\n- Ordered NVMe-o-TCP PDU Framing Fields:\n  Common Header (CH) -> PDU-Specific Header (PSH) -> Header Digest (HDGST) -> Padding (PAD) -> PDU Data (Capsule/Payload) -> Data Digest (DDGST)\n- Jumbo-Frame MTU 9000 Multi-PDU Packing:\n  Single 4 KiB (4,096B) in-capsule write PDU = 24B (CH+PSH) + 4B (HDGST) + 64B (SQE) + 4,096B (Data) + 4B (DDGST) = 4,192 bytes\n  At MTU 9000 (TCP MSS = 8,960 bytes), 2 PDUs = 2 x 4,192B = 8,384 bytes fit inside 1 TCP segment with 576 bytes remaining\n"})}),"\n",(0,a.jsx)(t.p,{children:"The packing math is easier to follow as a worked example. One 4 KiB in-capsule write PDU is 4,192 bytes. That total comes from 24 bytes of common and PDU-specific headers, 4 bytes of header digest, the 64-byte SQE, 4,096 bytes of data, and 4 bytes of data digest. At MTU 9000, the TCP MSS is 8,960 bytes. Two of those PDUs take 8,384 bytes, which leaves 576 bytes of the segment unused. Consider working the arithmetic once yourself, so the packing rules make sense. The lesson is that headers are not free. Each PDU carries a fixed set of bytes before the first byte of data, and a small write pays that overhead as a larger share of its size. Packing two PDUs into one segment is a way to share the cost of the wire between them."}),"\n",(0,a.jsx)(t.p,{children:"The session then moves through five stages, and each stage must finish before the next one starts. Think of the stages as the steps of a phone call. You dial, the other side answers, you identify yourself, you talk, and then you hang up. If the line drops, the call stops at the step that failed. If your session stops, you can tell which stage you reached."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"TCP and optional TLS handshake:"})," The host initiator completes a standard ",(0,a.jsx)(t.code,{children:"TCP SYN -> SYN-ACK -> ACK"})," handshake to target port 8009. An optional TLS handshake follows when the storage must be encrypted."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"ICReq and ICResp PDUs:"})," The host sends an ",(0,a.jsx)(t.code,{children:"NVMe/TCP ICReq PDU"})," that advertises its NVMe version and the digest flags ",(0,a.jsx)(t.code,{children:"HDGST"})," and ",(0,a.jsx)(t.code,{children:"DDGST"}),". It also sends the PDU data alignment and host identifier fields. The controller answers with an ",(0,a.jsx)(t.code,{children:"ICResp PDU"}),"."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"NVMe/TCP Connect request and response:"})," The host binds the TCP connection to a specific Controller ID. It then negotiates the Admin or I/O queue IDs (",(0,a.jsx)(t.code,{children:"QID"}),") and the queue depth."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Data transfer and jumbo-frame packing:"})," The session exchanges ",(0,a.jsx)(t.code,{children:"CapsuleCmd"}),", ",(0,a.jsx)(t.code,{children:"H2CData"}),", ",(0,a.jsx)(t.code,{children:"C2HData"}),", and ",(0,a.jsx)(t.code,{children:"CapsuleResp"})," PDUs. On a storage IP fabric with jumbo frames at ",(0,a.jsx)(t.code,{children:"MTU 9000"}),", one TCP segment can carry two or more NVMe-o-TCP PDUs back to back."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Session termination:"})," Either endpoint sends ",(0,a.jsx)(t.code,{children:"H2CTermReq"})," or ",(0,a.jsx)(t.code,{children:"C2HTermReq"}),", followed by a final ",(0,a.jsx)(t.code,{children:"CapsuleResp"})," CQE status. This releases the NSID, the Command IDs, and the queue bindings before the TCP socket closes."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"If you plan to rely on the packing, verify MTU 9000 on every hop of the storage path first. A single hop that still uses the default frame size breaks the packing for every session that crosses it, and the failure looks like a slow array rather than a configuration error."}),"\n",(0,a.jsx)(t.h3,{id:"23-nvme-o-rdma-rocev2-state-machine-tcp-8009---udp-4420---udp-4791",children:"2.3 NVMe-o-RDMA (RoCEv2) State Machine: TCP 8009 -> UDP 4420 -> UDP 4791"}),"\n",(0,a.jsx)(t.p,{children:"Training clusters can reach a point where TCP processing burns too much CPU and adds tail latency. NVMe-o-RDMA moves the storage transport into the NIC's RDMA engine instead. It delivers up to 66% lower write latency, and it lets GPUDirect Storage DMA straight into GPU HBM. Over a lossless RoCEv2 fabric, the session passes through three ports and two protocols. If a firewall blocks any one of those three ports, session bring-up stalls partway through. If you see a stall, check the three ports before you blame the storage array. A stall at discovery points to TCP 8009, a stall during the RDMA handshake points to UDP 4420, and a stall during data transfer points to UDP 4791."}),"\n",(0,a.jsx)(t.mermaid,{value:"sequenceDiagram\n  autonumber\n  participant Host as Initiator Host (NIC RDMA + NVMe)\n  participant Target as Target Controller (NVMe Array)\n  Note over Host,Target: Phase 1: Discovery over TCP Port 8009\n  Host->>Target: TCP 8009: Get Log Page (Discovery Log)\n  Target--\x3e>Host: Discovery Log (RDMA_PRTYPE: 04=RoCEv2, 02=IB, 05=iWARP)\n  Note over Host,Target: Phase 2: RDMA Connection Management over UDP Port 4420\n  Host->>Target: UDP 4420: RDMA_CM_REQUEST (Negotiate QPairs)\n  Target--\x3e>Host: UDP 4420: RDMA_CM_REPLY\n  Host->>Target: UDP 4420: RDMA_CM_RTU (QP Ready / RTS State)\n  Note over Host,Target: Phase 3: NVMe Queue & Data Plane over UDP Port 4791\n  Host->>Target: UDP 4791 (BTH+IB): NVMe RDMA Connect Capsule (RDMA_SEND)\n  Target--\x3e>Host: UDP 4791: NVMe Connect Response\n  Host->>Target: UDP 4791: NVMe IO Queue Create (1:1 SQ/CQ to QPair)\n  Target--\x3e>Host: UDP 4791: NVMe Queue Response\n  Host->>Target: UDP 4791: NVM CMD Capsule (NSID, CmdID, SGL) via RDMA_SEND\n  Target->>Host: UDP 4791 (BTH+RETH): Controller-initiated RDMA_READ / RDMA_WRITE\n  Target--\x3e>Host: UDP 4791: NVMe Response Capsule (CQE)"}),"\n",(0,a.jsx)(t.p,{children:"Read the table phase by phase. Each phase depends on the one before it, so a blocked port at any step stops the session at that step. Think of the phases as the checkpoints on a route, where a closed gate at one checkpoint stops everyone behind it. Each phase depends on the one before it, so a blocked port at any step stops the session at that step. You can use the phases as a checklist while you debug the session."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Phase"}),(0,a.jsx)(t.th,{children:"Protocol & Destination Port"}),(0,a.jsx)(t.th,{children:"Key Header Fields & State Transitions"}),(0,a.jsx)(t.th,{children:"Architectural Rules"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"1. Discovery Phase"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"TCP Port 8009"})}),(0,a.jsxs)(t.td,{children:["Host issues ",(0,a.jsx)(t.code,{children:"Get Log Page \u2013 Discovery Log Pages"}),". Target returns ",(0,a.jsx)(t.code,{children:"RDMA_PRTYPE"}),": ",(0,a.jsx)(t.strong,{children:"04"})," (0x04 RoCEv2), ",(0,a.jsx)(t.strong,{children:"02"})," (0x02 InfiniBand), or ",(0,a.jsx)(t.strong,{children:"05"})," (0x05 iWARP)."]}),(0,a.jsx)(t.td,{children:"Standard NVMe-oF Discovery Controller runs over TCP 8009 before any UDP/RDMA packet is sent."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"2. RDMA CM Handshake"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"UDP Port 4420"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.code,{children:"RDMA_CM_REQUEST"})," -> ",(0,a.jsx)(t.code,{children:"RDMA_CM_REPLY"})," -> ",(0,a.jsx)(t.code,{children:"RDMA_CM_RTU"})," (Ready to Use), transitioning the RDMA QPair into RTS (Ready to Send)."]}),(0,a.jsx)(t.td,{children:"No NVMe capsules can be exchanged until both endpoints' RDMA QPs reach RTS."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"3. NVMe Connect & I/O Data Plane"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"UDP Port 4791"})," (RoCEv2)"]}),(0,a.jsxs)(t.td,{children:["Outer ",(0,a.jsx)(t.code,{children:"Ethernet -> IP -> UDP (4791) -> BTH (Opcode, Dest QPair) -> RETH (VA, RKey, DMA Length) -> NVM CMD QID + NVM CMD (NSID, CmdID, SGL)"}),"."]}),(0,a.jsxs)(t.td,{children:["Strict ",(0,a.jsx)(t.strong,{children:"1:1 mapping"})," between one I/O SQ/CQ pair and one RDMA QPair. Host sends command capsules via ",(0,a.jsx)(t.code,{children:"RDMA_SEND"}),"; ",(0,a.jsxs)(t.strong,{children:["all ",(0,a.jsx)(t.code,{children:"RDMA_READ"})," and ",(0,a.jsx)(t.code,{children:"RDMA_WRITE"})," bulk transfers are initiated by the target controller"]}),"."]})]})]})]}),"\n",(0,a.jsx)(t.h3,{id:"24-high-performance-parallel-file-systems-and-gpudirect-storage-integration",children:"2.4 High-Performance Parallel File Systems and GPUDirect Storage Integration"}),"\n",(0,a.jsx)(t.p,{children:"Picture ten training nodes that all open the same dataset folder at the same moment. A block volume alone cannot tell them which files belong to whom, because each host sees only its own session. That coordination is the job of a file layer on top."}),"\n",(0,a.jsx)(t.p,{children:"Raw NVMe-oF block volumes give each host a 1:1 session to a target namespace. They do not coordinate file metadata across many GPU clients at once. A shared POSIX namespace at high speed therefore needs a parallel file system layered on top of NVMe-o-RDMA. Common choices include WekaFS, VAST, Lustre, GPFS, and BeeGFS, running over RoCEv2 or InfiniBand."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Parallel File System Striping and GPUDirect Storage (GDS) Parameters:\n- Parallel file systems: WekaFS, VAST, Lustre, GPFS (IBM Storage Scale), BeeGFS\n- WekaFS striping: distributes file data and metadata across all on-premises NVMe storage servers (Servers 1..8)\n- Standard AI file extensions & POSIX syscalls: .pt, .npy, .ckpt, .h5, .bin via open(), read(), write(), stat(), unlink()\n- Two-tier storage hierarchy: Tier 1 hot flash over RDMA (RoCEv2 / InfiniBand) + Tier 2 cold snapshots over HTTPS/TLS S3 REST APIs; VAST runs multipath NFS over RDMA\n- GPUDirect Storage (GDS) zero-copy pipeline (PyTorch v2.7.0+):\n  cudaMalloc -> cuFileBufRegister -> PIN to direct IO -> PCIe DMA directly between external RoCEv2/IB arrays and GPU 1..8 HBM via NIC A and NIC B (100G/200G or 400G/800G) bypassing host CPU and system DRAM\n"})}),"\n",(0,a.jsx)(t.p,{children:"Two parts of this stack are worth understanding before you tune anything. Both of them change what the file system does with a single read, so a change to either one can move the performance in ways you do not expect. The first is how the file system spreads data out. For example, a shared training dataset is a case for the file layer."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Parallel data and metadata striping:"})," Rather than funnel every client through one NFS gateway, WekaFS spreads both file data and metadata in small chunks across all on-premises NVMe storage servers. When PyTorch or TensorFlow reads checkpoint files through POSIX syscalls, the local client turns each call into parallel RDMA requests against Tier 1 hot flash. Cold snapshots move to Tier 2 cloud object storage over HTTPS S3 REST APIs."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"GPUDirect Storage zero-copy DMA:"})," When PyTorch or the CUDA runtime allocates GPU memory with ",(0,a.jsx)(t.code,{children:"cudaMalloc"})," and registers it with ",(0,a.jsx)(t.code,{children:"cuFileBufRegister"}),", the GPU memory pages are pinned for direct I/O. The GDS library then programs the storage NIC driver directly over PCIe. Blocks move between the external arrays and GPU HBM through the dedicated storage NICs, without bouncing through host CPU cores or system DRAM."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Use a parallel file system when many GPU clients need the same files. Use raw NVMe-oF volumes when each session needs its own namespace. Think of a shared file system as a library with one catalog that everyone uses, and a raw volume as a private locker that only one person opens."}),"\n",(0,a.jsx)(t.h3,{id:"25-infiniband-for-storage-16-bit-lid-48000-nodes-frame-format-and-64b-cbfc-credits",children:"2.5 InfiniBand for Storage: 16-Bit LID (48,000 Nodes), Frame Format, and 64B CBFC Credits"}),"\n",(0,a.jsx)(t.p,{children:"Suppose a storage team plans a native InfiniBand array next to a RoCEv2 array, and someone asks why the frames look so different on the wire. The answer is that the InfiniBand frame drops the Ethernet envelope and keeps the same storage conversation inside it."}),"\n",(0,a.jsx)(t.p,{children:"When native InfiniBand carries NVMe-o-RDMA and GPUDirect Storage, the RDMA handshake and the NVMe capsule payload look the same as they do on RoCEv2. The difference is the frame. The outer Ethernet, IP, and UDP headers give way to the native InfiniBand frame. That removes the L3 and L4 header overhead, and it cuts switch latency to roughly 300 ns."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Native InfiniBand Storage Frame Header Pipeline:\nLRH (S-LID, D-LID, VL) -> GRH (Optional Inter-Subnet) -> BTH (Opcode, Dest QP) -> ETH (Src QP / RDMA) -> NVMe-o-RDMA Capsule + Data -> ICRC + VCRC\n"})}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Native InfiniBand Storage Addressing, Integrity, and Flow Control Specs:\n- Local Routing Header (LRH) addressing: 16-bit Local Identifier (LID, 65,536 total values) assigned by the Subnet Manager (SM) via per-switch Subnet Manager Agents (SMAs)\n- Single-subnet node limit: up to 48,000 end nodes per InfiniBand subnet (e.g., 32,000 nodes fit in one subnet; 60,000 nodes require inter-subnet routing via the Global Routing Header GRH)\n- Frame CRCs: Invariant CRC (ICRC, end-to-end immutable fields) + Variant CRC (VCRC, hop-by-hop link fields)\n- Virtual Lanes (VLs) and Credit-Based Flow Control (CBFC): up to 16 VLs per physical link (typically 8-12 active data VLs); 1 CBFC credit in the Link Layer Header (LLH) = 64 bytes of buffer space (64 credits required for a 4,096-byte storage block); 10 km optical spec reach\n"})}),"\n",(0,a.jsx)(t.p,{children:"The numbers in that block make two checks easy. You can verify the subnet size against the node count on a whiteboard, and you can verify the credit count on the back of an envelope. Those quick checks catch design mistakes before anyone orders hardware. A 32,000-node cluster fits inside one subnet. A 60,000-node cluster is above the 48,000-node limit, so it needs inter-subnet routing through the GRH. For the flow control side, one credit covers 64 bytes of buffer space. A 4,096-byte block therefore needs 4,096 divided by 64, or 64 credits. You can repeat that division for any block size you plan to store."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Storage Option"}),(0,a.jsx)(t.th,{children:"(P)NFS / Parallel FS"}),(0,a.jsx)(t.th,{children:"NVMe-o-TCP"}),(0,a.jsx)(t.th,{children:"NVMe-o-RDMA (RoCEv2)"}),(0,a.jsx)(t.th,{children:"Native InfiniBand Storage"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Training & Inference Fit"})}),(0,a.jsx)(t.td,{children:"Training + Inference"}),(0,a.jsx)(t.td,{children:"Inference + Cold/Tier-2 Training"}),(0,a.jsx)(t.td,{children:"Training + Inference"}),(0,a.jsx)(t.td,{children:"Training (legacy/HPC + NVIDIA pods)"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Parallel Shared File Access"})}),(0,a.jsx)(t.td,{children:"Yes (POSIX / NFS)"}),(0,a.jsx)(t.td,{children:"Yes (when layered with FS)"}),(0,a.jsx)(t.td,{children:"Block-level (1:1 QP, needs PFS for shared files)"}),(0,a.jsx)(t.td,{children:"Block or File (Lustre/GPFS/Weka over IB)"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Switch Port-to-Port Latency"})}),(0,a.jsx)(t.td,{children:"~700\u2013900 ns (Ethernet)"}),(0,a.jsx)(t.td,{children:"~700\u2013900 ns (Ethernet)"}),(0,a.jsx)(t.td,{children:"~700\u2013900 ns (Ethernet)"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"~300 ns"})," (InfiniBand switch)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Requires Lossless Fabric"})}),(0,a.jsx)(t.td,{children:"No (unless over RDMA)"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"No"})," (runs on lossy IP)"]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Yes"})," (PFC + ECN + DCQCN)"]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Yes"})," (native 16 VLs + 64B CBFC)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Built-in Transport Reliability"})}),(0,a.jsx)(t.td,{children:"Via TCP or RDMA"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Yes"})," (standard TCP)"]}),(0,a.jsx)(t.td,{children:"Via NIC RDMA QP state machine"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Yes"})," (hardware HCA + CBFC)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Port Speeds & Multi-Vendor Scale"})}),(0,a.jsx)(t.td,{children:"400G/800G/1.6T; High multi-vendor"}),(0,a.jsx)(t.td,{children:"400G/800G/1.6T; High multi-vendor"}),(0,a.jsx)(t.td,{children:"400G/800G/1.6T; High multi-vendor"}),(0,a.jsx)(t.td,{children:"400G/800G/1.6T; Single-vendor (<48,000 nodes/subnet)"})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"The table makes the trade-off visible. Each column answers a planning question: what kind of training or inference it fits, whether it needs a lossless fabric, and whether it can share files. Read the switch latency row and the lossless row side by side, because they explain most of the cost difference. Native InfiniBand has the lowest switch latency, but it stays single-vendor and needs a lossless fabric. NVMe-o-TCP is the only option that does not need a lossless fabric. Before you pick InfiniBand for a storage fabric, check the planned subnet size against the 48,000-node limit."}),"\n",(0,a.jsx)(t.h3,{id:"26-gpudirect-storage-logical-view-and-cuda-api-orchestration",children:"2.6 GPUDirect Storage: Logical View and CUDA API Orchestration"}),"\n",(0,a.jsx)(t.p,{children:"Picture a checkpoint that must leave the GPUs, cross the server, and land on an array. Each extra copy on that trip costs time, and it also taxes the host CPU that has to run the copy. GPUDirect Storage is the feature that removes those copies from the path."}),"\n",(0,a.jsxs)(t.p,{children:["GPUDirect Storage lets a GPU place data straight onto storage arrays. The usual path makes the CPU copy every byte. GDS skips that copy. ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," describes the result as less jitter, much better bus bandwidth, and much lower CPU load. It also means fewer competing connections on each server. For you as an operator, that means a quieter host."]}),"\n",(0,a.jsx)(t.p,{children:"Figure 9-19 gives the logical view. The top section shows a server chassis labeled PCIe. Inside it, a central processing unit and system memory connect over the PCIe bus. Below them sit eight graphics processing units, GPU1 through GPU8, so the chassis holds a CPU, system memory, and eight GPUs. Each GPU has its own NIC, and each NIC connects to its own leaf switch. Eight spine switches form a full mesh with those leaves, and each leaf links to every spine in both directions. Two more dedicated NICs, NICA and NICB, connect the server to a ROCEv2 Storage cloud and to external storage arrays. Their arrows show two-way traffic, while each GPU NIC sends over a unidirectional link to its leaf. The GPUs place their outputs over the RoCEv2 NICs without interrupting the CPU core. Trace the figure from the GPU NICs to the leaves, and you will see every hop."}),"\n",(0,a.jsxs)(t.p,{children:["That design relaxes the demand on system memory. Think of system memory as a shared kitchen counter. If every ingredient must be set down there first, the cooks wait for counter space. With direct placement, the ingredients go straight to the cook's station, and the counter stays clear for other work. After the direct placement, the GPU can start its next task. The server does not need a large multi-core CPU or costly local memory to do it. ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," notes that this matters little in a small cluster. At 100,000 GPUs or more, the saving can have a large cost impact."]}),"\n",(0,a.jsxs)(t.p,{children:["GDS is also built into the CUDA API. A developer who calls the API does not need to write the NIC driver code, because the library handles that layer. The developer's job is to register the buffer and to keep the calls in the right order. CUDA is NVIDIA's parallel computing platform and programming interface. In Figure 9-20, a block labeled CUDA API sits at the top. An arrow labeled ",(0,a.jsx)(t.code,{children:"cudaMalloc"})," and ",(0,a.jsx)(t.code,{children:"cuFileBufRegister"})," leads to a block called GPU Memory, which shows that buffers are allocated and registered. From GPU Memory, an arrow labeled ",(0,a.jsx)(t.code,{children:"PIN to direct IO"})," leads to GDS. The GDS block then hands off to a storage NIC. A traditional path from GPU memory through PCIe also reaches that NIC. From the storage NIC, RoCEv2 carries traffic to the storage arrays. A feedback loop curves from the storage NIC back up to the CUDA API, which shows control or signaling. A second arrow curves back down to GDS, which shows return control or data flow."]}),"\n",(0,a.jsxs)(t.p,{children:["The CUDA layer sets up the NIC driver for the RoCEv2 or InfiniBand transfer. In practice, that means the framework asks for a registered buffer once, and the transfers then reuse it without touching the CPU for every byte. It does that without using a CPU core or any other system memory. When you read a GDS trace, expect the CPU to stay out of the data path. ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," adds that PyTorch v2.7.0 and later also support GDS API calls directly. It also says that RDMA access over InfiniBand or RoCEv2 is the one storage form where a GPU places data directly onto a remote SSD."]}),"\n",(0,a.jsx)(t.p,{children:"Confirm GDS registration on a real node, using the check in the commands section, before you plan a design around it. A design built on a feature that the node does not register will look fine on paper and then fall back to the slower path in production."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"3-ultra-ethernet-consortium-uec-specification-v10-architecture-pdsses-encapsulations-and-delivery-modes",children:"3. Ultra Ethernet Consortium (UEC Specification v1.0): Architecture, PDS/SES, Encapsulations, and Delivery Modes"}),"\n",(0,a.jsx)(t.p,{children:"Picture an Ethernet network team whose AI cluster grows from a few racks to a whole building. The team already knows its switches, but it now needs the fabric to behave like a supercomputer interconnect. The specification discussed here is the industry's answer to that need."}),"\n",(0,a.jsx)(t.p,{children:"The Ultra Ethernet Specification v1.0 is a major step for Ethernet. The Ultra Ethernet Consortium (UEC) released it on June 11, 2025, under the Linux Foundation. It was built for HPC, AI, cloud infrastructure, and data-intensive enterprise environments. Its goal is simple to state: make Ethernet fit the demands of modern GPU clusters. The hard part is the list of details that must all change together, and the rest of this chapter walks through that list one part at a time."}),"\n",(0,a.jsx)(t.p,{children:"Ethernet and IP fabrics have already proven themselves in AI data centers. Operators know how to run them, how to monitor them, and how to buy them from many vendors. The open question is how to make them behave like a dedicated interconnect for training. Production deployments have reached 100,000-GPU server clusters, and thousands of 400 Gbps and 800 Gbps ports connect those servers together."}),"\n",(0,a.jsx)(t.p,{children:"InfiniBand used to be the usual choice for this kind of cluster. Ethernet has since caught up on speed, and it brings a wider set of vendors, which is why buyers now compare the two on cost and on openness as well as on raw performance. Once Ethernet was tuned for lossless operation, 800 Gbps Ethernet became a more cost-competitive option. It offered the same performance, better scalability, and an open standard. Many vendors support both the switch side and the NIC side."}),"\n",(0,a.jsx)(t.p,{children:"Fine-tuned Ethernet with RoCEv2 and DCQCN still had drawbacks. Think of the tuning as a set of dials that must be turned again each time the traffic pattern changes. A dial set for one workload can misbehave for the next one. The biggest one is that operators had to retune it as AI workloads changed. The way server NICs announce end-to-end reordering can change. So can the handling of reordered packets, or the number of sessions that run in parallel based on buffer size."}),"\n",(0,a.jsx)(t.p,{children:"The network needs to understand what end hosts can do, and it needs to adapt to them. It can set buffers or pick a load-balancing method for one workload. Think of the network as a referee that adjusts the rules to each game. The rules should stay fixed for the whole match, because a referee who changes them in the middle of a play confuses both teams. Then it should keep that choice steady for the whole job. If you change that choice mid-job, you break the steady state the job depends on."}),"\n",(0,a.jsx)(t.p,{children:"AI models keep growing in parameters and tokens. Each jump in model size adds more gradient traffic, and the fabric has to keep up with that growth without a redesign every year. That pressure is what pushes the standard toward very large fabrics. Data center networks will need ports of 400 Gbps or more to synchronize GPU servers. For a training domain, the IP fabric should be ready for more than a million GPU nodes. Reaching that scale takes more optimization, such as faster ramp time, delivery mode detection, and both link-level and end-to-end congestion control. UEC wants to standardize these at the industry level."}),"\n",(0,a.jsx)(t.p,{children:"Standards cannot stop at the switch. A switch that offers a feature is only useful when the NIC on each server can use it too. That is why the specification covers both ends of the link, and why the chapter keeps returning to the NIC. End-host NIC drivers need them too, which makes this a full-stack solution. The switch understands what the end host needs, and the end host understands real-time network conditions. For example, a UEC NIC can react to congestion by changing its source UDP port. When you size a fabric, you need the switch and the NIC to agree on that behavior."}),"\n",(0,a.jsx)(t.p,{children:"The UEC decided to define a new transport, link, and software stack. A new stack is a bigger step than a patch, but it avoids carrying old assumptions forward. Think of it as a new building designed for today's traffic, rather than an extension on an old house. The aim is more performance and a fabric that is easier to deploy in a plug-and-play way. The table below lists the main motivations for that redesign. It puts a strong focus on end-host NIC optimization."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Area"}),(0,a.jsx)(t.th,{children:"Motivation"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Lossless fabric fine-tuning"}),(0,a.jsx)(t.td,{children:"If zero-touch DCQCN is missing, UEC offers a plug-and-play approach for lossless Ethernet."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Ultra-large scale and performance"}),(0,a.jsx)(t.td,{children:"AI data center infrastructure is growing and already has 100,000+ GPUs. UEC wants fabrics and communication libraries that support more than a million nodes. Faster workloads mean shorter session negotiation."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Full-stack AI fabric"}),(0,a.jsx)(t.td,{children:"Fabrics are not yet connected to upper-layer collective communication managers. In-Network Collectives (INC), defined in the UEC Software working group, bring collective communication into the specification. Transport and upper software layers stay synchronized."})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"Better LLM training also depends on the rest of the stack. A faster fabric does not help if the storage cannot feed it, or if the monitoring cannot show where the slow link sits. The specification therefore touches storage, management, and benchmarking as well. Storage networks, management, benchmarking standards, and KPIs all need the same care. HPC is part of the target too, not only training."}),"\n",(0,a.jsx)(t.p,{children:"UEC's motivation comes down to three goals. Each goal answers a complaint that operators have made about the current Ethernet options, and the list below states each one in plain words."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Performance:"})," Traditional Ethernet can add unpredictable delay from packet collisions and non-deterministic routing. UEC includes features that bound latency for critical workloads."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Scalability:"})," Modern AI training clusters and supercomputers can have tens of thousands of nodes. Legacy protocols often struggle to keep performance at that size."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Reliability and congestion control:"})," Congestion must be managed well when several high-bandwidth applications run at the same time."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Keep these three goals in mind. When a feature looks like extra complexity, ask which goal it serves. If the answer is none, the feature may not belong in your first deployment. Each feature in the rest of this chapter answers at least one of them. You can use them as a checklist when you read a feature list."}),"\n",(0,a.jsx)(t.h3,{id:"31-uec-working-groups-service-profiles-ai-base-ai-full-hpc-and-core-terminology",children:"3.1 UEC Working Groups, Service Profiles (AI Base, AI Full, HPC), and Core Terminology"}),"\n",(0,a.jsx)(t.p,{children:"As Ethernet AI clusters scale toward a million endpoints, legacy RoCEv2 hits three walls. Static ECMP flow hashing creates tail-latency collisions. A single dropped packet triggers a Go-Back-N retransmission of the entire window. Hop-by-hop PFC pause frames also risk spreading congestion across unrelated jobs. UEC Specification v1.0 answers these walls. Released on June 11, 2025 by more than 70 member companies under the Linux Foundation, it replaces the InfiniBand Base Transport Header with a multipath-native Ethernet transport stack. Think of the old header as a label that assumes one fixed road for each conversation. The new stack is built for many roads at once, so the sender can choose a different path for each packet."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"UEC Specification v1.0 Structure and Three Service Profiles:\n- Eight Working Groups:\n  1. Physical Layer (FEC statistics, link fault signaling, modified 64B/66B PCS encoding with out-of-band Control Ordered Sets CtlOS)\n  2. Link Layer (Link Layer Reliability LLR, Packet Rate Improvement PRI, Credit-Based Flow Control CBFC)\n  3. Transport Layer (Ultra Ethernet Transport UET, PDS, SES, TSS, NSCC, RCCC, DSCP packet trimming)\n  4. Software (Libfabric APIs fi_mr and fi_collective, In-Network Collectives INC)\n  5. Storage, 6. Management, 7. Performance & Debug, 8. Compliance\n- Three Negotiated Service Profiles:\n  - AI Base Profile: mandatory ROD and RUD delivery modes + mandatory NSCC congestion control over lossy or lossless 400G/800G Ethernet\n  - AI Full Profile: adds RUDI (idempotent unordered writes for gradient aggregation) as mandatory; UUD optional\n  - HPC Profile: strictest latency and feature rules; supports ROD, RUD, RUDI, and optional UUD\n- Seven Core UET Constructs:\n  1. Fabric Endpoint (FEP; sFEP for INC-capable switches)\n  2. Fabric Address (FA; IPv4 or IPv6 via SLAAC)\n  3. Packet Delivery Context (PDC; SPDCID, DPDCID, bound to 1 Congestion Control Context CCC_ID)\n  4. Packet Delivery Sublayer (PDS; SYN, PSNs, Clear PSN Offset, ACK/NACK/SACK, req_cc_state, ACK_CC)\n  5. Semantic Sublayer (SES; Libfabric fi_mr RKEY validation & fi_collective, Opcode RMA WRITE 0x01, TAGGED_SEND 0x80, DEFERRABLE SEND, Message ID, Buffer Offset, Match Bits, Request Length)\n  6. JobID, PIDonFEP, and Resource Index (RI)\n  7. Transport Security Sublayer (TSS; AES-GCM encryption header + trailing Integrity Check Value ICV)\n"})}),"\n",(0,a.jsx)(t.p,{children:"Reading a UEC packet capture or configuring a UET NIC requires seven core architectural constructs. Each one has a clear job, so learn them in order."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Fabric Endpoint:"})," Any server NIC or switch port that takes part in the UEC fabric. Switch endpoints that can run In-Network Collectives are called ",(0,a.jsx)(t.code,{children:"sFEPs"}),"."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Fabric Address:"})," The IPv4 or IPv6 address that identifies an FEP. Plug-and-play provisioning through IPv6 SLAAC often assigns it automatically."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Packet Delivery Context:"})," A logical point-to-point transport channel between an initiator FEP and a target FEP. It is identified by ",(0,a.jsx)(t.code,{children:"SPDCID"})," and ",(0,a.jsx)(t.code,{children:"DPDCID"}),", and it is bound to one Congestion Control Context (",(0,a.jsx)(t.code,{children:"CCC_ID"}),")."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Packet Delivery Sublayer:"})," The lower UET sublayer. It handles PDC session setup, Packet Sequence Numbers, ",(0,a.jsx)(t.code,{children:"Clear PSN Offset"}),", ",(0,a.jsx)(t.code,{children:"ACK"}),"/",(0,a.jsx)(t.code,{children:"NACK"}),"/",(0,a.jsx)(t.code,{children:"SACK"})," processing, and congestion control state."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Semantic Sublayer:"})," The upper UET sublayer. It translates Libfabric calls (",(0,a.jsx)(t.code,{children:"fi_mr"})," and ",(0,a.jsx)(t.code,{children:"fi_collective"}),") into wire semantics, and it encodes opcodes, message IDs, buffer offsets, match bits, and request lengths."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"JobID, PIDonFEP, and Resource Index:"})," These three fields replace the legacy RoCEv2 BTH Queue Pair number. ",(0,a.jsx)(t.code,{children:"JobID"})," identifies the distributed job across the cluster. ",(0,a.jsx)(t.code,{children:"PIDonFEP"})," identifies the target OS process context, and ",(0,a.jsx)(t.code,{children:"Resource Index"})," identifies the completion or receive queue."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Transport Security Sublayer:"})," A built-in UET encryption and authentication header that uses AES-GCM with a trailing Integrity Check Value. It provides end-to-end confidentiality, integrity, and anti-replay protection without external MACsec overhead."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"More than 70 vendors and institutions formed working groups, and each one focused on a single area of improvement. Think of the groups as the trades on a large construction site, with electricians, plumbers, and framers each working on their own part of one building. Their work was merged into one document for the first specification, released in June 2025 as a standard reference. You do not need every group's role to follow the technologies. Knowing which groups exist still helps, because it shows which features may appear in a later version. This chapter focuses on the Transport and Link Layer working groups and how they connect to the Software working group. Start with those two groups, and the rest of the chapter will read more easily."}),"\n",(0,a.jsx)(t.p,{children:"The Link Layer working group looks at the connection between two end nodes. Think of a link as a single stretch of road between two intersections. Problems that start on that stretch should be fixed there, before they spread to the rest of the route. That can be two UEC switches, or a UEC switch and a server. The group studies how to improve congestion control and reliable transport on each link. The goal is faster job completion and less tail latency. Three functions stand out, and you will meet each one again later in this chapter."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Link Layer Reliability (LLR):"})," LLR reduces the latency cost of packet loss. Recovery happens on the link, so the end host does not have to handle every retry."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Packet Rate Improvement (PRI):"})," PRI aims to raise the frame rate. It cuts per-frame overhead and keeps only the header fields that AI transmissions need."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Credit-Based Flow Control (CBFC):"})," CBFC aims to replace the RoCEv2 PFC with a more efficient credit system on each link. InfiniBand already uses credit-based flow control for storage transport, and UEC applies the same credit idea to Ethernet."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"The Transport working group develops Ultra Ethernet Transport (UET), which is one of the most important pieces for end-to-end integration. Think of UET as the part of the stack that carries the message from one end of the route to the other, while the link groups fix problems on each stretch along the way. UET uses a new data packet format. Instead of carrying an InfiniBand BTH inside a RoCEv2 UDP frame, it defines a new set of headers after the UDP header. The group also proposes packet trimming, Receiver Credit Congestion Control (RCCC), and Network Signal Congestion Control (NSCC). NSCC and RCCC both influence the entropy used for multipathing."}),"\n",(0,a.jsx)(t.p,{children:"UEC uses two levels of congestion control and signaling. One level runs end to end between servers. The other runs on the link, and some of its functions are optional. UET also brings authentication, encryption, and a UET security header into the packet itself. That replaces the separate MACsec functions used with encrypted RoCEv2."}),"\n",(0,a.jsx)(t.p,{children:"The Semantic Sublayer (SES) keeps the two endpoints in sync. It lets the software layer, Libfabric, track the state of each transaction. The Transport group also defines the basic packet delivery modes. Those modes set how two end hosts agree to communicate and whether packets must arrive in order."}),"\n",(0,a.jsx)(t.p,{children:"The Software working group defines In-Network Collectives (INC). It also defines how collective communication libraries (CCLs) use fabric resources efficiently. The group proposes an INC manager and an INC switch agent as new AI data center components. InfiniBand deployments already use similar components, and UEC took inspiration from them."}),"\n",(0,a.jsx)(t.p,{children:"UET borrows the strongest ideas from both worlds. Think of it as a hybrid car that takes the best of two engines. The credit idea comes from one design, and the open, distributed addressing comes from the other. From InfiniBand it takes credit mechanisms, CCL and INC support, and plug-and-play behavior. From Ethernet it takes a distributed model, where entries do not depend on a central state. IPv6 is a good example of that approach at massive scale. Plug-and-play address assignment with SLAAC, native to IPv6, is planned for UET fabrics too. You can think of UET as a design that takes the best parts of each parent."}),"\n",(0,a.jsx)(t.p,{children:"The API is a major focus for the Software group. An API that lets the application state its needs is useful, because the network can then choose the right service instead of guessing from the packet headers. It is looking at Libfabric, an open-source API that lets applications state their needs for message and packet ordering. UET then picks the transport service that matches those needs. The group also defines the AI Base, AI Full, and HPC profiles."}),"\n",(0,a.jsx)(t.p,{children:"Other groups matter as well. Certification and measurement work decide whether a product from one vendor works with a product from another, and that work often takes as long as the design itself. The Compliance working group defines the tests that show a device meets UEC standards. Companies such as Spirent and Keysight help define how performance is measured and how KPIs are checked. The Management working group makes the new UET standard deployable in production networks."}),"\n",(0,a.jsx)(t.p,{children:"The Physical Layer working group is the most disruptive. It changes the lowest levels of the stack, so existing Ethernet gear may not be fully compatible. That work will likely take the longest to reach scale-out products. The Storage working group stays somewhat separate, and it becomes relevant once the Transport and Link Layer work reaches switches and NICs."}),"\n",(0,a.jsx)(t.p,{children:"Here is what each working group covers in the first specification. Read the list as a map of who owns which part of the stack, so you know whom to ask when a feature behaves unexpectedly."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Physical Layer working group:"})," Creates specifications that improve the performance, latency, and management of the Ethernet physical layer, including the medium and the clients on that layer."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Link Layer working group:"})," Improves the performance, latency, and management of the Ethernet link layer."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Transport Layer working group:"})," Creates an AI and HPC transport with better throughput, latency, scalability, and management over Ethernet."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Software working group:"})," Creates specifications and an open-source software API for AI and HPC use cases."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Storage working group:"})," Works on compatibility with standard physical connections, link-level features, and packet encoding. It also covers transport services, security, and RDMA API compatibility with the Software group."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Compliance working group:"})," Makes sure devices and services follow UEC standards, and defines the tests that validate them."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Management working group:"})," Focuses on fabric manageability, including topology discovery, monitoring, and interoperability across vendors."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Performance and Debug working group:"})," Defines performance benchmarks and adds debugging capabilities."]}),"\n"]}),"\n",(0,a.jsx)(t.h3,{id:"32-pdc-session-handshake-udp-based-encapsulation-for-uet-udp-port-49150-and-uet-over-ip-ip-protocol-253",children:"3.2 PDC Session Handshake, UDP-Based Encapsulation for UET (UDP Port 49150), and UET over IP (IP Protocol 253)"}),"\n",(0,a.jsx)(t.p,{children:"Picture two servers that want to talk for the first time and must agree on the rules before they send anything. Each side needs to know which delivery mode, which profile and which congestion method the other side supports. The handshake below is how they settle those questions."}),"\n",(0,a.jsxs)(t.p,{children:["Before data moves on a Packet Delivery Context, initiator FEP A and target FEP B run a lightweight three-step PDS handshake. The handshake avoids slow out-of-band queue-pair exchanges. When Reliable Ordered Delivery is selected, every message that shares ",(0,a.jsx)(t.code,{children:"{JobID, source PIDonFEP, destination PIDonFEP, RI, Traffic Class}"})," is pinned to a single PDC. That pinning is why you should set the delivery mode before the first message leaves the host."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"PDC Session Establishment Handshake Sequence:\n1. Initiator FEP A -> Target FEP B: sends PDS packet with pds.flags.syn = 1, initial PSN = 101, Source PDC ID (SPDCID = 201), Clear PSN Offset, and requested delivery mode (ROD_REQ 0x03 or RUD_REQ)\n2. Target FEP B -> Initiator FEP A: allocates local PDC (301) and replies with ACK = 101, SPDCID = 301, DPDCID = 201\n3. Initiator FEP A -> Target FEP B: records DPDCID = 301, clears SYN bit (pds.flags.syn = 0), and transmits subsequent data packets (PSN = 102, SPDCID = 201, DPDCID = 301)\n"})}),"\n",(0,a.jsx)(t.p,{children:"Two servers form a one-to-one relationship during session setup. Think of it as two people who agree to a private phone line before they start talking. Once the line is open, both sides know whom they are speaking to and which rules apply to the call. The initiator and target start that relationship at the API and Libfabric levels. Libfabric turns the requirements into network and target memory parameters, and SES and PDS then use those parameters. Each server's stack runs from the application down through Libfabric, SES, PDC, PDS, UDP, IP, and MAC."}),"\n",(0,a.jsx)(t.p,{children:"Session setup begins with endpoint discovery. Each side must first learn that the other side exists and can be reached. Only after that does the conversation about profiles, reordering, and congestion method begin. Each FEP gets a fabric address, which is typically IPv4 or IPv6. Each FEP also gets relative addressing based on JobID and PIDonFEP for the PDC. The next phase exchanges supported profiles, such as AI Base or AI Full, along with transport capabilities and reordering support. The congestion management method for the PDC is negotiated in that same phase. When you debug a stuck session, check which of these phases never completed."}),"\n",(0,a.jsxs)(t.p,{children:["A real capture makes the PDS fields concrete. Reading a capture is the fastest way to tell whether your switches and your NICs agree, because the flags and identifiers show what each side actually sent. A sample PDS packet was captured and decoded with the Spirent implementation of the UEC emulator, then opened in Wireshark. In this capture, ",(0,a.jsx)(t.code,{children:"SYN"})," is set in the PDS, and the ROD request is advertised. The delivery mode was set indirectly, through the Libfabric settings at the software level."]}),"\n",(0,a.jsxs)(t.p,{children:["The frame reads from top to bottom. It starts with Ethernet II, then IPv4, then the UET transport. Inside the PDS, the Flags field shows CRC, RETX, ACK Request, and ",(0,a.jsx)(t.code,{children:"SYN"})," set. The PSN is 13, and both PDC IDs are 0. The ACK arrives in frame 3253, and the payload closes with a CRC of fcfdfeff."]}),"\n",(0,a.jsxs)(t.p,{children:["The SES part of a second capture decodes the JobID, PIDonFEP, and Resource Index. That request is a ",(0,a.jsx)(t.code,{children:"TAGGED_SEND"}),", an operation that uses match bits to choose a buffer. The Job ID is 1, and the index is 15. The match bits are 0x0000000000000001, and the request length is 4096 bytes."]}),"\n",(0,a.jsxs)(t.p,{children:["A UDP-based capture shows the same ideas. Its PDS is a ",(0,a.jsx)(t.code,{children:"RUD_REQ"})," with flags 0x48 and PSN 2607. Both source and destination PDC IDs are 2. Its SES is a ",(0,a.jsx)(t.code,{children:"DEFERRABLE SEND"})," with Message ID 23. The PDC source and destination and the delivery mode stay the same for the whole transfer. Only the PSNs and ACKs change."]}),"\n",(0,a.jsx)(t.p,{children:"The Message ID stays constant across a set of writes or sends, which helps track, match, and complete each operation. Think of the Message ID as a tracking number on a parcel. The sender and receiver use it to match the ACK to the right write, even when many writes are in flight at once. An ACK for an RUD request is shorter, and it refers only to the Message ID and Job ID."}),"\n",(0,a.jsxs)(t.p,{children:["The IP-only capture shows the lighter format. Its PDS carries an ",(0,a.jsx)(t.code,{children:"Entropy"})," value, and there is no UDP layer. The flags are 0x48 with CRC set, and ",(0,a.jsx)(t.code,{children:"SYN"})," is not set. The SES is a WRITE RMA opcode 0x01 with Message ID 1, Job ID 1, and Index 15. Even without UDP, Job ID, PIDonFEP, and Resource Index still map to the GPU memory region that Libfabric defines."]}),"\n",(0,a.jsx)(t.p,{children:"UEC Specification v1.0 defines two wire encapsulations for UET packets. Both endpoints must be configured identically before the PDC is created."}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart LR\n  subgraph UDP_Encap["Option A: UET over UDP (IP Proto 17, Dst Port 49150)"]\n    U_L2["Ethernet II<br/>0x0800 / 0x86DD"] --\x3e U_IP["IPv4 / IPv6<br/>Proto = 17"]\n    U_IP --\x3e U_UDP["UDP Header<br/>Src=Entropy, Dst=49150"]\n    U_UDP --\x3e U_TSS["Optional TSS<br/>or UET PDS + SES"]\n    U_TSS --\x3e U_Pay["UET Payload +<br/>UET CRC or TSS ICV + FCS"]\n  end\n  subgraph IP_Encap["Option B: UET over Native IP (IP Proto 253, 128B Parse)"]\n    I_L2["Ethernet II<br/>0x0800 / 0x86DD"] --\x3e I_IP["IPv4 / IPv6<br/>Proto = 253 (UET)"]\n    I_IP --\x3e I_PDS["UET PDS Header<br/>Entropy Field + Type/PSN"]\n    I_PDS --\x3e I_SES["UET SES Header<br/>JobID, PIDonFEP, RI"]\n    I_SES --\x3e I_Pay["UET Payload +<br/>UET CRC or TSS ICV + FCS"]\n  end'}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Encapsulation Property"}),(0,a.jsx)(t.th,{children:"Option A: UET-over-UDP"}),(0,a.jsx)(t.th,{children:"Option B: UET-over-IP (Native / Raw IP)"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Outer L3/L4 Headers"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"Ethernet -> IPv4/IPv6 (Protocol = 17) -> UDP (Dst Port = 49150)"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.code,{children:"Ethernet -> IPv4/IPv6 (Protocol = 253)"})," with no UDP header"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Multipath Entropy Carrier"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"UDP Source Port"})," dynamically rotated by the sender NIC mid-session whenever an NSCC NACK signals path congestion."]}),(0,a.jsxs)(t.td,{children:["Dedicated ",(0,a.jsx)(t.strong,{children:"Entropy field at the start of the PDS header"})," updated by the sender NIC upon NSCC feedback."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Switch ASIC Parsing & Compatibility"})}),(0,a.jsx)(t.td,{children:"Works transparently across all existing 400G/800G Ethernet switches using standard UDP ECMP/packet-spraying hashes."}),(0,a.jsxs)(t.td,{children:["Removes 8-byte UDP overhead so PDS + SES (",(0,a.jsx)(t.code,{children:"JobID"}),", ",(0,a.jsx)(t.code,{children:"RI"}),") fit inside the ",(0,a.jsx)(t.strong,{children:"128-byte switch packet-parsing window"}),", but requires switches to permit ",(0,a.jsx)(t.strong,{children:"IP Protocol 253"}),"."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Integrity (UET CRC) vs Security (TSS)"})}),(0,a.jsxs)(t.td,{children:["Supports optional UET CRC (",(0,a.jsx)(t.code,{children:"0xfcfdfeff"}),") ",(0,a.jsx)(t.strong,{children:"or"})," optional TSS (AES-GCM header after UDP + trailing ICV). ",(0,a.jsx)(t.strong,{children:"Never enable both UET CRC and TSS simultaneously."})]}),(0,a.jsxs)(t.td,{children:["Supports optional UET CRC ",(0,a.jsx)(t.strong,{children:"or"})," optional TSS immediately after the PDS Entropy field. When TSS encrypts PDS/SES, switches must hash on outer UDP Src Port or PDS Entropy."]})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"UDP-based encapsulation can also add security. A Transport Security Sublayer (TSS) header sits right after UDP, and the AES-GCM ICV is placed after the UET payload. Together they give end-to-end confidentiality, integrity, and anti-replay protection for AI workloads. A UET CRC is optional and can be used instead of TSS, but never both at once. If you enable TSS, you turn the UET CRC off."}),"\n",(0,a.jsx)(t.p,{children:"Encryption changes how switches can balance traffic. A switch that balances on hidden fields has to fall back on the fields it can still see. That is a trade-off between privacy and load balance, and the team should choose it on purpose. Once TSS hides the SES fields, switches cannot read the Resource Index or JobID, so packet spraying or UDP source port load balancing must be used instead. The SES opcode says what kind of write or send is happening. In RoCEv2 that information sat in the BTH. Here, the Resource Index, JobID, PIDonFEP, and buffer offset tell the target where the data goes in memory. Consider this when you plan the switch hashing for an encrypted job."}),"\n",(0,a.jsx)(t.p,{children:"CRC means cyclic redundancy checking at the UET layer. A CRC is a short checksum that the receiver recomputes, and a mismatch tells it that the bits changed on the way. Think of it as a seal that breaks when someone tampers with the envelope. It protects data integrity across the transport path, and NICs can use it. It helps most on lossy transport, where corruption can slip past hop-by-hop Ethernet checks. Whether it applies depends on the packet delivery mode of the PDC. For ROD, it can still check end-to-end integrity when packets arrive in order."}),"\n",(0,a.jsxs)(t.p,{children:["IP-only encapsulation also allows a CRC or TSS, but the specification says not to use both. TSS sits immediately after the ",(0,a.jsx)(t.code,{children:"Entropy"})," field in this format. Like UDP-based encapsulation, the PDS carries PSNs and ACK or NACK messages. If NSCC is used, the NACK carries entropy so the sender can adapt it. In this format the sender changes the ",(0,a.jsx)(t.code,{children:"Entropy"})," field instead of the UDP source port. You will see that field in the capture, so know where to look."]}),"\n",(0,a.jsx)(t.h3,{id:"33-the-four-uec-packet-delivery-modes-rod-rud-rudi-uud",children:"3.3 The Four UEC Packet Delivery Modes (ROD, RUD, RUDI, UUD)"}),"\n",(0,a.jsx)(t.p,{children:"Suppose a training job sprays its packets across every spine switch to balance the load, and the receiving NIC starts to see gaps in the sequence. That is the everyday tension between load balancing and reliable delivery, and the delivery modes below are how UEC handles it."}),"\n",(0,a.jsx)(t.p,{children:"In RoCEv2, spraying packets across multiple spine switches causes out-of-order arrivals at the target NIC. RoCEv2 reads those out-of-order arrivals as packet loss, and it flushes the entire 64-packet window. Through Libfabric, UET lets an application pick one of four delivery modes per PDC. It uses selective retransmission, so only the single missing PSN is resent."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Selective Retransmission vs RoCEv2 Go-Back-N Penalty:\n- In-flight window size: 64 packets (PSN 1..64)\n- Single packet loss at packet #1:\n  RoCEv2 Go-Back-N flushes and retransmits all 64 packets\n  UET (RUD / RUDI + packet trimming) selectively retransmits only 1 packet (saving 63 packets, a 64.0x retransmission reduction)\n"})}),"\n",(0,a.jsx)(t.p,{children:"Put the penalty in plain numbers. The point is not that the retry is slow in one step. The point is that go-back-N repeats far more work than the loss itself requires, and the extra work crowds the link at the moment it is busiest. With a 64-packet window and packet 1 lost, Go-Back-N resends all 64 packets. Selective retry resends one. That is 63 packets that never have to cross the fabric twice."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Delivery Mode"}),(0,a.jsx)(t.th,{children:"Reliability & Ordering Semantics"}),(0,a.jsx)(t.th,{children:"Pros & Cons"}),(0,a.jsx)(t.th,{children:"Mandatory / Optional Profiles & Target Workloads"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"ROD (Reliable Ordered Delivery)"})}),(0,a.jsxs)(t.td,{children:["PSN-tracked (",(0,a.jsx)(t.code,{children:"ACK"}),"/",(0,a.jsx)(t.code,{children:"NACK"}),"/",(0,a.jsx)(t.code,{children:"SACK"}),"), delivered ",(0,a.jsx)(t.strong,{children:"in strict order"})," to the upper layer. Receiver NIC uses its ",(0,a.jsx)(t.strong,{children:"reordering buffer"})," to absorb fabric packet spraying."]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Pros:"})," Preserves strict MPI/control ordering even over packet-sprayed fabrics.",(0,a.jsx)("br",{}),(0,a.jsx)(t.strong,{children:"Cons:"})," Higher tail latency and NIC reorder buffer memory footprint."]}),(0,a.jsxs)(t.td,{children:["Mandatory in ",(0,a.jsx)(t.strong,{children:"AI Base"}),", ",(0,a.jsx)(t.strong,{children:"AI Full"}),", and ",(0,a.jsx)(t.strong,{children:"HPC"}),". Used for HPC, MPI, and serialized control flows."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"RUD (Reliable Unordered Delivery)"})}),(0,a.jsxs)(t.td,{children:["PSN-tracked (",(0,a.jsx)(t.code,{children:"ACK"}),"/",(0,a.jsx)(t.code,{children:"NACK"}),"/",(0,a.jsx)(t.code,{children:"SACK"}),"), ",(0,a.jsx)(t.strong,{children:"out-of-order Direct Data Placement (DDP)"})," straight into GPU HBM without waiting for earlier PSNs."]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Pros:"})," Eliminates reorder-buffer head-of-line blocking; lower latency under per-packet spraying.",(0,a.jsx)("br",{}),(0,a.jsx)(t.strong,{children:"Cons:"})," Application/collective must tolerate out-of-order completion."]}),(0,a.jsxs)(t.td,{children:["Mandatory in ",(0,a.jsx)(t.strong,{children:"AI Base"}),", ",(0,a.jsx)(t.strong,{children:"AI Full"}),", and ",(0,a.jsx)(t.strong,{children:"HPC"}),". Used for AI tensor/pipeline parallelism and bulk data transfers."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"RUDI (Reliable Unordered Delivery Idempotent)"})}),(0,a.jsxs)(t.td,{children:["Reliable unordered delivery for ",(0,a.jsx)(t.strong,{children:"idempotent"})," operations that can be safely retried or written multiple times to the same memory offset by one or multiple sources."]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Pros:"})," Allows proactive application-level retries without waiting for NACK round-trips; supports multi-writer updates.",(0,a.jsx)("br",{}),(0,a.jsx)(t.strong,{children:"Cons:"})," Requires idempotent memory semantics."]}),(0,a.jsxs)(t.td,{children:["Mandatory in ",(0,a.jsx)(t.strong,{children:"AI Full"})," and ",(0,a.jsx)(t.strong,{children:"HPC"})," (HPC profile required for full semantic support). Used for RMA writes and ",(0,a.jsx)(t.strong,{children:"AI gradient updates"}),"."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"UUD (Unreliable Unordered Delivery)"})}),(0,a.jsxs)(t.td,{children:["Best-effort fire-and-forget: ",(0,a.jsxs)(t.strong,{children:["omits PSNs (",(0,a.jsx)(t.code,{children:"Clear PSN Offset"}),"), ACKs, SACKs, NACKs, and retransmissions"]}),"."]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Pros:"})," Fastest session ramp time and lowest latency.",(0,a.jsx)("br",{}),(0,a.jsx)(t.strong,{children:"Cons:"})," No loss recovery, no integrity checking, ",(0,a.jsx)(t.strong,{children:"incompatible with TSS security"}),"."]}),(0,a.jsxs)(t.td,{children:["Optional in ",(0,a.jsx)(t.strong,{children:"AI Full"})," and ",(0,a.jsx)(t.strong,{children:"HPC"}),". Used for real-time telemetry and inference logging."]})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"Why does the delivery mode matter for AI? Some traffic must arrive in order, such as a control message that sets up a job. Other traffic, such as gradient writes that add into the same memory, can arrive in any order and still produce the right answer. Matching the mode to the traffic keeps the fabric fast without breaking the job. RoCEv2 has many limits on which traffic can run in order and which can run unordered. The usable mode often depends on the NIC vendor and the operation type. Writing into the same memory space differs from writing into different spaces. Writing once also differs from writing the same sector many times. UEC lets an AI developer set these needs through Libfabric API calls. You set them once, and the stack carries them down to the wire."}),"\n",(0,a.jsx)(t.p,{children:"PyTorch has an interface to Open MPI, and Open MPI connects to Libfabric. Some settings can be made directly through the API. Libfabric turns them into PDS and SES settings, and UET carries them across the fabric. The packet delivery mode settings follow the same path, from the AI application down to the transport. If you configure a job, you will touch that path at the top, not the bottom."}),"\n",(0,a.jsx)(t.p,{children:"MPI is a widely adopted API standard for parallel computing. It began in HPC, and it now plays a key role as a high-level interface for UEC. MPI connects to Libfabric and to AI frameworks such as PyTorch. Open MPI, when connected to Libfabric, also gives an interface to NCCL or RCCL for collective communication. Open MPI itself handles process coordination and CPU-side messaging."}),"\n",(0,a.jsxs)(t.p,{children:["The NCCL or RCCL connection is not needed when native MPI collectives or Libfabric-managed collectives are used. MPICH, an MPI alternative to Open MPI, supports ",(0,a.jsx)(t.code,{children:"MPI_Allreduce"})," and ",(0,a.jsx)(t.code,{children:"MPI_Alltoall"})," as documented collective types. In most cases, reliable delivery is the right choice. Its ACK step costs some speed, but it confirms every packet. A NACK can be used when lower PSNs are still missing and higher PSNs arrived fine."]}),"\n",(0,a.jsx)(t.p,{children:"RUD, ROD, and RUDI are all reliable modes, and only the ordering choice changes between them. UUD is the unreliable and unordered option. Think of it as a postcard. It goes out quickly and costs little, but nothing confirms that it arrived, so it suits telemetry better than a gradient. Each profile has a delivery mode for each operation type, such as read, write, or send. One passage in the source text says all profiles support RUD and ROD, and that only HPC supports RUDI. The profile table, however, lists RUDI as mandatory in AI Full. Check the exact profile rules in the UEC specification before you rely on either statement."}),"\n",(0,a.jsx)(t.h3,{id:"34-protocol-stack-network-architectures-and-existing-ethernet",children:"3.4 Protocol Stack, Network Architectures, and Existing Ethernet"}),"\n",(0,a.jsx)(t.p,{children:"Suppose your Ethernet vendor tells you that a new transport needs a new physical layer. The first question is whether your existing cables and switch ports still work. The answer below is that UEC keeps standard Ethernet at the bottom."}),"\n",(0,a.jsx)(t.p,{children:"The biggest early worry was that Ethernet and the physical layer would stop being compatible with IEEE standards. That would slow adoption of UEC and its transport and congestion features. UEC avoids the problem. It keeps standard Ethernet and changes only the layers after UDP, along with the end-to-end semantics. The first focus is the new UET packet format. You should look at that header first when you read a capture."}),"\n",(0,a.jsx)(t.p,{children:"From top to bottom, the stack holds applications, software APIs such as CCL, MPI, and OpenSHMEM, and the transport layer over UDP and IP. Below that sit a security layer, the IP layer, the Ethernet link layer, and the Ethernet PHY. The transport layer includes SES message semantics, PDS packet delivery with RUD and ROD options, and congestion management. The link layer adds LLDP negotiation, packet rate improvements, LLR, and CBFC. LLDP lets the two ends of a link discover what each one supports before they agree on the rules, which avoids a mismatch that would otherwise show up only as a slow link."}),"\n",(0,a.jsxs)(t.p,{children:["The UEC Ethernet physical layer is a longer-term option. Its main jobs are FEC statistics for predicting link quality and link fault signaling. It also uses modified 64B/66B PCS encoding to run out-of-band signaling inside the physical layer. The optional control ordered set message, ",(0,a.jsx)(t.code,{children:"CtlOS"}),", supports CBFC and LLR on each segment."]}),"\n",(0,a.jsx)(t.p,{children:"UET does not require a new network design. Most teams can keep the layout they already run and change the transport settings on top of it, which lowers the cost of trying the new features. The IP Clos three-stage and five-stage designs keep their place, even for UEC scale-out clusters. The right design depends on the target scale and the expected performance. For about 100,000 or 1 million GPUs, a five-stage or seven-stage architecture is needed, along with load-balancing mechanisms on the Ethernet and IP switches. If your fabric is already a three-stage Clos, you do not need to start over."}),"\n",(0,a.jsx)(t.p,{children:"The lossless fabric stays optional for UEC. Think of the lossless link as a safety rail. It helps on a narrow road, but a well-designed end-to-end system can drive safely without it, which is what the specification aims for. NIC-level reliable delivery and end-to-end congestion control are meant to deliver good performance even when not every segment is lossless. That is why the first specification keeps link-layer optimization optional. Those optimizations can still raise scale and performance a lot."}),"\n",(0,a.jsx)(t.p,{children:"For latency-sensitive inference, the five-stage topology may not be used. Every extra stage adds a hop, and an inference reply that waits for several hops feels slow to the user. A shorter path helps that workload even when the training fabric is larger. A collapsed spine design or a three-stage IP fabric takes its place. Some UEC networks add INC and CCL features on leaf-spine topologies to save bandwidth and latency. That needs stronger spine devices and better management platforms, and the fabric may also need a controller such as an INC manager."}),"\n",(0,a.jsx)(t.p,{children:"Most UEC IP fabrics keep a high port radix from leaf to spine. Those switches must balance traffic based on the semantics negotiated at the SES layer. Early on, some feared the Ethernet header would change to reduce segment latency. Compression or field removal remains an option, but it is optional, like the link-layer features."}),"\n",(0,a.jsx)(t.p,{children:"Existing 400 Gbps and 800 Gbps switches with enough Ethernet and IP ports can therefore carry UEC, at least for the AI Base profile. UEC-ready switches are mostly Ethernet switches that parse deep enough to read some UEC fields for load balancing. With JobID or Resource Index in the packet, the source UDP port must join the load-balancing hash. RoCEv2's QPair-based balancing no longer works, because the BTH is gone. So when you move a RoCEv2 fabric to UET, you must change the hash configuration too. Think of the hash as the rule that decides which lane each car takes. If the rule still looks for a label that no longer exists, every car lands in the same lane."}),"\n",(0,a.jsxs)(t.p,{children:["Most networks will keep leaf-spine-super spine designs with more 800 Gbps, 1.6 Tbps, and 3.2 Tbps ports. ",(0,a.jsx)(t.em,{children:"AI Data Center Network Design and Technologies"})," expects architectures to move toward DragonFly, DragonFly+, and Torus. It also expects a shift toward scale-up systems rather than scale-out. The change is mostly in switch software features, not in the design itself. A team that already runs a leaf-spine fabric can often upgrade the software and keep the cables and the rack layout."]}),"\n",(0,a.jsx)(t.p,{children:"The first UEC networks will likely share the fabric with existing RoCEv2 servers. Think of the shared fabric as a road with two lanes of different traffic, one for trucks that must never stop and one for cars that can slow down. The queues that separate the two lanes are the planning work the rest of this paragraph describes. The same ToR may serve UEC-ready servers and RoCEv2 GPU servers. RoCEv2 servers keep the lossless approach. UEC-ready servers can use best-effort delivery and rely on end-to-end control through RCCC or NSCC. You can run both kinds of server on one ToR, but you must plan the queues."}),"\n",(0,a.jsx)(t.p,{children:"Lossless mechanisms such as PFC-DSCP, LLR, and CBFC need careful planning, and one of the link-level options must be chosen for a shared link. For a native UEC fabric, link-layer control, reliable transport, and end-to-end control work well together. When two workload types must share a fabric, the lossless queue still uses RoCEv2, and the rest of the congestion control happens at the server NIC. Keep a written list of which queue each workload uses, because a silent change to that list is a common cause of mixed-traffic stalls."}),"\n",(0,a.jsx)(t.p,{children:"Path isolation can also help. Think of a separate overlay as a second road built beside the first one. New UEC work can use the new road, and the existing jobs keep using the old one without any change. The multi-tenancy options from the earlier IP routing discussion can carry new UEC workloads as a separate overlay, which keeps them isolated from existing AI and ML workloads. That keeps them away from the existing jobs, so you can add them without moving those jobs."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"4-uec-congestion-management-nscc-rccc-cbfc-packet-trimming-llr-and-in-network-collectives-inc",children:"4. UEC Congestion Management (NSCC, RCCC, CBFC), Packet Trimming, LLR, and In-Network Collectives (INC)"}),"\n",(0,a.jsx)(t.p,{children:"Flexible delivery modes still need congestion management. Picture a highway where every car can choose its own lane. Without a speed sign and a way to slow the flow at the on-ramps, the lanes still jam. Congestion control is that speed sign, and it works on both ends of the trip. You want the initiator and the target to react to congestion quickly, because that cuts retransmissions. A slow reaction lets the queue grow, and a growing queue turns a small burst into a long stall for every job that shares the link. The response must not slow an AI workload for longer than necessary, and it must not slow workloads that caused none of the congestion. RoCEv2 AI workloads suffered on this point, because PFC backpressure also hit servers that were not part of the congestion. You can see why that matters for any shared rack."}),"\n",(0,a.jsxs)(t.p,{children:["UEC has two main types of congestion management. Think of them as a city's traffic lights and its road signs. One part tells the drivers at each intersection what to do, and the other part keeps each segment of the road from filling up. The first is end-to-end, using either NSCC, which is managed at the originator, or RCCC, which is managed at the target. The second is segment or link-level control, which uses CBFC. Each PDC gets a congestion control context, ",(0,a.jsx)(t.code,{children:"CCC_ID"}),", that stays in place for the life of that PDC. When you read a trace, you can match each flow to its context by that ID. Keep the ID in your notes for the whole capture, so you can tell two busy flows apart when they share the same link. The three UEC profiles must support NSCC on lossy networks. That rule matters because a lossy network is the one that most deployments start with, and NSCC is the control that keeps it usable. As of mid-2025, RCCC is optional for lossy IP fabrics."]}),"\n",(0,a.jsx)(t.h3,{id:"41-two-tier-congestion-management-nscc-rccc-256b-credits-and-link-level-cbfc-32-vcs",children:"4.1 Two-Tier Congestion Management: NSCC, RCCC (256B Credits), and Link-Level CBFC (32 VCs)"}),"\n",(0,a.jsx)(t.p,{children:"In a traditional RoCEv2 cluster, a sudden many-to-one incast at a receiver fills the top-of-rack switch buffers. Picture many roads merging into one exit ramp at rush hour. The ramp backs up, and the cars on other roads that never touched the ramp get stuck behind the jam. That triggers Priority Flow Control pause frames, and those pauses freeze innocent victim flows that share the same link. If you run RoCEv2 today, this is the failure to watch for. A pause frame is a blunt tool, because it stops a whole link rather than the one flow that caused the problem. The victims are often unrelated jobs that happened to share the same uplink. UEC removes the PFC pause storms and head-of-line blocking by separating the two jobs. The end-to-end control slows the senders that cause the pressure, and the link-level control protects each hop without freezing unrelated traffic. End-to-end congestion control runs between endpoint NICs, and the lossless link-level control becomes optional."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"UEC End-to-End (NSCC / RCCC) and Link-Level (CBFC) Quantitative Parameters:\n- Network Signal Congestion Control (NSCC): sender-driven congestion window (cwnd) adjusted via RTT, ECN flag in NACKs, and ACK_CC telemetry (received byte count, service time, out-of-order packet count)\n- Receiver Credit Congestion Control (RCCC): target-driven Credit Pool requested via Credit Target (req_cc_state) and granted via 24-bit ACK congestion control field in units of 256 bytes:\n  256 credits x 256 bytes = 65,536 bytes (64 KiB) authorized transmission\n  Maximum 24-bit RCCC credit window = (2^24 - 1) x 256 = 4,294,967,040 bytes (~4.0 GiB)\n- Link-Level Credit-Based Flow Control (CBFC):\n  32 Virtual Channels (VCs) per port (2x InfiniBand's 16 VLs, 4x IEEE PFC's 8 priorities)\n  Discovered via LLDP; tracks Consumed Credit (CC) and Freed Credit (CF) counters per VC\n  Uses modified 64B/66B PCS physical sublayer out-of-band Control Ordered Set (CtlOS) CP_Update messages at line rate\n"})}),"\n",(0,a.jsx)(t.p,{children:"The three mechanisms act at different points on the path, and each one has a separate job. Keep the three apart in your head, because they fail in different ways. Think of them as three guards at three gates. End-to-end control watches the whole route, receiver credits watch the door of the destination, and link-level credits watch each short hop on the way."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Network Signal Congestion Control:"})," This is mandatory across all three UEC profiles on lossy fabrics. The sender PDS keeps an explicit congestion window of in-flight, unacknowledged bytes. The receiver returns ",(0,a.jsx)(t.code,{children:"ACK_CC"})," packets that carry the received byte count, the service time, and the out-of-order packet count. It can also return NACK packets with the ECN flag. The sender adjusts ",(0,a.jsx)(t.code,{children:"cwnd"})," using RTT and ECN feedback, and it rotates its UDP source port or PDS Entropy field."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Receiver Credit Congestion Control:"})," This is an optional, target-driven scheme built to prevent many-to-one receiver incast. Senders request credit through the ",(0,a.jsx)(t.code,{children:"Credit Target"})," (",(0,a.jsx)(t.code,{children:"req_cc_state"}),") field in their data packets. The target FEP arbitrates its local Credit Pool across the active incoming sessions. It grants credits back in units of 256 bytes inside a 24-bit ACK field. If the receiver buffer pool is full, it withholds credits before packets ever enter the fabric."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Link-Level Credit-Based Flow Control:"})," Inspired by InfiniBand CBFC, UEC CBFC doubles the capacity to 32 Virtual Channels per port. Lossless and best-effort channels can then share one link. Neighboring switches and NICs discover CBFC support through LLDP, and they track Consumed Credit and Freed Credit counters per VC. Instead of spending Layer 2 frame bandwidth on credit updates, the sender PCS sublayer sends out-of-band ",(0,a.jsx)(t.code,{children:"CtlOS"})," ",(0,a.jsx)(t.code,{children:"CP_Update"})," messages at line rate."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Think of the NSCC window as the number of boxes you may have on a conveyor belt at once. A new box goes on only when an old one has been confirmed as received. When the belt jams, you put fewer boxes on it, and when it runs clear, you add a few back."}),"\n",(0,a.jsx)(t.p,{children:"NSCC keeps an explicit congestion window. The sender uses window-based control to estimate its packets in flight, meaning the packets the target has not yet acknowledged. It may send while the window is larger than the bytes in flight. A packet counts as having left the network once an ACK or SACK confirms it. Until that confirmation arrives, the packet still occupies a place in the window, like a parcel that is still on the truck until the receipt comes back. NACKs may carry the ECN flag. When a flow runs slowly, start by checking whether the window is shrinking."}),"\n",(0,a.jsxs)(t.p,{children:["The feedback path runs in reverse. Information about the road travels back to the car that is driving on it, so the driver can slow down before the jam gets worse. The receiver sends NACKs, or sets and clears the ECN bit, and that feedback crosses the fabric back to the sender. The sender measures round-trip time (RTT) and uses it, together with the feedback, to resize the window. Whenever NSCC is used, the ACK or SACK must carry congestion control flags. Without those flags, the sender has no signal to adjust its window, and it will keep sending at the same rate even when the path is congested. The ",(0,a.jsx)(t.code,{children:"ACK_CC"})," reports the bytes received, the service time, and the out-of-order packet count."]}),"\n",(0,a.jsxs)(t.p,{children:["RCCC works from the receiver side, and it uses credit attribution instead of window math. Think of the receiver as a cashier who hands out a fixed number of tickets for a show. The sender can enter only with a ticket, so the room never holds more people than it can seat. A sender asks for more credit through the ",(0,a.jsx)(t.code,{children:"Credit Target"})," field in its data packets. It may transmit whenever its local credit pool at the receiver still has credit left. The receiver returns credit through credit control packets. Because the receiver shares credit information across all senders, their combined rate cannot congest it. Each sender sees the same pool, so no sender can take more than its share while the others wait."]}),"\n",(0,a.jsx)(t.p,{children:"Picture two sender servers and one receiver server. Each sender sends credit requests through its intermediate switches. The receiver's credit pool answers with credit control messages, and those messages travel back to each sender to set its rate. The advantage is simple. Think of the receiver as the person who controls the front door of a busy shop. Each customer gets in only when a slot opens, so the shop never has more people inside than it can serve. The target knows exactly how many credits remain across its active sessions, and when none are left, none are handed out."}),"\n",(0,a.jsxs)(t.p,{children:["In RCCC, the ",(0,a.jsx)(t.code,{children:"req_cc_state"})," field tells the target how much data the sender wants to send. The target can then decide how many credits to grant, based on what its own buffers can hold at that moment. The 24-bit ACK congestion control field carries the credits, in units of 256 bytes."]}),"\n",(0,a.jsx)(t.p,{children:"Suppose a receiver has room for one 64 KiB block and wants to tell the sender how much it can accept right now. The credit field answers that question in small units, and the arithmetic below shows the size of one grant and the largest value the field can carry."}),"\n",(0,a.jsx)(t.p,{children:"Here is the arithmetic for one credit grant. Each credit covers 256 bytes, so 256 credits cover 65,536 bytes, which is 64 KiB of authorized transmission. The largest window a 24-bit field can express is 2^24 minus 1, multiplied by 256. That comes to 4,294,967,040 bytes, or about 4.0 GiB."}),"\n",(0,a.jsx)(t.p,{children:"CBFC is an optional link-layer function. Think of it as a prepaid card on each link. The receiver loads the card with the space it has, and the sender spends one unit for each packet it sends. When the card runs out, the sender waits, so the receiver's buffer never overflows. It gives lossless delivery by priority on a full-duplex Ethernet link. Like RCCC, it uses credits to track free buffer space at the receiver. The difference is scope. CBFC works on one segment, such as the link between two switches in the same IP fabric. InfiniBand's CBFC inspired the UEC version, which doubles the virtual channels from 16 to 32 per port. Keep the two designs side by side when you read the comparison table."}),"\n",(0,a.jsx)(t.p,{children:"Think of the credits as a bank balance that the sender spends and the receiver refills. Unlike a pause frame, which stops everything on a link, a credit balance tells the sender exactly how much room is left for each class of traffic."}),"\n",(0,a.jsx)(t.p,{children:"CBFC has real advantages over standard PFC. It supports more lossless classes, allows better scheduling and load balancing, and is less sensitive to cable length and frame size. Explicit credit exchange reduces head-of-line blocking and PFC storms, and it allows more granular congestion management. The receiver creates credits from its available buffer, and the sender transmits only while it holds enough of them. The sender can wait for more credits without losing its place, which is why the link stays calm under a burst. You can think of the credits as a balance that the sender spends."}),"\n",(0,a.jsx)(t.p,{children:"Both sides track consumed credits. The sender counts what it has spent, and the receiver counts what it has freed. The two totals must agree, so a mismatch is a clear sign that something on the link is wrong. The receiver reports freed credits once traffic leaves its input buffer. Between two UEC switches, the sending side holds per-VC queues and a credit consumer, while the receiving side has its buffer and a credit generator. Packets flow hop by hop, and credits flow back the other way. Think of a relay of buckets passed along a line, where each person hands an empty bucket back to the one behind before that person hands over another full one. The receiving switch returns credits based on its port buffer state, using dedicated buffers, a shared pool, or both. Think of dedicated buffers as a reserved lane for each class, and the shared pool as a common lane that any class can use when it is free."}),"\n",(0,a.jsxs)(t.p,{children:["CBFC tracks consumed credits (",(0,a.jsx)(t.code,{children:"CC"}),") and freed credits (",(0,a.jsx)(t.code,{children:"CF"}),") with counters. The UEC specification lists them as the counters to watch at each segment. When a link misbehaves, compare the consumed and freed totals on both ends first, because that comparison often points to the failing segment faster than a packet capture. Compared with end-to-end control, CBFC needs small link-layer changes so that credit updates can run out of band. The sender's PCS sublayer sends ",(0,a.jsx)(t.code,{children:"CtlOS"})," ",(0,a.jsx)(t.code,{children:"CP_Update"})," messages at line rate. Switch1 does not send an explicit credit request. The link-level exchange is quieter than that. Switch1 simply reports how much it has used, and the other end works out the rest from the totals. Instead, it reports consumed credits through the ",(0,a.jsx)(t.code,{children:"CP_Update"})," message."]}),"\n",(0,a.jsx)(t.p,{children:"Picture a switch port that runs two threshold systems at once, one for pause frames and one for credits. Each system has its own limits, and the two limits must stay in step. The paragraph below explains why engineers avoid running both on one link."}),"\n",(0,a.jsx)(t.p,{children:"In theory, PFC and CBFC can run on different VCs of the same link. Running two threshold systems at once gets very complicated, so CBFC is the more effective approach compared with PFC and DSCP-driven control on lossless fabrics. Before any credit exchange, LLDP confirms that both ends of the segment support CBFC. Check that LLDP result first when a link misbehaves. A link that never completed the CBFC exchange will look healthy in some counters while it quietly runs without flow control."}),"\n",(0,a.jsx)(t.h3,{id:"42-fast-retransmission-via-dscp-packet-trimming-and-hop-by-hop-link-layer-reliability-llr",children:"4.2 Fast Retransmission via DSCP Packet Trimming and Hop-by-Hop Link Layer Reliability (LLR)"}),"\n",(0,a.jsx)(t.p,{children:"Picture a collective that stalls for a long stretch because one packet was dropped in a brief burst of traffic. The whole group waits for the sender to notice the loss and resend it. UEC shortens that wait by repairing the loss closer to where it happened."}),"\n",(0,a.jsx)(t.p,{children:"When microbursts overflow a switch buffer despite NSCC and RCCC, waiting for a sender retransmission timeout stalls the whole collective. UEC avoids that wait by catching packet drops at the switch buffer and on the physical link. Two mechanisms do the work. You will see both in the failure modes later in the chapter."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"DSCP packet trimming:"})," Packets in trim-eligible DSCP classes are never silently dropped when an intermediate switch buffer fills. The congested switch slices off the data payload and keeps the packet header and the original ECN-capable state. It forwards the lightweight trimmed header over a high-priority queue to the destination FEP. When the destination NIC gets a trimmed packet, it skips writing the payload into GPU HBM. It immediately sends a targeted NACK or SACK to the sender for that exact PSN. You get that fast repair without waiting for a timeout."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Link Layer Reliability:"})," This is negotiated per link segment, between adjacent switches or between a NIC and a switch. Each LLR-eligible Ethernet frame receives a link-layer sequence number, ",(0,a.jsx)(t.code,{children:"SEQ"}),", embedded in the MAC preamble. A copy goes into an on-ASIC replay buffer guarded by a short link timer."]}),"\n"]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Hop-by-Hop Link Layer Reliability (LLR) Replay Sequence (Switch 1 <-> Switch 2):\n- Clean arrival (SEQ = 1): Switch 2 receives SEQ = 1 cleanly and returns link-level ACK -> Switch 1 flushes SEQ = 1 from its replay buffer\n- Wire corruption or loss (SEQ = 2 or SEQ = 3): if SEQ = 2 times out, or if SEQ = 3 is lost and SEQ = 4 arrives out of order, Switch 2 immediately returns NACK SEQ = 3 -> Switch 1 retransmits the missing frame from its local ASIC replay buffer in hundreds of nanoseconds, hiding the optical bit error from end-to-end UET PDS\n"})}),"\n",(0,a.jsx)(t.p,{children:"The PSN sequence numbers already guarantee reliable transport end to end. Think of a PSN as a page number on a letter. The receiver can tell which page is missing, and it can ask for only that page again. The trouble is that, in a large fabric, every drop forces the original sender to retransmit, and that delay can hold up the whole AI job. LLR helps by managing retransmission between neighboring nodes instead of between end hosts."}),"\n",(0,a.jsx)(t.p,{children:"Think of LLR as a handshake between two neighbors who agree to watch each other's mail. Both sides must say yes before the watching starts, which is why the capability is advertised first."}),"\n",(0,a.jsx)(t.p,{children:"The LLR capability is advertised between two switches, or between a host NIC and a switch. The LLR state machine runs only when both nodes agree. If only one side supports it, LLR is ignored, and normal end-to-end PSN and ACK, NACK, and SACK reliability takes over. When LLR is active, the two levels of reliability work together, which gives double-level control. The result should be a better job completion time, especially where congestion risk is high. Measure job completion time before and after, because a feature that looks good in theory can still add delay on a link that was already clean."}),"\n",(0,a.jsxs)(t.p,{children:["LLR has to live in the ASIC so that it does not slow end-to-end traffic. A chip-level replay buffer can answer a neighbor's request in hundreds of nanoseconds, while a software path would take far longer. That speed is the reason LLR is built into the silicon rather than the software. If the MAC client does not want LLR, or the frame is not eligible, the frame goes out as a standard Ethernet frame. An eligible frame gets a sequence number and a copy in a replay buffer, in case the link partner does not receive it. Here is how a lossy link recovers. Switch1 sends ",(0,a.jsx)(t.code,{children:"SEQ"})," 1 and stores a copy with a timer running. Switch2 receives it and returns an ACK, so Switch1 clears its copy."]}),"\n",(0,a.jsxs)(t.p,{children:["Next, ",(0,a.jsx)(t.code,{children:"SEQ"})," 2 is lost in transit. The timer expires, and Switch1 resends it. Then ",(0,a.jsx)(t.code,{children:"SEQ"})," 3 is lost while ",(0,a.jsx)(t.code,{children:"SEQ"})," 4 arrives first. Switch2 sees the gap and sends ",(0,a.jsx)(t.code,{children:"NACK SEQ 3"}),", so Switch1 resends the missing frame. The sender never has to involve the end hosts for that repair. That is the part to remember: the repair stays between two neighbors. The end hosts never see the lost frame, so their timers and their windows keep running as if nothing happened at that hop."]}),"\n",(0,a.jsx)(t.p,{children:"LLR is still optional. Think of it as a second safety net under the first one. Operators can add it on the links where loss is most costly, and leave it off where the link is short and clean. It complements RUD, ROD, and RUDI retransmissions with PSN-based recovery. Retransmission happens at the link level instead of at the server level, so for the PDC the LLR step can stay transparent. LLR suits latency-sensitive AI work, such as inference on GPU servers, where segment-level control may give a positive outcome. You decide whether to enable it per link, so plan the links one at a time. Enable it on one link, measure the result, and only then move to the next link. A change made everywhere at once makes the cause of any new problem hard to find."}),"\n",(0,a.jsx)(t.h3,{id:"43-in-network-collectives-inc-vs-user-space-xccl-management-interoperability-and-compliance",children:"4.3 In-Network Collectives (INC) vs User-Space xCCL, Management, Interoperability, and Compliance"}),"\n",(0,a.jsxs)(t.p,{children:["Under the UEC Software Working Group, the Libfabric ",(0,a.jsx)(t.code,{children:"fi_collective"})," API bridges PyTorch, Open MPI, MPICH (",(0,a.jsx)(t.code,{children:"MPI_Allreduce"}),", ",(0,a.jsx)(t.code,{children:"MPI_Alltoall"}),"), and vendor xCCLs to switch-assisted In-Network Collectives:"]}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Switch-assisted INC execution:"})," An out-of-band INC Manager talks to INC Agents running inside ",(0,a.jsx)(t.code,{children:"sFEPs"})," over gRPC. For collective groups (",(0,a.jsx)(t.code,{children:"Collectives-gr1"}),", ",(0,a.jsx)(t.code,{children:"Collectives-gr2"}),"), leaf INC agents forward vectors to an elected root-of-tree spine switch (",(0,a.jsx)(t.code,{children:"Spine 1"})," or ",(0,a.jsx)(t.code,{children:"Spine 2"}),"). That root spine switch aggregates or replicates the collective flow once in hardware, then distributes the result downstream."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Management, interoperability, and certification:"})," UET exports per-flow telemetry that tracks CBFC and RCCC credits, latency, jitter, and drops across Libfabric, MPI, NCCL, RCCL, and the INC Manager. For backward compatibility, UEC Specification v1.0 supports dual-mode link negotiation, so brownfield IP fabrics can run lossless RoCEv2 alongside end-to-end UET. Link-level CBFC and LLR are reserved for greenfield deployments. The UEC compliance suite validates multi-vendor interoperability, line-rate performance, and TSS security across the AI Base, AI Full, and HPC profiles."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"INC refers to compute work done inside the network. Picture a relay where a switch takes several small envelopes from its neighbors, combines them into one, and passes that single envelope along. The work is the same sum, but far fewer envelopes cross the links. A common example is aggregation for AllReduce, an idea first introduced in NVIDIA's SHARP framework. INC supports an xCCL with network-level optimizations, such as data transformation, filtering, and in-network routing decisions tuned to each collective. Grouping a collective's flows onto specific switches and servers improves GPU use and latency."}),"\n",(0,a.jsx)(t.p,{children:"Hierarchical aggregation at a switch, such as a spine, cuts data copies and data movement. Think of a regional post office that sorts the mail before it goes to the local branches, so fewer bags travel the long route. Here is the practical view. Think of the stack as a set of translators. Each one passes the request to the next, and each one must understand the message it receives before it can pass it on. PyTorch calls down into MPI, and MPI calls Libfabric. Libfabric sends the collective request both to the INC manager and to the network fabric. The INC manager reaches the switch agents over an out-of-band control path using gRPC. If you debug INC, start with the manager and work down to the agents."}),"\n",(0,a.jsxs)(t.p,{children:["Two collective groups, ",(0,a.jsx)(t.code,{children:"Collectives-gr1"})," and ",(0,a.jsx)(t.code,{children:"Collectives-gr2"}),", each hold their own leaf agents and root-of-tree spine agents. The sFEP, an Ethernet switch that runs UEC and INC, has the INC engine built into the silicon's microkernel. The INC manager (IM) handles control and coordination for these agents. It decides which switch is the root of each tree, and it does not carry the data itself. That split keeps the control path separate from the data path."]}),"\n",(0,a.jsx)(t.p,{children:"Take one simple case. Picture a result that one server must share with two others. The naive path sends two full copies, and the smarter path sends one copy to a switch that does the fan-out. The second path uses less bandwidth on the link that is most likely to be busy. GPU-server1 needs to send the result of its local computation to GPU-server2 and GPU-server3. Instead of sending two copies, it sends one copy to the spine elected as the INC tree root. That root distributes the result to the rest of the switches in the group. Bandwidth is saved between leaf and spine, and latency is more even across the servers. Consider the same case with your own server names. Write the path on paper, with each hop labeled, and mark the point where the copy count drops. That mark is where the saving happens."}),"\n",(0,a.jsx)(t.p,{children:"The table compares INC with xCCLs. Read each row as a question about where the work happens. When the answer is in the switch, the fabric carries the load. When the answer is on the host, the servers carry it."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Feature"}),(0,a.jsx)(t.th,{children:"INC"}),(0,a.jsx)(t.th,{children:"xCCLs"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Layer"}),(0,a.jsx)(t.td,{children:"Fabric level (hardware)"}),(0,a.jsx)(t.td,{children:"Software library (user space)"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Primary execution"}),(0,a.jsx)(t.td,{children:"Inside network switches (sFEPs)"}),(0,a.jsx)(t.td,{children:"On host CPUs using standard protocols"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Integration"}),(0,a.jsx)(t.td,{children:"Needs Libfabric and INC switches"}),(0,a.jsx)(t.td,{children:"Integrates with MPI or AI frameworks, and the switch is transparent"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Offload capabilities"}),(0,a.jsx)(t.td,{children:"Yes (to the switches)"}),(0,a.jsx)(t.td,{children:"When paired with INC"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Performance"}),(0,a.jsx)(t.td,{children:"Lower latency, higher throughput, and optimized GPU utilization"}),(0,a.jsx)(t.td,{children:"Optimized GPU utilization"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Scalability"}),(0,a.jsx)(t.td,{children:"Very high in supported fabrics, depending on the type of collective set"}),(0,a.jsx)(t.td,{children:"Limited by server library software optimization"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Required infrastructure"}),(0,a.jsx)(t.td,{children:"INC-capable switches, INC manager, and Libfabric"}),(0,a.jsx)(t.td,{children:"Standard NICs and the MPI/CCL stack"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Implementation"}),(0,a.jsx)(t.td,{children:"UEC fabrics with INC switches and an INC manager"}),(0,a.jsx)(t.td,{children:"PyTorch DDP, TensorFlow, and MPI collectives"})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"An INC deployment usually has three parts. Think of them as the hardware, the coordinator, and the software library. Missing any one of the three leaves the feature switched on in name only. It needs INC-capable switches with sFEPs and agents, an INC manager for control and coordination, and Libfabric software integration."}),"\n",(0,a.jsx)(t.p,{children:"Compliance requires observability APIs, formal test methods, and procedures that validate interoperability. Think of compliance as the inspection that lets two cars from different factories share one highway safely. Without that inspection, each vendor's trucks may use different rules on the same road. Before the specification becomes a production standard, all the related tooling must exist. A standard without tools is a document, and operators need tools that show them the counters, the credits, and the failures in one place. That includes telemetry for UEC-specific features, such as CBFC credits and RCCC credits. The AI Base, AI Full, and HPC profiles let teams fit deployments to different scales and uses. Before you buy, ask which profile your vendor supports."}),"\n",(0,a.jsx)(t.p,{children:"The compliance suite covers three areas."}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsx)(t.li,{children:"Interoperability testing across multiple vendors and device types."}),"\n",(0,a.jsx)(t.li,{children:"Line-rate performance benchmarks for latency, jitter, and throughput."}),"\n",(0,a.jsx)(t.li,{children:"Security validation, including encryption and authentication methods."}),"\n"]}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Dimension"}),(0,a.jsx)(t.th,{children:"InfiniBand (IBTA)"}),(0,a.jsx)(t.th,{children:"RoCEv2 (DCQCN)"}),(0,a.jsx)(t.th,{children:"Ultra Ethernet (UET / UEC v1.0)"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Target Cluster Scale"})}),(0,a.jsx)(t.td,{children:"< 100,000 endpoints (48,000 per 16-bit LID subnet)"}),(0,a.jsx)(t.td,{children:"> 100,000 endpoints"}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"~1 million endpoints"})})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Wire Encapsulation"})}),(0,a.jsx)(t.td,{children:"Native InfiniBand (LRH/GRH/BTH)"}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.code,{children:"Ethernet / IP / UDP (4791) / BTH"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:(0,a.jsx)(t.code,{children:"UDP (49150) + PDS/SES"})})," or ",(0,a.jsx)(t.strong,{children:(0,a.jsx)(t.code,{children:"Native IP (253) + PDS/SES"})})]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Delivery & Loss Recovery"})}),(0,a.jsx)(t.td,{children:"Reliable Connected (RC) in-order; Go-Back-N / IB retry"}),(0,a.jsx)(t.td,{children:"RC in-order (Go-Back-N window flush on single loss)"}),(0,a.jsxs)(t.td,{children:["Flexible ",(0,a.jsx)(t.strong,{children:"ROD / RUD / RUDI / UUD"})," with selective retry"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Congestion & Flow Control"})}),(0,a.jsx)(t.td,{children:"Link-level 16 VLs + 64B CBFC credits"}),(0,a.jsx)(t.td,{children:"PFC (8 priorities) + ECN + DCQCN manual tuning"}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"NSCC (RTT/ECN), RCCC (256B credits), CBFC (32 VCs), Packet Trimming, LLR"})})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Security & In-Network Collectives"})}),(0,a.jsxs)(t.td,{children:["Partition keys (",(0,a.jsx)(t.code,{children:"P_Key"}),"); optional SHARP"]}),(0,a.jsx)(t.td,{children:"External MACsec / IPsec; no native Ethernet INC"}),(0,a.jsxs)(t.td,{children:["Built-in ",(0,a.jsx)(t.strong,{children:"TSS (AES-GCM)"}),"; optional ",(0,a.jsxs)(t.strong,{children:["INC (sFEP + IM + ",(0,a.jsx)(t.code,{children:"fi_collective"}),")"]})]})]})]})]}),"\n",(0,a.jsx)(t.h3,{id:"44-comparing-uec-to-infiniband-and-rocev2",children:"4.4 Comparing UEC to InfiniBand and RoCEv2"}),"\n",(0,a.jsx)(t.p,{children:"Suppose a buyer asks which fabric to choose for a cluster that will grow for five years. The answer depends on the features they need now, the features they will need later, and how much risk they can accept while the standard matures."}),"\n",(0,a.jsx)(t.p,{children:"Ultra Ethernet v1.0 sets a new standard for scale-out data center and high-performance networking. It offers flexible reordering, high scalability, high bandwidth, deterministic communication, stronger security, and simpler management. Adoption depends on the cost and complexity of upgrading infrastructure. Interoperability with the wide range of existing Ethernet equipment matters just as much. You should weigh that as heavily as the raw performance numbers."}),"\n",(0,a.jsx)(t.p,{children:"The table compares InfiniBand, RoCEv2, and UET on the main requirements. Each row is a different question a buyer asks. Read the congestion and security rows first, because they change the operating effort for the whole life of the cluster. UET aims for lower latency, higher throughput, and better scalability than earlier options. It adds determinism for time-sensitive flows through specified delivery intervals, which standard Ethernet does not offer. Libfabric adds open, standards-based programmability, so teams can shape network behavior with open APIs and programmable hardware. Ask yourself which of these you need before you read the table row by row."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Requirement"}),(0,a.jsx)(t.th,{children:"InfiniBand"}),(0,a.jsx)(t.th,{children:"RoCEv2"}),(0,a.jsx)(t.th,{children:"UET"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Scale"}),(0,a.jsx)(t.td,{children:"under 100,000"}),(0,a.jsx)(t.td,{children:"over 100,000"}),(0,a.jsx)(t.td,{children:"about 1 million (target)"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Performances (JCT, BUS BW)"}),(0,a.jsx)(t.td,{children:"High"}),(0,a.jsx)(t.td,{children:"High; comparable to InfiniBand"}),(0,a.jsx)(t.td,{children:"High; same as or better than InfiniBand"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Multipathing"}),(0,a.jsx)(t.td,{children:"Yes"}),(0,a.jsx)(t.td,{children:"Yes"}),(0,a.jsx)(t.td,{children:"Yes"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Congestion control"}),(0,a.jsx)(t.td,{children:"Yes; credit/credit"}),(0,a.jsx)(t.td,{children:"DCQCN (ECN, PFC-DSCP), controller-based auto-tuning"}),(0,a.jsx)(t.td,{children:"NSCC (RTT/ECN), RCCC, packet trimming, CSIG, CBFC, auto-tunning built-in protocol"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Delivery modes"}),(0,a.jsx)(t.td,{children:"Reliable connect (RC); in-order, unreliable connect"}),(0,a.jsx)(t.td,{children:"RC; in-order, unreliable connect"}),(0,a.jsx)(t.td,{children:"Flexible delivery; RUD/RUDI/UUD"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Security"}),(0,a.jsx)(t.td,{children:"N/A"}),(0,a.jsx)(t.td,{children:"External security stack (for example, MAC-Sec)"}),(0,a.jsx)(t.td,{children:"Built-in the UEC protocol stack \u2013 using the TSS"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Encapsulation options"}),(0,a.jsx)(t.td,{children:"InfiniBand"}),(0,a.jsx)(t.td,{children:"UDP/BTH in IPv4 or IPv6"}),(0,a.jsx)(t.td,{children:"UDP/SES and PDS in IPv4/IPv6 or IP and SES/PDS without UDP"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Network deployment readiness"}),(0,a.jsx)(t.td,{children:"Deployed in production networks"}),(0,a.jsx)(t.td,{children:"Deployed in production networks"}),(0,a.jsx)(t.td,{children:"Expected first pilot deployments in late 2026"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"NIC diversity"}),(0,a.jsx)(t.td,{children:"Low"}),(0,a.jsx)(t.td,{children:"High"}),(0,a.jsx)(t.td,{children:"Low"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"UET-compatible fabric transport"}),(0,a.jsx)(t.td,{children:"No"}),(0,a.jsx)(t.td,{children:"Yes"}),(0,a.jsx)(t.td,{children:"Yes"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Interoperability"}),(0,a.jsx)(t.td,{children:"Bad"}),(0,a.jsx)(t.td,{children:"Good"}),(0,a.jsx)(t.td,{children:"Good"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"Transport"}),(0,a.jsx)(t.td,{children:"InfiniBand"}),(0,a.jsx)(t.td,{children:"Ethernet/IP/UDP"}),(0,a.jsx)(t.td,{children:"Ethernet/IP/UDP"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:"INC/CCL"}),(0,a.jsx)(t.td,{children:"Yes (optional)"}),(0,a.jsx)(t.td,{children:"No"}),(0,a.jsx)(t.td,{children:"Yes (optional)"})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"You do not have to switch on every UEC feature at once. A phased rollout lets your team learn one feature at a time, and it gives you a clean baseline to compare against when something changes. Teams can enable a subset of features and still move past the go-back-to-N limits of RoCEv2. Keep the table in mind when you choose a transport for a new cluster. It shows where each option is strong and where it is still early."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"5-scale-up-systems-architecture-ocp-sue-t-esun-ualink-10-and-memory-coherence",children:"5. Scale-Up Systems: Architecture, OCP SUE-T (ESUN), UALink 1.0, and Memory Coherence"}),"\n",(0,a.jsx)(t.h3,{id:"51-why-scale-up-pods-exist-latency-bandwidth-and-the-4-rack--1000-xpu-boundary",children:"5.1 Why Scale-Up Pods Exist: Latency, Bandwidth, and the 4-Rack / 1,000-xPU Boundary"}),"\n",(0,a.jsx)(t.p,{children:"Picture a conversation that must go back and forth thousands of times per second between a small group of accelerators. Every reply waits for the one before it, so a delay of a few hundred nanoseconds becomes a visible slowdown. That is the problem scale-up fabrics are built to solve."}),"\n",(0,a.jsx)(t.p,{children:"Scale-out networks connect independent servers across multi-tier leaf-spine fabrics, using external 400G or 800G NICs over PCIe. Seven latency-critical AI workloads, however, exchange activations at a sub-microsecond cadence. Picture each workload as a conversation that cannot pause for long. A reply that arrives late stalls the next step, and the accelerator waits with nothing to do. They include foundational LLM training, multimodal text-to-video diffusion, Mixture-of-Experts token routing, and multi-step reasoning. They also include digital-twin physics simulation, Graph Neural Networks with sparse neighbor reads, nanosecond financial risk modeling, and edge federated inference. External NICs and PCIe buses cannot feed these workloads without stalling the accelerators. Consider one of these workloads, and you can see why the interconnect matters for it. A model that spends most of its time waiting on a neighbor is limited by the wire, however fast the chips are."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Scale-Up Interconnect vs PCIe / CXL Latency, Bandwidth, and Pod Geometry Specs:\n- PCIe 5.0: 500 ns to 1 us latency, 32 GT/s per lane, 3.94 GB/s per lane (64 Gbps / 63.02 GB/s unidirectional on x16)\n- PCIe 6.0: 8 GB/s per lane (~128 GB/s / ~128 Gbps bidirectional on x16)\n- CXL 3.0: ~100 ns cache-coherent shared memory latency, tied to PCIe 6.0 (32 GT/s) per-lane bandwidth\n- NVIDIA NVLink 5 (NVL72): 100-300 ns latency, 1.8 Tbps (1,800 Gbps) bidirectional per GPU across 18 NVLink switches connecting 72 GPUs (B300 compute tray packs 4 GPUs with 1,152 GB aggregate HBM3)\n- Scale-up workload examples: text-to-video diffusion spreading 1,024 images across 512 xPUs at 2 images per micro-batch; GNN irregular sparse reads at ~300 ns\n- Physical scale-up pod geometry: 72 to 1,000 xPUs across 1 to 4 pre-engineered racks (pods), < 4 m in-rack copper/optical cables, 200 Gbps SerDes lanes from on-die interconnect points (IP) into single-hop scale-up switches (ESUN/SUE-T, UALink Switches ULS, or NVSwitch) at 200-300 ns port-to-port latency (< 1 us end-to-end RTT)\n- Horizontal pod-to-pod scale-out: separate 400G/800G scale-out NICs over PCIe Gen5/Gen6 across multi-plane Fabric Plane 1 | Plane 2 Clos networks\n"})}),"\n",(0,a.jsx)(t.p,{children:"Across dense accelerator scale-up systems, the main goal is simpler and faster memory access. Think of the goal as a shared whiteboard that every team member can write on directly, instead of passing notes across the room. Engineers want a large model to look like one memory space that every accelerator can reach directly. That keeps the software stack smaller. The high-bandwidth memory (HBM) on many accelerators then reads as one coherent pool. Moving data from one accelerator to another also carries less overhead. There is no IP or UDP header to add, and no multi-stage network to cross. The path becomes an optimized Ethernet switch system with one hop. For a large language model, the aim is a more direct memory load semantic, and a faster one. Each xPU sees a more coherent multi-xPU high-bandwidth memory view. A tensor that one accelerator writes can be read by another without a separate copy step, which removes a layer of bookkeeping from the training code. Less fabric interconnect setup is needed, and the software stack stays simple. For you as a designer, that means fewer moving parts to configure."}),"\n",(0,a.jsx)(t.p,{children:"Multimodal models form another use case. Picture a diffusion model that runs many small denoising steps, and syncs its gradients after each batch of images. The sync cost repeats thousands of times, so the interconnect cost is paid again and again. Text-to-video, audio, and 3D generators rely on diffusion models. These models move large tensors between GPUs, and they must sync often. That exchange can repeat thousands of times for each batch. Here is a concrete case. A batch of 1,024 images spreads across 512 xPUs. Each xPU handles two images as a micro-batch. After that, the xPUs sync their gradients across the interconnect point for one step. The sync runs over the whole shared memory, so the model behaves as if it trained on a single xPU. You can picture the whole pod as one large accelerator from the software side."}),"\n",(0,a.jsx)(t.p,{children:"Work the numbers yourself. The point is to see how a large batch divides cleanly across the pod, so that each accelerator has a fair share of the work before the sync step. Each xPU holds 2 images, and 512 xPUs hold 1,024 images in total, so one step covers the full batch. Every xPU then syncs its gradients once across the shared memory."}),"\n",(0,a.jsx)(t.p,{children:"Financial risk analysis is another case. Picture a risk model that must refresh its exposure numbers as the market moves. A slow shared memory view means stale numbers, and stale numbers are a cost the business feels right away. Traders and analysts need to see market volatility and their exposure quickly. Real-time market models keep updating with fresh financial data. High-frequency algorithms use that data to predict trends, tune trading strategies, and manage risk as the economy changes. What ties these cases together is the need for many accelerators to share one fast memory view. Whatever your workload, that is the question to ask first."}),"\n",(0,a.jsx)(t.h3,{id:"52-open-compute-project-ocp-scale-up-ethernet-transport-sue-t--esun",children:"5.2 Open Compute Project (OCP) Scale-Up Ethernet Transport (SUE-T / ESUN)"}),"\n",(0,a.jsx)(t.p,{children:"Picture a tiny message that carries more header than data. Inside a rack, that ratio wastes wire time on every single transfer, and the waste adds up across millions of small loads and stores. The scale-up transport was designed to remove that waste."}),"\n",(0,a.jsx)(t.p,{children:"Standard Ethernet frames carry tens of bytes of IP, UDP, and RDMA headers. On the small 64-byte or 256-byte memory loads and stores inside a rack, those headers waste wire bandwidth. Announced in October 2025 under the OCP Ethernet Scale-Up Networking initiative, Scale-Up Ethernet Transport adapts standard 100 Gbps and 200 Gbps PAM-4 Ethernet PHY and MAC silicon for single-hop scale-up pods. It replaces IP, UDP, and BTH with two compact Layer 2 headers. Think of the swap as trading a long address label for a short sticker that carries only what the switch needs to route the frame inside the rack."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"OCP SUE-T (ESUN) Framing, Header Efficiency, and On-Die Interface Specifications:\n- Physical interface scaling: 100G/200G PAM-4 SerDes (800G, 1.6T, or 3.2T per SUE interface; e.g., 12 SUE instances x 12 lanes per xPU connected 1:1 to 12 ESUN switches, ~250 ns switch hop latency)\n- Base frame and PDU sizes: converts a 256-byte frame into a scale-up flit carrying up to a 4,096-byte SUE PDU over a Virtual Channel (VC)\n- AI Fabric Header (AFH Generation 2):\n  1. Compressed AFH (6 bytes): for single-hop scale-up pods; encodes Destination xPU, Traffic Class, Source xPU, Opaque bits, and control flags (V version 0, W compressed vs non-compressed format/hop count, Z administratively assigned local MAC identifier, X/Y/R reserved, M multicast) inside Ethernet DMAC/SMAC positions\n     -> 256B payload + 6B AFH Gen 2 + 2B EtherType + 8B RH + 8B R-CRC/FCS = 280 bytes total (91.43% payload efficiency)\n  2. Non-Compressed AFH (12 bytes): for two-hop scale-up topologies\n     -> 256B payload + 12B AFH Gen 2 + 2B EtherType + 8B RH + 8B R-CRC/FCS = 286 bytes total (89.51% payload efficiency)\n- Reliability Header (RH, 8 bytes after EtherType, before SUE Payload + R-CRC + PAD + FCS):\n  Row 1: VER, OP (opcode), RSV, 10-bit xPU ID (up to 1,024 xPUs), 16-bit NPSN (Next/Packet Sequence Number)\n  Row 2: VC (4 or more virtual channels), RSV, Partition (multi-tenant virtual pod isolation), 16-bit APSN (Acknowledge Sequence Number)\n- Two On-Die xPU-to-SUE Interfaces:\n  1. FIFO Interface: 1 raw PDU stream using a 10-bit xPU identifier + 2-bit VC identifier\n  2. ARM AXI 4.0 Interface: 5 independent memory transaction channels mapped across 2 VCs:\n     - Requests on VC0: AR (Read Address), AW (Write Address), W (Write Data)\n     - Responses on VC1: B (Write Response), R (Read Data)\n"})}),"\n",(0,a.jsx)(t.p,{children:"The header choice comes down to two cases, and the efficiency numbers make the difference concrete. Think of the header as the envelope around a letter. A thinner envelope leaves more room for the letter itself, and the percentages show how much of each frame is letter and how much is envelope. Take a 256-byte payload. With the 6-byte compressed header, the frame is 280 bytes, and the payload is 91.43% of it. With the 12-byte non-compressed header for two-hop topologies, the frame is 286 bytes, and the payload is 89.51%. The compressed form is 6 bytes shorter, and the chapter pairs it with single-hop pods. If your pod has two hops, you need the 12-byte header instead."}),"\n",(0,a.jsx)(t.p,{children:"The SUE-T design rests on three pieces, and each one is worth a closer look. Each piece answers one question. How is the frame addressed, how is it kept reliable, and how does the accelerator hand it over?"}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"AI Fabric Header Generation 2:"})," It replaces standard MAC addressing with a 6-byte compressed header for single-hop pods, or a 12-byte non-compressed header for two-hop topologies. Both formats keep IEEE Ethernet frame compatibility."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Reliability Header and dual-layer loss recovery:"})," The 8-byte Reliability Header sits right after the EtherType. It tracks end-to-end sequence numbers, ",(0,a.jsx)(t.code,{children:"NPSN"})," and ",(0,a.jsx)(t.code,{children:"APSN"}),", across up to 1,024 xPUs. Hop-by-hop Link Layer Reliability retransmits lost frames from the ESUN switch replay buffer, and link-level CBFC prevents buffer overflow."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"On-die FIFO and ARM AXI 4.0 interfaces:"})," Between the xPU compute core and the on-die SUE transport block, designers choose either a raw streaming FIFO interface or a 5-channel ARM AXI 4.0 memory interface. The AXI 4.0 interface keeps read and write requests (",(0,a.jsx)(t.code,{children:"AR"}),", ",(0,a.jsx)(t.code,{children:"AW"}),", ",(0,a.jsx)(t.code,{children:"W"}),") on ",(0,a.jsx)(t.code,{children:"VC0"}),", separate from read and write responses (",(0,a.jsx)(t.code,{children:"B"}),", ",(0,a.jsx)(t.code,{children:"R"}),") on ",(0,a.jsx)(t.code,{children:"VC1"}),". You should keep that split in mind when you read a trace."]}),"\n"]}),"\n",(0,a.jsx)(t.p,{children:"Figure 13-7 walks the whole SUE stack from Accelerator 1 on the left, through a Scale up Switch in the center, to Accelerator 2 on the right. The SUE stack sits on the left of each column, and Ethernet is labeled on the right. The accelerator's transaction layer sends data down through the interface layer and the packing or mapping layer. The packing layer and the transport layer together form the SUE transport. The transport layers on both ends exchange ordering and reliability information. Next comes the network header layer, which carries the AFH on both ends. Below it sit the Ethernet MAC layer, the reconciliation layer, RS FEC, the PMA or PMD layer, and the PHY. The MAC layers on each end exchange LLR and CBFC information with the switch. Read the figure from left to right, and you will follow one write from the accelerator to the far side."}),"\n",(0,a.jsx)(t.p,{children:"Figure 13-8 shows the links that come up when the system boots. Accelerator 1, labeled ACC1 xPU 1, has an on-die interconnect point that can be FIFO or AXI 4. Each accelerator has twelve SUE segments, and each segment has twelve lanes, labeled E 1 through E 12. Every SUE segment fans out to all twelve ESUN switches. On the far accelerator, each switch reaches its matching segment, so ESUN 1 pairs with SUE 1 and ESUN 12 pairs with SUE 12. Each link runs as 200 Gbps or 100 Gbps SerDes Ethernet with AFH. When you bring up a new pod, check each link against this pattern. A link that is missing from the expected map is a cabling fault until proven otherwise, and finding it early saves a long search later."}),"\n",(0,a.jsx)(t.h3,{id:"53-ultra-accelerator-link-ualink-10-64-tbps-stations-64b640b-flits-upli-and-gva---npa---spa",children:"5.3 Ultra Accelerator Link (UALink 1.0): 6.4 Tbps Stations, 64B/640B Flits, UPLI, and GVA -> NPA -> SPA"}),"\n",(0,a.jsx)(t.p,{children:"Suppose a message must cross several switches between two accelerators. Each switch that waits for a full variable-length frame adds a little delay, and those small delays stack up. The UALink design attacks that stacking at its source."}),"\n",(0,a.jsxs)(t.p,{children:["Variable-length Ethernet frames and standard 4-way Reed-Solomon FEC codeword interleaving add hundreds of nanoseconds of delay at every switch hop. The Ultra Accelerator Link Specification 1.0 removes variable-length Ethernet framing altogether. It connects up to 1,000 accelerators across single-hop UALink Switches (",(0,a.jsx)(t.code,{children:"ULS 0..31"}),") or direct full-mesh ",(0,a.jsx)(t.code,{children:"UALink Direct"})," links. Every transfer uses fixed-size flits that align 1:1 with physical PCS codewords. If you come from Ethernet, this is the biggest change you will notice. Ethernet engineers are used to thinking in packets and MAC addresses. In this protocol, the unit is a fixed-size flit and the address is a memory location, so the mental model must shift."]}),"\n",(0,a.jsx)(t.mermaid,{value:'flowchart TB\n  subgraph Src["Source xPU (GVA Space)"]\n    S_App["Application / PGAS<br/>Load, Store, Atomic"] --\x3e S_UPLI["UPLI Originator<br/>Req & OrigData (57b Addr)"]\n    S_UPLI --\x3e S_MMU["Source MMU + PTE<br/>Address Handle -> NPA"]\n    S_MMU --\x3e S_TL["Transaction Layer (TL)<br/>64B Flits (16x4B Sectors)"]\n    S_TL --\x3e S_DL["Data Link Layer (DL)<br/>10x64B = 640B Flit + 8B CRC"]\n    S_DL --\x3e S_PL["Physical Layer (PL)<br/>680B w/ 40B FEC, 1/2-Way"]\n  end\n  subgraph Sw["UALink Switches (NPA Space)"]\n    S_PL --\x3e ULS["ULS 0..31 (200G SerDes)<br/>8 Stations x 4 Lanes = 6.4T"]\n  end\n  subgraph Dst["Destination xPU (SPA Space)"]\n    ULS --\x3e D_PL["Dest PL / DL / TL<br/>RS(544,514) Decode & Replay"]\n    D_PL --\x3e D_MMU["Dest Link MMU<br/>NPA (10b ACC-ID) -> SPA"]\n    D_MMU --\x3e D_HBM["UPLI Completer &<br/>Local HBM3/HBM4 Cache"]\n  end'}),"\n",(0,a.jsx)(t.p,{children:"The table below lays out each layer and its job, from the stations down to the address translation. Use it as a lookup when a capture confuses you. Find the layer that the field belongs to, then read that row to learn what the field is for."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"UALink 1.0 Layer / Mechanism"}),(0,a.jsx)(t.th,{children:"Quantitative Specification & Framing"}),(0,a.jsx)(t.th,{children:"Architectural Function"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Stations & Per-xPU Bandwidth"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"8 Stations per xPU x 4 lanes per Station x 200 Gbps (200 GT/s) SerDes = 32 lanes = 6,400 Gbps (6.4 Tbps)"})," aggregate bandwidth per accelerator."]}),(0,a.jsx)(t.td,{children:"Delivers 8x\u201316x the bandwidth of a single 400G/800G scale-out NIC over < 4 m in-rack cables."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"UPLI (Protocol Level Interface)"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Four channelized links"})," between UPLI Originator and UPLI Completer: ",(0,a.jsx)(t.strong,{children:"Req"})," (Request), ",(0,a.jsx)(t.strong,{children:"OrigData"})," (Write Request Data), ",(0,a.jsx)(t.strong,{children:"RD Res"})," (Read Response + Data), and ",(0,a.jsx)(t.strong,{children:"WR Res"})," (Write Response)."]}),(0,a.jsxs)(t.td,{children:["Carries a ",(0,a.jsxs)(t.strong,{children:["57-bit ",(0,a.jsx)(t.code,{children:"ReqAddr"})]}),", ",(0,a.jsx)(t.code,{children:"ReqCmd"}),", credit return/release counts, and ",(0,a.jsxs)(t.strong,{children:["10-bit ",(0,a.jsx)(t.code,{children:"ReqSrcPhysAccID"})," / ",(0,a.jsx)(t.code,{children:"DSTACCID"})]})," (up to 1,000 accelerators per pod)."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Transaction Layer (TL) Flits"})}),(0,a.jsxs)(t.td,{children:["Fixed ",(0,a.jsx)(t.strong,{children:"64-byte TL flits"}),", organized into ",(0,a.jsx)(t.strong,{children:"16 x 4-byte sectors"})," and split into an ",(0,a.jsx)(t.strong,{children:"Upper 32-byte Half-Flit"})," and ",(0,a.jsx)(t.strong,{children:"Lower 32-byte Half-Flit"})," (",(0,a.jsx)(t.code,{children:"Req0..Req3"})," control in lower half; ",(0,a.jsx)(t.code,{children:"Req0.Data"})," across halves)."]}),(0,a.jsxs)(t.td,{children:["Encodes semantic operations (",(0,a.jsx)(t.code,{children:"read"}),", ",(0,a.jsx)(t.code,{children:"write"}),", ",(0,a.jsx)(t.code,{children:"atomic"}),", ",(0,a.jsx)(t.code,{children:"RMA_SYNC"}),", ",(0,a.jsx)(t.code,{children:"NOTIFY"}),", ",(0,a.jsx)(t.code,{children:"RMA_FENCE"}),", ",(0,a.jsx)(t.code,{children:"RMA_COMPLETION"}),", ",(0,a.jsx)(t.code,{children:"ATOMIC_ACK"}),")."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Data Link (DL) Flits & Replay"})}),(0,a.jsxs)(t.td,{children:["Packs ",(0,a.jsx)(t.strong,{children:"10 x 64-byte TL flits"})," from multiple sources/destinations into one ",(0,a.jsx)(t.strong,{children:"640-byte DL flit"})," plus ",(0,a.jsx)(t.strong,{children:"8-byte CRC"})," for link-level replay (",(0,a.jsx)(t.code,{children:"CRD"}),"/",(0,a.jsx)(t.code,{children:"RREQ"}),"/",(0,a.jsx)(t.code,{children:"ACK"}),"/",(0,a.jsx)(t.code,{children:"NACK"}),"), and ",(0,a.jsx)(t.strong,{children:"40-byte FEC"})," = ",(0,a.jsx)(t.strong,{children:"680-byte fixed wire unit"}),"."]}),(0,a.jsxs)(t.td,{children:["Eliminates variable-length Ethernet fragmentation and handles hop-by-hop link training, credit updates (",(0,a.jsx)(t.code,{children:"CRD"}),"), and CRC replay (",(0,a.jsx)(t.code,{children:"RREQ"}),")."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Physical Layer (PL) & PCS Alignment"})}),(0,a.jsxs)(t.td,{children:["One ",(0,a.jsx)(t.strong,{children:"640-byte DL flit maps 1:1 into one RS(544, 514) PCS codeword"})," (544/514 10-bit symbols; first several 257-bit blocks overwritten with 802.3 alignment markers). Uses ",(0,a.jsx)(t.strong,{children:"1-way or 2-way codeword interleaving"})," instead of standard 4-way Ethernet interleaving."]}),(0,a.jsx)(t.td,{children:"Waiting for only 1 or 2 codewords instead of 4 cuts FEC decoding latency by 4.0x or 2.0x (200\u2013300 ns switch hop latency), requiring purpose-built ULS switches."})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Address Translation (GVA -> NPA -> SPA)"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Guest Virtual Address (GVA)"})," -> Source MMU Page Table Entry (PTE) + ",(0,a.jsx)(t.strong,{children:"Address Handle ID"})," -> ",(0,a.jsx)(t.strong,{children:"Network Physical Address (NPA + 10-bit ACC-ID + key bits)"})," -> ULS switch forwarding -> Destination ",(0,a.jsx)(t.strong,{children:"Link MMU"})," -> ",(0,a.jsx)(t.strong,{children:"System Physical Address (SPA)"}),"."]}),(0,a.jsxs)(t.td,{children:["Replaces Ethernet MAC switching with hardware memory-address routing and ",(0,a.jsx)(t.strong,{children:"virtual pod partitioning"})," where 10-bit ACC-IDs remain constant across partition changes."]})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"The flit sizes form a simple chain, and the chain is what matters on the wire. Think of it as nesting boxes. Small boxes fit into a medium box, and the medium box fits into a shipping crate. Knowing each size tells you exactly what the next layer expects. A 64-byte TL flit holds 16 sectors of 4 bytes. Ten of those flits pack into one 640-byte DL flit, and the DL flit adds an 8-byte CRC. Forty bytes of FEC bring the total to a 680-byte wire unit. That wire unit lines up one-for-one with a single RS(544, 514) PCS codeword. If you follow the chain, you can check each size yourself."}),"\n",(0,a.jsx)(t.h3,{id:"54-hardware-directory-coherence-vs-software-pgas-coherence-and-scale-up-comparison",children:"5.4 Hardware Directory Coherence vs Software PGAS Coherence and Scale-Up Comparison"}),"\n",(0,a.jsx)(t.p,{children:"Assume that a multi-GPU kernel will behave the same on an open pod as it does on NVIDIA's NVL72 rack, and you can ship silent stale-memory bugs. When an engineer ports such a kernel from NVL72 to an open UALink or SUE-T pod, that assumption is the first thing to check. A fundamental architectural divide separates proprietary hardware-coherent pods from open software-coherent scale-up pods. In a hardware-coherent pod, the fabric keeps every cache copy up to date for you. In a software-coherent pod, your code must tell the fabric when a copy is safe to read. You need to know which kind of pod you run before you port any code."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Hardware cache coherence:"})," On NVLink and NVSwitch, AMD Infinity Fabric, and CXL 3.0, the fabric silicon enforces cache consistency automatically, without software intervention. A directory-based home agent tracks which xPU caches hold copies of each cache line. When GPU 1 writes to memory address X, the NVSwitch sends hardware invalidate snoop messages to all peer GPUs that cache line X. It collects the acknowledgments and then grants exclusive ownership to GPU 1. Hardware coherence allows transparent pointer dereferencing across 72 GPUs in NVL72. But snoop directory traffic scales poorly toward 1,000 accelerators, and it locks the pod to one vendor. You get transparent pointers, but you pay for it in scale and lock-in. Think of hardware coherence as a very attentive assistant who watches every room. The assistant works well for a small house, but the cost of watching grows fast as the house gets bigger."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Software-managed PGAS coherence:"})," To scale cleanly to 1,000 multi-vendor accelerators, UALink 1.0 and SUE-T leave out hardware cache snoops. They adopt a Partitioned Global Address Space memory model above the Transaction Layer. Runtime libraries such as NCCL, RCCL, SHMEM, CUDA, and ROCm explicitly coordinate cache flushes and memory visibility at collective boundaries. They do this with lightweight TL control verbs, ",(0,a.jsx)(t.code,{children:"RMA_FENCE"}),", ",(0,a.jsx)(t.code,{children:"RMA_SYNC"}),", ",(0,a.jsx)(t.code,{children:"NOTIFY"}),", ",(0,a.jsx)(t.code,{children:"RMA_COMPLETION"}),", and ",(0,a.jsx)(t.code,{children:"ATOMIC_ACK"}),". So when you port code to these pods, you add those barriers yourself."]}),"\n"]}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Capability"}),(0,a.jsx)(t.th,{children:"OCP SUE-T (ESUN)"}),(0,a.jsx)(t.th,{children:"UALink 1.0"}),(0,a.jsx)(t.th,{children:"NVIDIA NVLink 5 (NVL72)"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Wire / PHY Layer"})}),(0,a.jsx)(t.td,{children:"Standard Ethernet PHY (100G\u2013800G PAM-4)"}),(0,a.jsx)(t.td,{children:"Custom 802.3dj-aligned 200G PAM-4 (1-way/2-way FEC)"}),(0,a.jsx)(t.td,{children:"Proprietary NVIDIA NVLink 5 high-speed SerDes"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"On-Wire Unit"})}),(0,a.jsx)(t.td,{children:"Ethernet frame (256B base flit, up to 4,096B PDU) + 6B/12B AFH Gen 2 + RH"}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"64B TL flits"})," packed 10:1 into ",(0,a.jsx)(t.strong,{children:"640B DL flits"})," (680B with 40B FEC)"]}),(0,a.jsx)(t.td,{children:"Proprietary NVLink flits over 18 NVSwitch crossbars"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Memory & Coherence Model"})}),(0,a.jsxs)(t.td,{children:["One-sided PGAS (",(0,a.jsx)(t.code,{children:"put"}),"/",(0,a.jsx)(t.code,{children:"get"}),"/",(0,a.jsx)(t.code,{children:"atomic"}),") via FIFO or AXI 4.0; ",(0,a.jsx)(t.strong,{children:"software-managed"})," fences"]}),(0,a.jsxs)(t.td,{children:["PGAS (",(0,a.jsx)(t.code,{children:"load"}),"/",(0,a.jsx)(t.code,{children:"store"}),"/",(0,a.jsx)(t.code,{children:"atomic"}),"/",(0,a.jsx)(t.code,{children:"fence"}),"/",(0,a.jsx)(t.code,{children:"notify"}),") via GVA->NPA->SPA; ",(0,a.jsx)(t.strong,{children:"software-managed"})]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"Hardware-coherent"})," shared memory (directory + snoop invalidations via NVSwitch)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Reliability & Flow Control"})}),(0,a.jsx)(t.td,{children:"RH (16-bit NPSN/APSN) + hop-by-hop LLR + CBFC"}),(0,a.jsxs)(t.td,{children:["DL-level credits (",(0,a.jsx)(t.code,{children:"CRD"}),") + 8B CRC + replay (",(0,a.jsx)(t.code,{children:"RREQ"}),"/",(0,a.jsx)(t.code,{children:"ACK"}),"/",(0,a.jsx)(t.code,{children:"NACK"}),")"]}),(0,a.jsx)(t.td,{children:"Hardware retry and internal credit scheduler inside NVSwitch"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Topology Scope & Scale"})}),(0,a.jsx)(t.td,{children:"1-hop or 2-hop pod; up to 1,024 (10-bit xPU ID)"}),(0,a.jsxs)(t.td,{children:["In-rack / 4-rack pod up to ",(0,a.jsx)(t.strong,{children:"1,000 xPUs"})," (10-bit ACC-ID)"]}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.strong,{children:"72 GPUs"})," fully connected (NVL72)"]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"1-Hop Latency & Per-xPU BW"})}),(0,a.jsx)(t.td,{children:"~250 ns switch hop (< 1 us E2E); 0.8\u20133.2 Tbps typical"}),(0,a.jsxs)(t.td,{children:["200\u2013300 ns switch hop (< 1 us RTT); ",(0,a.jsx)(t.strong,{children:"up to 6.4 Tbps (8x4x200G)"})]}),(0,a.jsxs)(t.td,{children:["Tens of ns switch hop (100\u2013300 ns system); ",(0,a.jsx)(t.strong,{children:"1.8 Tbps (1,800 Gbps)"})," per GPU"]})]})]})]}),"\n",(0,a.jsx)(t.h3,{id:"55-pod-building-blocks-hbm-placement-and-vendor-scope",children:"5.5 Pod Building Blocks, HBM Placement, and Vendor Scope"}),"\n",(0,a.jsx)(t.p,{children:"A scale-up pod is not assembled part by part on the data center floor. Think of the pod as a prebuilt appliance that arrives with its wiring already done. Your job is to place it, power it, and connect its uplinks, which is far less work than building a fabric from parts. Vendors build the compute system with its parts already fitted into the rack. The chassis, its intra-chassis cabling, the optics, the management switches, and the storage units all arrive prebuilt. The buyer gets one management interface that covers the accelerators, the compute, and the storage. The options a buyer can change are limited. You should ask the vendor early which of those options you need. A late request for a different storage layout or a different NIC count can delay the whole rack by weeks."}),"\n",(0,a.jsx)(t.p,{children:"Picture a buyer who wants to add a second vendor's pod to an existing one. The question is whether the two chassis can share the same fabric. The answer, for most current products, is that the vendors do not design for that mix, so the buyer should plan separate pods."}),"\n",(0,a.jsx)(t.p,{children:"Interoperability between two vendors' scale-up chassis is not typically addressed. A common deployment uses one to four pods from the same vendor. Keeping one vendor inside the pod keeps the management plane, the firmware, and the support contract simple, which is worth more than a small saving on hardware. Those pods then connect to the existing scale-out systems. Think of the pods as large appliances that plug into the building's main supply, rather than as separate buildings that must talk to each other directly. If you plan a mixed-vendor design, check this yourself. Figure 13-1 shows four identical pods joined by a rack-to-rack link, which can use scale-out or scale-up extenders. The top bar is labeled Rack to Rack Interconnection, with Scale out or Scale up Extenders. From top to bottom, each pod holds out-of-band (OOB) management switches, power shelves, compute, and accelerators. Below them sits a boundary of interconnect switches, such as ESUN, UALink, or NVLink switches. Under that boundary come another accelerator block, compute, NVMe-oF storage, and power shelves. A three-tier IP Clos scale-out fabric can connect even more racks."}),"\n",(0,a.jsx)(t.p,{children:"A four-pod or four-rack scale-up system can hold from 72 to hundreds of xPUs. Picture the pod as one large room that holds many workers, where any worker can reach any tool in the room without walking through a door. Those xPUs can be GPUs, TPUs, or other accelerators. Each accelerator has its own HBM, placed physically next to it. The HBM is still exposed as part of one coherent shared memory to every other xPU. Each HBM module holds hundreds of gigabytes. Memory software manages the HBM, usually at the compute level. The compute host connects over PCIe, much like a multi-core CPU or ARM chip. When SUE or UALink switches carry the AI training traffic, that PCIe link is not used for it. So you do not need to route training traffic over the host bus."}),"\n",(0,a.jsx)(t.p,{children:"Figure 13-2 zooms into one compute node. A DDR CPU and a NIC sit stacked on the left, joined to a vertical PCIe bar. Two accelerators, ACC1 and ACC2, sit on the right, with HBM blocks inside dashed outlines above ACC1 and below ACC2. The middle section, labeled SUE switches, holds several switch blocks with bidirectional arrows. Each accelerator links to every SUE switch in a mesh. The next compute node, Compute n, follows the same layout with its own pair of accelerators."}),"\n",(0,a.jsx)(t.h3,{id:"56-single-hop-mesh-wiring-and-attaching-pods-to-fabric-planes",children:"5.6 Single-Hop Mesh Wiring and Attaching Pods to Fabric Planes"}),"\n",(0,a.jsx)(t.p,{children:"Picture a rack where any two accelerators can talk without passing a second switch. Every pair is one hop apart, so the latency between any two of them is the same. That property is useful for a model that must exchange data with every peer."}),"\n",(0,a.jsx)(t.p,{children:"Inside the rack, the wiring forms a full mesh that is only one hop wide. Figure 13-3 shows 64 accelerators, ACC1 through ACC64. A rounded box labeled Accelerators sits at the top, with a dashed range standing in for ACC2 through ACC63. Twelve scale-up switches are enabled in that rack. Each accelerator has twelve connections, labeled SUE T 1 through SUE T 12, one to each switch, so every accelerator reaches every switch in a crisscross full mesh. Each lane runs at 100 Gbps or 200 Gbps into the SUE-T switch. Any two accelerators are one hop apart, which keeps latency low for AI workloads. A design where every pair is one hop apart is easier to reason about, because the path length does not depend on which two accelerators talk. You get that property from the wiring alone, not from software."}),"\n",(0,a.jsx)(t.p,{children:"The physical Ethernet connection stays the same. SUE-T adds the new AFH transport and an optimized Ethernet header to carry remote memory access from one accelerator to another. The RoCEv2 and UET frame formats are not used here, because they add overhead. A single-hop design needs less entropy handling, so the RoCEv2 and BTH fields are not needed. The memory access rules are also simpler, which shortens the time needed to write results into a remote HBM."}),"\n",(0,a.jsx)(t.p,{children:"A scale-up rack still has to reach the rest of the AI data center. Each compute system uses a dedicated scale-out NIC for that link. Figure 13-4 shows two fabric planes, and production deployments use more planes for better availability. Scale-up System 1 has two NICs. The left NIC receives 800 Gbps from Plane 1, and the right NIC receives 800 Gbps from Plane 2. Each accelerator has an 800 Gbps link that splits into two 400 Gbps links, one to each of two SUE switches. When you cable a rack, count those links on both sides."}),"\n",(0,a.jsx)(t.p,{children:"A multi-plane design offers faster convergence and a controlled minimum of compute capacity across several scale-up systems. Think of two bridges across the same river. If one bridge closes for repairs, the other one still carries traffic, although each car may need a slower route. If one plane goes offline, the capacity between scale-up systems still equals one plane plus the compute capacity of each system. The number of 800 Gbps NIC ports per compute node may vary from two to four with 800 Gbps cards. With 400 Gbps cards, the count runs from four to eight. Those ports connect to ToR Ethernet switches on different fabric planes. A single-plane fabric with inter-pod links also works. Pick the plane count that matches the availability you need. It supports the path diversity options from Chapter 8, IP Routing for AI/ML Fabrics."}),"\n",(0,a.jsx)(t.h3,{id:"57-full-scale-up-comparison-and-why-open-standards-matter",children:"5.7 Full Scale-Up Comparison and Why Open Standards Matter"}),"\n",(0,a.jsx)(t.p,{children:"Comparing NVLink with the open fabrics takes care. Public documentation is thinner for NVLink, while the open standards publish their framing and address rules in detail. A fair comparison weighs what each vendor has published, not only what the marketing page claims. Public NVLink documentation gives fewer detailed specifications than the open standards do. SUE-T was announced as a framework, so its details may change over time. UALink is the best-defined of the three. A well-defined specification gives engineers something concrete to test against, so the gaps between a product and the document are easier to spot. Its transaction and data link flits over the Ethernet PHY, its request semantics, and its address translation are all specified. UALink may take longer to implement than SUE-T, which keeps standard DMAC and SMAC addressing. When you compare them, weigh the level of detail each one publishes."}),"\n",(0,a.jsx)(t.p,{children:"The table below extends the comparison from Section 5.4 with the remaining capabilities. Use the two comparison tables side by side, because the first one covers the hardware and memory model and this one covers ordering, congestion, and openness."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"Capability"}),(0,a.jsx)(t.th,{children:"SUE-T/SUE"}),(0,a.jsx)(t.th,{children:"UALink 1.0"}),(0,a.jsx)(t.th,{children:"NVLink"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Ordering"})}),(0,a.jsx)(t.td,{children:"Per-flow; strict or unordered per virtual channel; single-hop focus"}),(0,a.jsx)(t.td,{children:"Per-stream in-order TL delivery"}),(0,a.jsx)(t.td,{children:"In-order per flow; global fabric ordering via switches"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Congestion control"})}),(0,a.jsx)(t.td,{children:"In-band credits (AFH) and endpoint rate control"}),(0,a.jsx)(t.td,{children:"Credit-based"}),(0,a.jsx)(t.td,{children:"Fabric-internal; scheduler and backpressure in NVSwitch"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Programming model"})}),(0,a.jsx)(t.td,{children:"AXI or FIFO into SUE-T; one-sided verbs; libraries map collectives to SUE-T"}),(0,a.jsx)(t.td,{children:"PGAS API (load/store/atomic/fence), collectives over TL"}),(0,a.jsx)(t.td,{children:"CUDA, NCCL, NVSHMEM with coherent pointers; hardware collectives"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Openness/ecosystem"})}),(0,a.jsx)(t.td,{children:"Open (OCP), leverages Ethernet optics and switches"}),(0,a.jsx)(t.td,{children:"Open consortium spec (new switches and ASICs)"}),(0,a.jsx)(t.td,{children:"Proprietary Nvidia stack and hardware"})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Cost"})}),(0,a.jsx)(t.td,{children:"Medium"}),(0,a.jsx)(t.td,{children:"Medium"}),(0,a.jsx)(t.td,{children:"High"})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"Open standards matter to buyers, not only to engineers. A buyer who can mix suppliers can negotiate on price, and can switch a supplier without rebuilding the whole pod. That freedom has a value that does not show up in a single benchmark. When accelerators and switches from different vendors work together, a data center can mix hardware from several suppliers. That can lower cost, add flexibility, and speed up innovation. NVLink offers strong performance, but it ties a buyer to one vendor's stack. UALink and SUE-T are meant to be open standards from industry groups. They define interoperable protocols, hardware interfaces, and memory models, so multi-vendor super-accelerators become possible. As a buyer, you gain room to choose suppliers."}),"\n",(0,a.jsx)(t.h3,{id:"58-ualink-flit-layout-station-wiring-and-address-handles",children:"5.8 UALink Flit Layout, Station Wiring, and Address Handles"}),"\n",(0,a.jsx)(t.p,{children:"UALink moves data in small fixed units, and its addresses are not plain MAC addresses. Think of the fixed units as standard shipping containers. Every container has the same size, so the terminal can plan the space for each one before it arrives. Readers who expect Ethernet behavior often get confused here. The next pieces show how one write request is packed, wired, and addressed. Keep the Ethernet picture aside while you read them. Think of the UALink format as a different language with its own grammar. Translating each word into Ethernet terms only causes confusion."}),"\n",(0,a.jsxs)(t.p,{children:["Figure 13-13 shows how one uncompressed write request fits into a 64-byte TL flit. The flit has an upper half and a lower half, each 32 bytes. In the upper half, the data pieces ",(0,a.jsx)(t.code,{children:"Req0.Data.0"}),", ",(0,a.jsx)(t.code,{children:"Req0.Data.2"}),", and ",(0,a.jsx)(t.code,{children:"Req0.Data.4"})," stack on top of each other. The lower half starts with four request-control slots, ",(0,a.jsx)(t.code,{children:"Req3"}),", ",(0,a.jsx)(t.code,{children:"Req2"}),", ",(0,a.jsx)(t.code,{children:"Req1"}),", and ",(0,a.jsx)(t.code,{children:"Req0"}),". The pieces ",(0,a.jsx)(t.code,{children:"Req0.Data.1"})," and ",(0,a.jsx)(t.code,{children:"Req0.Data.3"})," sit on the right side of the lower half. So the data for one request spreads across both halves of the flit."]}),"\n",(0,a.jsx)(t.p,{children:"Figure 13-10 shows how accelerators wire into the UALink switches in one rack. Each accelerator has eight connection points, Station 0 through Station 7. Each station holds four 200 Gbps lanes. So each accelerator has 32 lanes and 6.4 Tbps of bandwidth. Station 0 connects to ULS 0 and ULS 1. Station 7 connects to ULS 30 and ULS 31. Each station fans out to several switches, and the same pattern repeats for every accelerator."}),"\n",(0,a.jsx)(t.p,{children:"The software layer registers memory regions on each accelerator. Registration is the step where the runtime tells the hardware which memory may be reached from outside, and it is done before any transfer starts. It defines local SPA ranges and exports them as an address handle table. The handle value goes into the UPLI request, next to the target accelerator identifier. The UALink switch reads the 10-bit accelerator ID and picks the outgoing interface. Ethernet MAC addresses play no role in that step. The PHY is still Ethernet, but the switch routes on a memory-mapped scheme instead. You will see this when you trace a request through the switch."}),"\n",(0,a.jsx)(t.p,{children:"The address handle is a reference object. Think of it as a labeled key card for one room in a building. The card does not open the room by itself. It tells the access system which room to open, and which hardware path to use to get there. It holds everything needed to reach a remote memory region over UALink, including the hardware context and the access control for remote memory access. The originator uses the handle ID in its UPLI requests. The UALink hardware swaps that ID for the NPA plus key bits before anything goes on the wire. A page table entry in the accelerator's MMU links the handle to the accelerator identifier."}),"\n",(0,a.jsxs)(t.p,{children:["On the request side, a 10-bit ",(0,a.jsx)(t.code,{children:"DSTACCID"})," field maps into the NPA address. The ",(0,a.jsx)(t.code,{children:"SRCACCID"})," field lets the responder build the return NPA address. At the destination, the TL decoder takes the delivered flit from UPLI and the MMU. It queues the flit and creates the right receive memory cache entry."]}),"\n",(0,a.jsx)(t.p,{children:"Figure 13-15 shows the three address spaces from end to end. On the source side, three CU blocks send requests to one accelerator MMU, all in the guest virtual address space. The middle section holds the UALink switches, which work in the network physical address space. On the destination side, the second accelerator's MMU translates the address to a system physical address, which reaches two HBM blocks. Follow the arrows from source to destination, and you have the whole translation."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"commands-and-configurations-that-matter",children:"Commands and configurations that matter"}),"\n",(0,a.jsx)(t.p,{children:"The commands below let you check each layer this chapter described, from the NVMe-oF discovery step to the UET capture and the GPUDirect Storage registration. Think of them as a set of gauges on a control panel. Each gauge reads one part of the path, and a needle in the wrong place points you to the part to inspect first. Run them on the storage node, or on a GPU host attached to the fabric. Each block is marked untested here, so treat its output as the first thing to check on your own cluster. Run the blocks in order, write down what each one returns, and compare the result with the chapter before you change any setting."}),"\n",(0,a.jsx)(t.h3,{id:"1-nvme-o-tcp-port-8009-and-nvme-o-rdma-rocev2-ports-8009---4420---4791-host-operations",children:"1. NVMe-o-TCP (Port 8009) and NVMe-o-RDMA (RoCEv2 Ports 8009 -> 4420 -> 4791) Host Operations"}),"\n",(0,a.jsx)(t.p,{children:"Start with the MTU, because multi-PDU packing depends on jumbo frames being set on the storage NIC. A host that discovers a target correctly but runs with the default frame size will still connect, and it will quietly lose the packing benefit described earlier. Check the MTU before you trust any throughput number. Then discover the targets, connect, and list the subsystems and their multipath state."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"# 1. Verify storage NIC jumbo frame MTU (9000 bytes) for multi-PDU NVMe-o-TCP / RoCEv2 packing (untested here)\nip -d link show dev eth2\n\n# 2. Discover NVMe-oF targets over the standard Discovery Controller TCP port 8009 (untested here)\n# Returns RDMA_PRTYPE (04=RoCEv2, 02=InfiniBand, 05=iWARP) or TCP transport descriptors\nsudo nvme discover -t tcp  -a 10.40.1.100 -s 8009\nsudo nvme discover -t rdma -a 10.40.2.100 -s 8009\n\n# 3. Connect an NVMe-o-TCP namespace (lossy IP fabric, 1:1 SQ/CQ per core over TCP 8009) (untested here)\nsudo nvme connect -t tcp  -n nqn.2026-10.io.ai-storage:subsys01 -a 10.40.1.100 -s 8009 --nr-io-queues=16\n\n# 4. Connect an NVMe-o-RDMA namespace over RoCEv2 (UDP 4420 CM -> UDP 4791 BTH/RETH) (untested here)\nsudo nvme connect -t rdma -n nqn.2026-10.io.ai-storage:subsys01 -a 10.40.2.100 -s 4420 --nr-io-queues=16\n\n# 5. Inspect active NVMe-oF subsystems, namespaces (NSIDs), and Fab A / Fab B multipath state (untested here)\nsudo nvme list-subsys\n"})}),"\n",(0,a.jsx)(t.h3,{id:"2-inspecting-nvme-o-rdma-uet-over-udp-49150-and-uet-over-ip-proto-253-on-the-wire",children:"2. Inspecting NVMe-o-RDMA, UET-over-UDP (49150), and UET-over-IP (Proto 253) on the Wire"}),"\n",(0,a.jsx)(t.p,{children:"Packet captures are the fastest way to confirm which encapsulation a link is really carrying. The config file says what the team intended, and the capture says what the switch actually forwarded. When the two disagree, believe the capture and fix the config. Capture the storage ports first, then the UET ports, and then ask Libfabric which delivery modes the provider offers."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"# 1. Capture NVMe-oF Discovery (TCP 8009), RDMA CM (UDP 4420), and RoCEv2 data (UDP 4791) (untested here)\nsudo tcpdump -ni eth2 'tcp port 8009 or udp port 4420 or udp port 4791' -c 50\n\n# 2. Capture Ultra Ethernet Transport (UET) over UDP (port 49150) or Native IP (protocol 253) (untested here)\nsudo tcpdump -ni eth0 'udp port 49150 or ip proto 253 or ip6 proto 253' -vvv -c 50\n\n# 3. Query Libfabric UET provider capabilities, delivery modes (ROD/RUD/RUDI/UUD), and domain (untested here)\nfi_info -v -p uet\n"})}),"\n",(0,a.jsx)(t.h3,{id:"3-infiniband-storage-subnet-lid--16-vls-and-gpudirect-storage-verification",children:"3. InfiniBand Storage Subnet (LID & 16 VLs) and GPUDirect Storage Verification"}),"\n",(0,a.jsx)(t.p,{children:"The last two checks confirm the InfiniBand addressing and the GDS registration. Run them on the node that will carry the storage traffic, because the answers depend on that node's own HCA and mounts, not on a sister node that happens to look similar. Run them on the node that will carry the storage traffic, because the answers depend on that node's own HCA and mounts."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"# 1. Inspect InfiniBand HCA 16-bit LID assignment, active Virtual Lanes (VLs), and port state (untested here)\nibstat\nibv_devinfo -v\n\n# 2. Verify GPUDirect Storage (GDS) registration with NVMe-oF / WekaFS / VAST mounts (untested here)\n/usr/local/cuda/gds/tools/gdscheck -p\n"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"how-it-fails",children:"How it fails"}),"\n",(0,a.jsx)(t.p,{children:"A misconfigured storage fabric, UEC link, or scale-up pod rarely prints an obvious protocol error. The job just runs slowly, stalls, or produces wrong numbers. Think of a fabric fault like a leaking pipe behind a wall. The water shows up as a stain on the ceiling, far from the leak, so the symptom and the cause are often several layers apart. The table maps each of the common symptoms to its likely cause and to the fix. Start from the symptom you can see, then work back to the layer that caused it. When a job fails, match the symptom against this list first."}),"\n",(0,a.jsxs)(t.table,{children:[(0,a.jsx)(t.thead,{children:(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.th,{children:"#"}),(0,a.jsx)(t.th,{children:"Failure Mode"}),(0,a.jsx)(t.th,{children:"Observable Symptom"}),(0,a.jsx)(t.th,{children:"Root-Cause Diagnosis"}),(0,a.jsx)(t.th,{children:"Remediation"})]})}),(0,a.jsxs)(t.tbody,{children:[(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"1"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Long-Haul (40 km+) Lossless RoCEv2 Storage Replication Collapse"})}),(0,a.jsx)(t.td,{children:"Inter-site checkpoint replication over a 40 km+ DCI link suffers periodic throughput collapses and PFC pause backpressure into the local storage leaf switches."}),(0,a.jsx)(t.td,{children:"DCQCN reaction loops and PFC pause quanta cannot maintain lossless headroom across long propagation delays (40 km+), starving local ToR buffers."}),(0,a.jsxs)(t.td,{children:["Keep NVMe-o-RDMA (RoCEv2) strictly intra-site; switch inter-site (40 km+) replication to ",(0,a.jsx)(t.strong,{children:"NVMe-o-TCP"})," (port 8009) or HTTPS S3 over ",(0,a.jsx)(t.strong,{children:"deep-buffer Ethernet switches"}),"."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"2"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"NVMe-o-RDMA Session Hang at Discovery vs CM (TCP 8009 vs UDP 4420/4791)"})}),(0,a.jsxs)(t.td,{children:[(0,a.jsx)(t.code,{children:"nvme discover -t rdma -s 8009"})," succeeds and prints target NQN and ",(0,a.jsx)(t.code,{children:"RDMA_PRTYPE = 04"}),", but ",(0,a.jsx)(t.code,{children:"nvme connect -t rdma"})," times out before creating I/O queues."]}),(0,a.jsxs)(t.td,{children:["Security ACLs or EVPN VRF policies permit TCP 8009 (Discovery Log) and UDP 4791 (RoCEv2), but block ",(0,a.jsx)(t.strong,{children:"UDP 4420"})," (RDMA CM QPair negotiation), preventing QPs from reaching RTS."]}),(0,a.jsxs)(t.td,{children:["Permit all three NVMe-o-RDMA ports end-to-end across Fab A and Fab B: ",(0,a.jsx)(t.strong,{children:"TCP 8009"})," (Discovery), ",(0,a.jsx)(t.strong,{children:"UDP 4420"})," (RDMA CM), and ",(0,a.jsx)(t.strong,{children:"UDP 4791"})," (RoCEv2 data)."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"3"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"UET-over-IP (Protocol 253) Silent Blackholing on Brownfield Switches"})}),(0,a.jsx)(t.td,{children:"UET-over-UDP (port 49150) works at line rate, but switching endpoints to lightweight UET-over-IP drops 100% of PDS SYN packets across the spine."}),(0,a.jsxs)(t.td,{children:["Brownfield Ethernet switch ACLs or L3 forwarding pipelines restrict IP protocol numbers to standard TCP (6), UDP (17), and ICMP (1) or fail to parse the PDS Entropy field under ",(0,a.jsx)(t.strong,{children:"IP Protocol 253"}),"."]}),(0,a.jsxs)(t.td,{children:["Use ",(0,a.jsx)(t.strong,{children:"UET-over-UDP (Dst Port 49150)"})," on brownfield fabrics, or explicitly allow ",(0,a.jsx)(t.strong,{children:"IP Protocol 253"})," and verify 128-byte PDS/SES deep-header parsing on UEC-compliant switches."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"4"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"UET TSS Security Enabled Alongside UET CRC or UUD Delivery Mode"})}),(0,a.jsx)(t.td,{children:"PDC initialization fails with protocol configuration errors, or switch SES-field load balancing collapses to a single link when TSS encryption is turned on."}),(0,a.jsxs)(t.td,{children:["UEC Specification v1.0 forbids enabling UET CRC and TSS (AES-GCM + ICV) simultaneously, marks ",(0,a.jsx)(t.strong,{children:"UUD incompatible with TSS"}),", and encrypts SES (",(0,a.jsx)(t.code,{children:"JobID"}),"/",(0,a.jsx)(t.code,{children:"RI"}),") under TSS so switches cannot read inner SES fields."]}),(0,a.jsxs)(t.td,{children:["Disable UET CRC when enabling TSS, use ROD, RUD, or RUDI (never UUD) for TSS-protected flows, and configure switches to hash on outer ",(0,a.jsx)(t.strong,{children:"UDP Source Port"})," or ",(0,a.jsx)(t.strong,{children:"PDS Entropy"}),"."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"5"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Mixing Legacy PFC and UEC CBFC/LLR on the Same Shared Queue"})}),(0,a.jsx)(t.td,{children:"Brownfield ToR hosting both RoCEv2 and UET servers experiences erratic buffer stalls, false link retries, and tail-latency spikes."}),(0,a.jsxs)(t.td,{children:["Running PFC pause thresholds and UEC CBFC (",(0,a.jsx)(t.code,{children:"CtlOS"})," ",(0,a.jsx)(t.code,{children:"CP_Update"}),") / LLR simultaneously on overlapping buffer pools causes conflicting backpressure loops."]}),(0,a.jsxs)(t.td,{children:["On mixed brownfield ToRs, keep the lossless PFC/DCQCN queue dedicated to legacy RoCEv2 and run UET over a separate best-effort queue using end-to-end ",(0,a.jsx)(t.strong,{children:"NSCC"})," or ",(0,a.jsx)(t.strong,{children:"RCCC"}),", reserving link-level CBFC/LLR for greenfield links."]})]}),(0,a.jsxs)(t.tr,{children:[(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"6"})}),(0,a.jsx)(t.td,{children:(0,a.jsx)(t.strong,{children:"Stale Tensor Reads in Software-Coherent Scale-Up Pods (UALink / SUE-T)"})}),(0,a.jsx)(t.td,{children:"Porting a multi-GPU kernel that relies on direct shared-memory pointers from NVLink (NVL72) to UALink 1.0 or SUE-T produces silent numerical divergence during training."}),(0,a.jsxs)(t.td,{children:["Unlike NVLink/NVSwitch, which dispatches hardware directory ",(0,a.jsx)(t.strong,{children:"snoop invalidations"})," on every cache-line write, UALink 1.0 and SUE-T use ",(0,a.jsx)(t.strong,{children:"software-managed PGAS coherence"})," without hardware cache snooping."]}),(0,a.jsxs)(t.td,{children:["Insert explicit PGAS / TL synchronization barriers (",(0,a.jsx)(t.code,{children:"RMA_FENCE"}),", ",(0,a.jsx)(t.code,{children:"RMA_SYNC"}),", ",(0,a.jsx)(t.code,{children:"NOTIFY"}),", ",(0,a.jsx)(t.code,{children:"RMA_COMPLETION"}),") via the collective/runtime library (NCCL/RCCL/SHMEM) before peer xPUs read updated HBM regions."]})]})]})]}),"\n",(0,a.jsx)(t.p,{children:"Failures 1 and 2 are both about ports and distance, while failures 3 and 4 are about encapsulation and security settings. Think of these two groups as the two sides of a border crossing. One group checks where the traffic is allowed to go, and the other checks what the traffic is allowed to carry. Failure 5 comes from mixing two lossless mechanisms on one queue, and failure 6 comes from assuming hardware coherence that the platform does not provide. If you see one of these symptoms, jump straight to the matching row. You will save time if you trust the table over your first guess. You can use the table as a quick check during an incident, row by row. Port and encapsulation problems usually show up at session setup, while coherence problems show up later as wrong numbers during training. That timing is a useful clue on its own. A session that never starts points to ports and headers, and a session that starts cleanly and then drifts points to memory visibility or to a security setting that hides fields from the switches. Look for those symptoms first when you bring up a new fabric."}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"hands-on-lab",children:"Hands-on lab"}),"\n",(0,a.jsx)(t.p,{children:"Suppose you are on call and must check a new storage and UEC fabric before the training team arrives on Monday. The lab below is built for that situation. Its first half runs anywhere, and its second half needs the real hardware."}),"\n",(0,a.jsx)(t.p,{children:"The lab has two halves. The first runs on your laptop and checks the protocol arithmetic from this chapter. The second runs on a Nebius GPU cluster and checks the live fabric with the commands from the commands section. Treat the first half as a rehearsal and the second half as the real inspection, since only the second half touches the hardware."}),"\n",(0,a.jsx)(t.h3,{id:"venue-and-scope",children:"Venue and Scope"}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Local runnable lab:"})," Run ",(0,a.jsx)(t.code,{children:"code/part12/storage_uec_scaleup.py"})," and ",(0,a.jsx)(t.code,{children:"code/part12/storage_uec_scaleup_lab.py"})," with the Python 3 standard library. The lab runs 25 automated self-checks. They cover NVMe-o-TCP, NVMe-o-RDMA, InfiniBand storage, UEC v1.0 UET, OCP SUE-T, and UALink 1.0."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Cluster verification:"})," Run the ",(0,a.jsx)(t.code,{children:"nvme"}),", ",(0,a.jsx)(t.code,{children:"tcpdump"}),", ",(0,a.jsx)(t.code,{children:"fi_info"}),", ",(0,a.jsx)(t.code,{children:"ibstat"}),", and ",(0,a.jsx)(t.code,{children:"gdscheck"})," commands from the commands section on a Nebius GPU cluster. These cluster steps were not run on a live cluster while this chapter was drafted, so treat any output you see there as your first real data point."]}),"\n"]}),"\n",(0,a.jsx)(t.h3,{id:"run-the-verification-lab",children:"Run the Verification Lab"}),"\n",(0,a.jsx)(t.p,{children:"Start the self-check script with the command below. Nothing in the script touches a switch or a NIC, so it is safe to run on a laptop before you open a terminal on the cluster. Each line of its output is one check, and a PASS means the chapter's numbers hold in the code."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-bash",children:"python3 -B code/part12/storage_uec_scaleup_lab.py\n"})}),"\n",(0,a.jsx)(t.p,{children:"If every check passes, the output should match the block below. Read the lines in order, because each one names a single claim from the chapter, and a failure on one line tells you which section to reread. A FAIL on any line means that check no longer matches the figures in this chapter."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"=== Chapter 12.21 Lab: Storage Networks, Ultra Ethernet and Scale-Up Fabrics ===\n  [PASS] 1. NVMe-o-TCP session uses TCP port 8009, ICReq/ICResp PDUs, and runs on lossy IP fabrics\n  [PASS] 2. NVMe-o-TCP capsule IDs map 0x01=CapsuleCmd, 0x02=CapsuleResp, 0x03=H2CData, 0x04=C2HData and opcodes 0x01=Write, 0x02=Read\n  [PASS] 3. Jumbo-frame MTU 9000 (MSS 8960B) packs 2 NVMe-o-TCP 4 KB in-capsule PDUs (4192B each) into one TCP segment\n  [PASS] 4. NVMe-o-RDMA over RoCEv2 discovers over TCP 8009 (RDMA_PRTYPE=0x04), negotiates QPs over UDP 4420, and transfers data over UDP 4791\n  [PASS] 5. NVMe-o-RDMA RDMA_PRTYPE codes map 0x02=InfiniBand, 0x04=RoCEv2, and 0x05=iWARP\n  [PASS] 6. InfiniBand storage fabric uses 16-bit LID (up to 48,000 nodes per subnet), 16 VLs, and 64-byte CBFC credits (64 credits for 4096B)\n  [PASS] 7. InfiniBand deployment exceeding 48,000 nodes requires inter-subnet routing with the Global Routing Header (GRH)\n  [PASS] 8. UET over UDP uses IP protocol 17, destination UDP port 49150, and UDP source port for dynamic path-spraying entropy\n  [PASS] 9. UET over native IP uses IP protocol 253, omits the UDP header, and places Entropy directly in the PDS header within the 128B switch parse depth\n  [PASS] 10. UET enforces mutual exclusion between UET CRC and TSS (AES-GCM + ICV) security on the same packet\n  [PASS] 11. UEC delivery modes ROD and RUD are supported across AI Base, AI Full, and HPC profiles\n  [PASS] 12. UEC RUDI supports idempotent multi-writer gradient retries, while UUD omits PSNs/ACKs and is incompatible with TSS security\n  [PASS] 13. UEC RCCC allocates receiver credits in 256-byte units inside a 24-bit ACK field (256 credits for a 64 KB transfer)\n  [PASS] 14. UEC link-level CBFC doubles virtual channels from 16 (InfiniBand VLs) to 32 VCs per port using PCS CtlOS CP_Update messages\n  [PASS] 15. Dropping packet 1 of a 64-packet window triggers 64 retransmissions under RoCEv2 Go-Back-N vs 1 selective retry under UET (64.0x reduction)\n  [PASS] 16. SUE-T AFH Generation 2 uses a 6-byte compressed header for single-hop scale-up pods and a 12-byte non-compressed header for two-hop topologies\n  [PASS] 17. SUE-T Reliability Header (RH) encodes a 10-bit xPU ID (up to 1,024 endpoints) and 16-bit NPSN/APSN sequence numbers with up to 4096B SUE PDUs\n  [PASS] 18. SUE-T on-die ARM AXI 4.0 interface maps 5 channels (AR, AW, W requests on VC0; B, R responses on VC1) vs 1 raw stream on FIFO\n  [PASS] 19. UALink 1.0 supports 8 stations x 4 lanes x 200 Gbps = 32 lanes = 6.4 Tbps aggregate bandwidth per xPU accelerator\n  [PASS] 20. UALink Transaction Layer (TL) flits are 64 bytes (16 x 4B sectors, split into upper and lower 32B half-flits)\n  [PASS] 21. UALink Data Link (DL) packs 10 x 64B TL flits into one 640B DL flit (+ 40B FEC = 680B wire unit) aligned 1:1 with an RS(544,514)x10b PCS codeword\n  [PASS] 22. UALink 1-way and 2-way PCS codeword interleaving cut FEC serialization latency by 4.0x and 2.0x compared to standard 4-way Ethernet interleaving\n  [PASS] 23. UALink UPLI exposes 4 channels (Req, OrigData, RD Res, WR Res) with 57-bit ReqAddr and 10-bit ACC-ID (up to 1,000 accelerators per pod)\n  [PASS] 24. UALink MMU address handle pipeline translates GVA -> NPA -> SPA across UALink Switches (ULS) using software PGAS coherence\n  [PASS] 25. Scale-up technology comparison verifies NVLink 5 (18 switches, 72 GPUs, 1.8 Tbps, 100-300 ns hardware coherence) vs PCIe 5.0 (500-1000 ns, 32 GT/s, 64 Gbps x16)\n\nSummary: 25 passed, 0 failed\n"})}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"common-first-mistakes",children:"Common first mistakes"}),"\n",(0,a.jsx)(t.p,{children:"These four mistakes come up again and again in storage and UEC reviews. Each one looks reasonable on a slide, and each one breaks a real fabric. Think of them as the common potholes on a new road, and check each one before you drive the first truck over the surface. Each one looks reasonable on a slide, and each one breaks a real fabric. Read them before you draw the first diagram, and you will avoid the most common traps."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Confusing NSID with PRP1, PRP2, and SGL in NVMe-oF packet captures."})," The NSID picks the target logical volume on the storage array controller. PRP1 and PRP2 pointers, and SGL descriptors, do a different job. They name the initiator host or GPU BAR1 buffer addresses where DMA places the data. If you read one as the other, the capture will not make sense. Keep a short note beside your capture that labels each field, so the next reader does not repeat the same confusion."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Sizing storage fabrics at 1:1 non-blocking capacity, or stretching RoCEv2 across 40 km+ links."})," Dedicated storage fabrics run efficiently at 1:3 leaf-to-spine oversubscription, provided that the 100G or 200G storage NICs sit on Fab A and Fab B with symmetric failover capacity. Across inter-site links of 40 km+, never stretch lossless RoCEv2 and PFC. Use NVMe-o-TCP with deep-buffer switches, or HTTPS S3 tiering, instead. If you plan a link like that, expect a different transport from the one you use inside the site. The inside of the site and the link between sites have different loss and delay profiles, and each one needs its own transport choice."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Configuring switches to hash UET packets on RoCEv2 BTH Queue Pair offsets."})," UET removes the InfiniBand Base Transport Header completely, so a BTH-based hash has nothing to read. Switches that forward UET traffic must hash on the UDP Source Port for UET-over-UDP port 49150. For UET-over-IP protocol 253, they hash on the PDS Entropy field. With unencrypted SES fields, they can also hash on those. Check which fields your switches can see before you pick the hash, because the choice decides whether the load spreads across all links or piles onto one."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Assuming standard Ethernet switches can transparently switch UALink 1.0 traffic."})," UALink 1.0 reuses 200G IEEE 802.3 PHY signaling, but it aligns 640-byte DL flits directly to RS(544, 514) PCS codewords with 1-way or 2-way interleaving. It also switches on the 10-bit ACC-ID and NPA memory addresses, not on Ethernet MAC headers. That requires purpose-built UALink Switches. A standard Ethernet switch looks at the MAC header, and that header is not where a UALink switch finds its route, so the swap is not a simple firmware change. OCP SUE-T under ESUN is different, because it keeps IEEE-compliant DMAC and SMAC positions through its 6-byte or 12-byte AFH Gen 2 header."]}),"\n"]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"exercises",children:"Exercises"}),"\n",(0,a.jsx)(t.p,{children:"Work the six exercises below with the parameter block in front of you. Picture each exercise as a small design question that a colleague might ask you during a review, and answer it the way you would answer on the call. Each one asks for a specific number or a comparison, so write your answer down with its unit before you check the chapter."}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:"Exercise Input Parameters Reference:\n- Exercise 1: NVMe-o-TCP 4 KiB (4,096B) in-capsule write PDU (24B CH+PSH + 4B HDGST + 64B SQE + 4,096B data + 4B DDGST = 4,192B) inside MTU 9000 (MSS = 8,960B); NVMe-o-RDMA ports TCP 8009, UDP 4420, UDP 4791 and RDMA_PRTYPE 0x04 (RoCEv2), 0x02 (InfiniBand), 0x05 (iWARP)\n- Exercise 2: 32,000-node vs 60,000-node InfiniBand storage cluster (16-bit LID = 65,536 values, 48,000 max nodes/subnet; GRH required for 60,000); 4,096B block across 12 active VLs (16 max VLs, 64B per LLH CBFC credit = 64 credits)\n- Exercise 3: UET-over-UDP (IP Proto 17, UDP Dst Port 49150, UDP Src Port entropy) vs UET-over-IP (IP Proto 253, PDS Entropy field, 128-byte switch parse depth); packet #1 lost in 64-packet window (64 Go-Back-N retries vs 1 UET selective retry)\n- Exercise 4: 64 KiB (65,536B) RCCC transfer in 256-byte credit units (256 credits in 24-bit ACK field); 32 UEC CBFC VCs vs 16 IB VLs using PCS CtlOS CP_Update\n- Exercise 5: 256B SUE-T payload with 6B compressed AFH Gen 2 (280B, 91.43%) vs 12B non-compressed AFH Gen 2 (286B, 89.51%); 5 ARM AXI 4.0 channels (AR, AW, W on VC0; B, R on VC1) vs FIFO\n- Exercise 6: UALink 1.0 8 stations x 4 lanes x 200 Gbps = 32 lanes = 6,400 Gbps (6.4 Tbps); 4B TL sector, 32B half-flit, 64B TL flit, 640B DL flit (10 TL flits + 8B CRC), 680B wire unit (+ 40B FEC) in RS(544, 514) 10-bit PCS codeword; GVA -> NPA (10-bit ACC-ID) -> SPA\n"})}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:["Jumbo-frame packing, then session bring-up. Picture a storage engineer who must confirm the packing before the array goes live. Use ",(0,a.jsx)(t.code,{children:"calculate_nvme_tcp_pdu_packing()"})," and ",(0,a.jsx)(t.code,{children:"trace_nvme_of_session()"})," in ",(0,a.jsx)(t.code,{children:"code/part12/storage_uec_scaleup.py"}),". Work out the byte size of one NVMe-o-TCP in-capsule write PDU. Count how many of them fit in one MTU 9000 TCP segment. List the three L4 ports that an NVMe-o-RDMA session passes through during bring-up, in order."]}),"\n",(0,a.jsx)(t.li,{children:"InfiniBand storage at 32,000 and 60,000 nodes. Take the two clusters from the parameter block and judge native InfiniBand for each. Find the bit width of an LRH LID. Decide which cluster needs routing between subnets through the GRH. Calculate how many 64-byte LLH CBFC credits one 4,096-byte block needs. State the maximum number of VLs per port."}),"\n",(0,a.jsx)(t.li,{children:"UET over UDP against UET over IP. Compare the two encapsulations by their outer IP protocol number, UDP destination port, entropy field, and switch parse depth. Count the packets retransmitted when packet 1 of a 64-packet window is lost under RoCEv2 Go-Back-N. Count them again under UET selective retry."}),"\n",(0,a.jsx)(t.li,{children:"Credits and virtual channels. For the 64 KiB RCCC payload, calculate how many 256-byte credits the receiver grants in its 24-bit ACK field. Compute the largest window those 24 bits can represent. State how many Virtual Channels a UEC CBFC port supports. Compare that count with InfiniBand VLs. Name the PCS message that carries the credit updates."}),"\n",(0,a.jsxs)(t.li,{children:["SUE-T header cost. Use ",(0,a.jsx)(t.code,{children:"evaluate_suet_scaleup_fabric()"})," on a 256-byte payload. Give the total frame size and the payload efficiency for a single-hop frame. Repeat that for a two-hop frame. Explain how SUE-T maps the 5 ARM AXI 4.0 channels onto ",(0,a.jsx)(t.code,{children:"VC0"})," and ",(0,a.jsx)(t.code,{children:"VC1"}),". Explain how that differs from the FIFO interface."]}),"\n",(0,a.jsx)(t.li,{children:"One UALink 1.0 transfer. An accelerator has 8 UALink 1.0 stations. Calculate its total lanes and its bandwidth per xPU. Give the byte size of a TL sector, a TL half-flit, and a TL flit. Give the byte size of a DL flit and of the wire unit with FEC. Trace the address translation from GVA to NPA to SPA."}),"\n"]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"interview-angles",children:"Interview angles"}),"\n",(0,a.jsx)(t.p,{children:"These questions come up when an interviewer wants to know whether you understand the wire, not just the marketing summary. Each answer below names the protocol steps, the ports, and the fields an experienced engineer would mention. Say the answer out loud once before you write it down, because spoken steps tend to come out in the right order. If you can say the steps in order, you can answer the question well. Pause after each step and check that you named the port or field it depends on, because interviewers usually follow up on exactly those details."}),"\n",(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:'"Walk me through the exact wire-level difference between establishing an NVMe-o-TCP session and an NVMe-o-RDMA (RoCEv2) session."'}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"What they are testing:"})," Depth of storage protocol state machines beyond high-level TCP versus RDMA summaries. Your answer should show that you know the steps, not only the names."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"Senior answer:"})," NVMe-o-TCP runs entirely over TCP port 8009 on a lossy IP fabric. After the TCP handshake and optional TLS, the host exchanges ",(0,a.jsx)(t.code,{children:"ICReq"})," and ",(0,a.jsx)(t.code,{children:"ICResp"})," PDUs and ",(0,a.jsx)(t.code,{children:"NVMe Connect"})," requests to bind a 1:1 SQ and CQ pair. It then transfers ",(0,a.jsx)(t.code,{children:"CapsuleCmd"}),", ",(0,a.jsx)(t.code,{children:"H2CData"})," or ",(0,a.jsx)(t.code,{children:"C2HData"}),", and ",(0,a.jsx)(t.code,{children:"CapsuleResp"})," PDUs, and it packs multiple PDUs into each MTU 9000 TCP segment. The steps are the same whether you read a capture or answer on a whiteboard. NVMe-o-RDMA over RoCEv2 is different. It needs a lossless fabric at 1:3 oversubscription, and it spans three ports. First, TCP port 8009 serves the Discovery Controller ",(0,a.jsx)(t.code,{children:"Get Log Page"}),", which returns ",(0,a.jsx)(t.code,{children:"RDMA_PRTYPE = 04"})," for RoCEv2. Second, UDP port 4420 handles the RDMA CM handshake that brings the QPair to RTS. Third, UDP port 4791 handles the 1:1 queue creation, the ",(0,a.jsx)(t.code,{children:"RDMA_SEND"})," command capsules, and the controller-initiated ",(0,a.jsx)(t.code,{children:"RDMA_READ"})," and ",(0,a.jsx)(t.code,{children:"RDMA_WRITE"})," bulk DMA."]}),"\n"]}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:'"How does Ultra Ethernet (UEC v1.0) eliminate RoCEv2\'s PFC storms and Go-Back-N retransmission penalties?"'}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"What they are testing:"})," Understanding of UET PDS and SES, delivery modes, NSCC and RCCC, packet trimming, and LLR."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"Senior answer:"})," RoCEv2 pins flows to static BTH QPairs, and it flushes an entire window through Go-Back-N when a single packet drops. That forces operators to rely on hop-by-hop PFC pause frames. UEC v1.0 replaces the BTH with UET over UDP port 49150 or IP protocol 253, split into PDS and SES. First, RUD and RUDI allow out-of-order Direct Data Placement into GPU HBM, with selective retransmission of only the missing PSN. Second, sender-driven NSCC and target-driven RCCC, which uses 256-byte receiver credits in a 24-bit ACK field, prevent congestion and receiver incast end to end, without PFC. Third, DSCP packet trimming slices off payloads on congested switches. It forwards the trimmed headers on a high-priority queue, which triggers immediate targeted NACKs. Optional link-level LLR and 32-VC CBFC handle hop-by-hop loss and flow control cleanly. Name the three mechanisms in order, and the answer will sound complete."]}),"\n"]}),"\n"]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:'"Compare NVIDIA NVLink, OCP SUE-T (ESUN), and UALink 1.0 for building a scale-up super-accelerator pod."'}),"\n",(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"What they are testing:"})," Architectural trade-offs across wire framing, switch silicon, bandwidth, and hardware versus software memory coherence."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.em,{children:"Senior answer:"})," NVLink 5 in NVL72 connects 72 GPUs across 18 proprietary NVSwitches, at 1.8 Tbps per GPU and 100 to 300 ns latency. It uses hardware directory and snoop cache coherence. The coherence model is the biggest difference you will explain in this answer. To build open multi-vendor pods that scale up to 1,000 xPUs across 1 to 4 racks, OCP SUE-T under ESUN keeps standard Ethernet DMAC and SMAC switching. It uses a 6-byte compressed or 12-byte non-compressed AFH Gen 2 header, plus an 8-byte Reliability Header, LLR, CBFC, and on-die FIFO or AXI 4.0 interfaces. UALink 1.0 exposes 8 stations of 4 lanes of 200G per xPU, for 6.4 Tbps. It translates GVA to NPA to SPA through MMU address handles. It packs ten 64B TL flits into one 640B DL flit, which aligns 1:1 to an RS(544, 514) PCS codeword, with 1-way or 2-way interleaving across ULS switches. Both SUE-T and UALink use software-managed PGAS coherence (",(0,a.jsx)(t.code,{children:"RMA_FENCE"}),", ",(0,a.jsx)(t.code,{children:"RMA_SYNC"}),", ",(0,a.jsx)(t.code,{children:"NOTIFY"}),"), so coherence can scale to 1,000 xPUs. If you explain that trade-off clearly, the interviewer can follow your reasoning."]}),"\n"]}),"\n"]}),"\n"]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"checkpoint-questions-20",children:"Checkpoint questions (20)"}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"1. How do local PCIe Gen5 SSD latency, InfiniBand storage switch latency, and Ethernet storage switch latency compare?"})}),(0,a.jsx)(t.p,{children:"You can read the three latencies as a ladder. A local PCIe Gen5 SSD answers in roughly 100 ns. A native InfiniBand storage switch adds roughly 300 ns. An Ethernet storage switch adds roughly 700 to 900 ns of port-to-port latency."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"2. What are the four AI storage network topology designs, and what leaf-to-spine oversubscription ratio is typical for dedicated storage fabrics?"})}),(0,a.jsx)(t.p,{children:"You can choose among four designs: physical Fab A and Fab B separation, logical Fab A and Fab B separation with EVPN-VXLAN RT5 or MAC-VRF, a collapsed Fab A and Fab B spine, and a hybrid on-prem plus multi-cloud fabric. Dedicated storage fabrics typically run at 1:3 leaf-to-spine oversubscription."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"3. Why is NVMe-o-TCP preferred over NVMe-o-RDMA (RoCEv2) for inter-site storage replication across 40 km+ links?"})}),(0,a.jsx)(t.p,{children:"Keeping RoCEv2 lossless with DCQCN and PFC over a 40 km+ link is fragile. The long round-trip delay exhausts the buffer headroom. NVMe-o-TCP runs reliably over a lossy IP core, using standard TCP congestion and flow control together with deep-buffer switches. You can use that reasoning in any design review."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"4. Trace the complete NVMe-o-TCP session establishment, data transfer, and teardown sequence on TCP port 8009."})}),(0,a.jsxs)(t.p,{children:["Consider the handshake first, because every later step depends on it. Each step must finish before the next one can start. 1. Complete the ",(0,a.jsx)(t.code,{children:"TCP SYN -> SYN-ACK -> ACK"})," handshake on port 8009, plus the optional TLS handshake.\n2. Exchange an ",(0,a.jsx)(t.code,{children:"NVMe/TCP ICReq PDU"})," and an ",(0,a.jsx)(t.code,{children:"ICResp PDU"}),", which set the host and controller capabilities, the digests, and the data offset.\n3. Exchange a ",(0,a.jsx)(t.code,{children:"NVMe/TCP Connect Request"})," and a ",(0,a.jsx)(t.code,{children:"Connect Response"}),", which bind the controller to the SQ and CQ 1:1.\n4. Move the data with ",(0,a.jsx)(t.code,{children:"CapsuleCmd"})," (",(0,a.jsx)(t.code,{children:"0x01"}),"), ",(0,a.jsx)(t.code,{children:"H2CData"})," (",(0,a.jsx)(t.code,{children:"0x03"}),") or ",(0,a.jsx)(t.code,{children:"C2HData"})," (",(0,a.jsx)(t.code,{children:"0x04"}),"), and ",(0,a.jsx)(t.code,{children:"CapsuleResp"})," (",(0,a.jsx)(t.code,{children:"0x02"}),"). Reads use ",(0,a.jsx)(t.code,{children:"opcode 0x02"}),", and writes use ",(0,a.jsx)(t.code,{children:"0x01"}),".\n5. Tear the session down gracefully with ",(0,a.jsx)(t.code,{children:"H2CTermReq"})," or ",(0,a.jsx)(t.code,{children:"C2HTermReq"}),"."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"5. What are the six ordered fields of an NVMe-o-TCP PDU, and how does MTU 9000 improve PDU transport efficiency?"})}),(0,a.jsxs)(t.p,{children:["In a capture, you can check that the fields arrive in this order. Each NVMe-o-TCP PDU is built in this order: Common Header, then PDU-Specific Header, then Header Digest, then PDU Padding, then PDU Data, and finally Data Digest. If you configure ",(0,a.jsx)(t.code,{children:"MTU 9000"})," end to end across the storage fabric, two or more NVMe-o-TCP PDUs can share one TCP segment."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"6. Trace the three-phase NVMe-o-RDMA (RoCEv2) session state machine and list the three RDMA_PRTYPE provider codes."})}),(0,a.jsxs)(t.ol,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"Discovery:"})," Over TCP port 8009, the host sends Get Log Page \u2013 Discovery Log Pages. The target returns ",(0,a.jsx)(t.code,{children:"RDMA_PRTYPE"})," 04 for RoCEv2, 02 for InfiniBand, or 05 for iWARP."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"RDMA CM:"})," Over UDP port 4420, the endpoints exchange ",(0,a.jsx)(t.code,{children:"RDMA_CM_REQUEST"}),", then ",(0,a.jsx)(t.code,{children:"RDMA_CM_REPLY"}),", then ",(0,a.jsx)(t.code,{children:"RDMA_CM_RTU"}),". The QPair enters RTS at that point."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"NVMe connect and data:"})," Over UDP port 4791, the session runs the NVMe RDMA Connect Capsule and the NVMe IO Queue Create. The controller then starts the ",(0,a.jsx)(t.code,{children:"RDMA_READ"})," and ",(0,a.jsx)(t.code,{children:"RDMA_WRITE"})," transfers, which ride on BTH and RETH."]}),"\n"]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"7. How does native InfiniBand storage handle addressing, inter-subnet routing, frame integrity, and per-hop lossless QoS?"})}),(0,a.jsxs)(t.p,{children:["You will find that the Subnet Manager gives each node a 16-bit LID, which sits in the Local Routing Header, and a subnet can hold up to 48,000 nodes. Larger or multi-subnet fabrics route through the optional Global Routing Header. Each frame runs ",(0,a.jsx)(t.code,{children:"LRH -> GRH -> BTH -> ETH -> Payload -> ICRC + VCRC"}),". Lossless QoS works across up to 16 Virtual Lanes, and each 64-byte CBFC credit in the LLH paces the traffic."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"8. What are the three UEC Specification v1.0 service profiles, and how does Libfabric map application requests into PDS and SES?"})}),(0,a.jsxs)(t.p,{children:["The three profiles are AI Base, AI Full, and HPC. An application calls Libfabric through ",(0,a.jsx)(t.code,{children:"fi_mr"})," and ",(0,a.jsx)(t.code,{children:"fi_collective"}),". Libfabric turns semantic operations such as ",(0,a.jsx)(t.code,{children:"JobID"}),", ",(0,a.jsx)(t.code,{children:"PIDonFEP"}),", Resource Index, Buffer Offset, and Message ID into the Semantic Sublayer. The Packet Delivery Sublayer then receives the delivery and reliability rules, which cover ",(0,a.jsx)(t.code,{children:"SPDCID"})," and ",(0,a.jsx)(t.code,{children:"DPDCID"}),", ",(0,a.jsx)(t.code,{children:"PSN"}),", the delivery mode, and ",(0,a.jsx)(t.code,{children:"NSCC"})," and ",(0,a.jsx)(t.code,{children:"RCCC"}),"."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"9. Compare UET-over-UDP and UET-over-IP encapsulations across protocol numbers, ports, entropy fields, and switch parsing limits."})}),(0,a.jsx)(t.p,{children:"If you compare them, Read the two encapsulations as two ways to carry the same UET packet. UET-over-UDP rides inside IP Protocol 17 with UDP destination port 49150, and it carries its path-spraying entropy in the UDP source port. UET-over-IP drops the UDP header, uses IP Protocol 253, and puts a dedicated Entropy field at the start of the PDS header. That keeps PDS and SES inside the 128-byte switch ASIC parsing window."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"10. What is the rule governing UET CRC and the Transport Security Sublayer (TSS) on a UET packet?"})}),(0,a.jsx)(t.p,{children:"The UEC Specification v1.0 lets a packet use either the UET CRC or TSS, but never both at once. TSS also does not work with UUD. Keep that rule in mind when you configure a link."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"11. Contrast the four UEC packet delivery modes (ROD, RUD, RUDI, UUD) and their primary AI/HPC workloads."})}),(0,a.jsxs)(t.ul,{children:["\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"ROD:"})," Delivers in order, using the receiver NIC reorder buffer. It suits HPC, MPI, and serialized control traffic."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"RUD:"})," Places data out of order with Direct Data Placement and selective retry. It suits AI model parallelism and bulk transfers."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"RUDI:"})," Delivers unordered, and it is safe to retry or write several times. It suits RMA writes and AI gradient updates."]}),"\n",(0,a.jsxs)(t.li,{children:[(0,a.jsx)(t.strong,{children:"UUD:"})," Best-effort, with no PSNs, no ACKs or NACKs, and no TSS. It suits telemetry and inference logs."]}),"\n"]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"12. How do NSCC and RCCC differ in UEC end-to-end congestion management, and what is the exact RCCC credit unit size?"})}),(0,a.jsxs)(t.p,{children:["NSCC is sender-driven. It adjusts the congestion window (",(0,a.jsx)(t.code,{children:"cwnd"}),") and the packet-spraying entropy, based on RTT, the ECN flags in NACKs, and ",(0,a.jsx)(t.code,{children:"ACK_CC"})," telemetry. RCCC is target-driven. Senders request credit through Credit Target (",(0,a.jsx)(t.code,{children:"req_cc_state"}),"), and the receiver grants credit from its local Credit Pool through a 24-bit ACK field. Each credit is 256 bytes. You can think of a credit as a fixed unit of permission to send."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"13. How does UEC link-level CBFC improve upon both IEEE PFC and InfiniBand CBFC?"})}),(0,a.jsxs)(t.p,{children:["Credits are the reason the link can run lossless without pause storms. In practice, UEC CBFC raises the capacity from 8 PFC priorities and 16 InfiniBand VLs to 32 Virtual Channels per port. Its capability is negotiated over LLDP. It tracks Consumed and Freed credits per VC, and it sends credit updates out of band, in the physical sublayer, as PCS ",(0,a.jsx)(t.code,{children:"CtlOS"})," ",(0,a.jsx)(t.code,{children:"CP_Update"})," messages at line rate."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"14. How do UEC DSCP Packet Trimming and Link Layer Reliability (LLR) accelerate loss recovery?"})}),(0,a.jsxs)(t.p,{children:["With DSCP Packet Trimming, you see a congested switch cut the data payload off trim-eligible packets. It forwards the header on a high-priority queue to the target FEP. The target then sends a targeted fast-retransmission request, a ",(0,a.jsx)(t.code,{children:"NACK"}),", and it never writes the trimmed header into GPU memory. With LLR, neighboring link partners give each frame a ",(0,a.jsx)(t.code,{children:"SEQ"})," number in the MAC preamble and keep a copy in an ASIC replay buffer. They retransmit the frame locally when a timeout or a ",(0,a.jsx)(t.code,{children:"NACK SEQ"})," shows it was lost."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"15. What are the components of UEC In-Network Collectives (INC), and how do they interact with xCCLs?"})}),(0,a.jsxs)(t.p,{children:["You will find three parts in UEC INC. Put simply, the switches do the adding, and the hosts send only one copy. There are INC-capable switches (",(0,a.jsx)(t.code,{children:"sFEPs"}),") that run switch INC agents, an out-of-band INC Manager that talks over gRPC, and the Libfabric ",(0,a.jsx)(t.code,{children:"fi_collective"})," API. User-space xCCLs coordinate GPU collectives on the hosts. INC instead elects a root-of-tree spine switch, which aggregates and distributes the collective vectors inside the switch silicon."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"16. Why do scale-up pods replace PCIe with NVLink, SUE-T, or UALink, and what is the physical scale limit of a scale-up pod?"})}),(0,a.jsx)(t.p,{children:"Read this answer as a case for scale-up fabrics. PCIe 5.0 and PCIe 6.0 cannot match the 100 to 300 ns latency and the multi-Tbps per-xPU bandwidth that tightly coupled tensor parallelism and MoE all-to-all routing need. For you as a designer, cables shorter than 4 meters and power limits keep a scale-up pod to 1 to 4 racks and up to 1,000 xPUs."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"17. In OCP SUE-T (ESUN), what is the difference between the 6-byte and 12-byte AFH Gen 2 headers, and what fields reside in the Reliability Header (RH)?"})}),(0,a.jsxs)(t.p,{children:["When you read a trace, the header tells you which format you are looking at. If your pod is single-hop, the 6-byte compressed AFH Gen 2 header serves it. It encodes the Destination xPU, Traffic Class, and Source xPU inside the DMAC and SMAC positions. The 12-byte non-compressed header serves two-hop topologies. The RH carries ",(0,a.jsx)(t.code,{children:"VER"}),", ",(0,a.jsx)(t.code,{children:"OP"}),", a 10-bit xPU ID, a 16-bit ",(0,a.jsx)(t.code,{children:"NPSN"}),", ",(0,a.jsx)(t.code,{children:"VC"}),", a ",(0,a.jsx)(t.code,{children:"Partition"})," field for tenant isolation, and a 16-bit ",(0,a.jsx)(t.code,{children:"APSN"}),"."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"18. How do the FIFO and ARM AXI 4.0 on-die interfaces differ in SUE-T accelerators?"})}),(0,a.jsxs)(t.p,{children:["Picture the two interfaces side by side. The FIFO interface streams raw PDUs, using a 10-bit xPU ID and a 2-bit VC ID, and it has no memory-transaction semantics. The ARM AXI 4.0 interface exposes five independent transaction channels on two virtual channels. Its ",(0,a.jsx)(t.code,{children:"AR"}),", ",(0,a.jsx)(t.code,{children:"AW"}),", and ",(0,a.jsx)(t.code,{children:"W"})," requests travel on ",(0,a.jsx)(t.code,{children:"VC0"}),", and its ",(0,a.jsx)(t.code,{children:"B"})," and ",(0,a.jsx)(t.code,{children:"R"})," responses travel on ",(0,a.jsx)(t.code,{children:"VC1"}),"."]})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"19. Explain the UALink 1.0 station/lane hierarchy (6.4 Tbps) and how 64B TL flits pack into 640B DL flits and RS(544, 514) PCS codewords."})}),(0,a.jsx)(t.p,{children:"Work the arithmetic from the bottom up. If you build a UALink 1.0 xPU, it has up to 8 stations of 4 lanes of 200 Gbps SerDes, which makes 32 lanes and 6.4 Tbps. The Transaction Layer encodes commands and data into 64-byte TL flits. The Data Link layer packs 10 TL flits into one 640-byte DL flit, and adding 40 bytes of FEC makes a 680-byte wire unit. That unit aligns 1:1 into a single RS(544, 514) PCS codeword, which travels with 1-way or 2-way interleaving."})]}),"\n",(0,a.jsxs)(s,{children:[(0,a.jsx)("summary",{children:(0,a.jsx)(t.strong,{children:"20. Trace the UALink 1.0 GVA -> NPA -> SPA address translation pipeline and explain why UALink uses software PGAS coherence instead of hardware snoops."})}),(0,a.jsxs)(t.p,{children:["You can trace it this way: a compute unit issues a request in the Guest Virtual Address space. The source MMU and the Address Handle translate that GVA into a globally unique Network Physical Address, which carries a 10-bit ",(0,a.jsx)(t.code,{children:"DSTACCID"})," and ",(0,a.jsx)(t.code,{children:"SRCACCID"}),". UALink Switches route the DL flit using the 10-bit ACC-ID. The destination Link MMU then translates the NPA into a local System Physical Address in HBM. UALink 1.0 uses software-managed PGAS coherence (",(0,a.jsx)(t.code,{children:"RMA_FENCE"}),", ",(0,a.jsx)(t.code,{children:"RMA_SYNC"}),", ",(0,a.jsx)(t.code,{children:"NOTIFY"}),") instead of hardware directory snoops. That lets coherence scale across 1,000 multi-vendor accelerators."]})]}),"\n",(0,a.jsx)(t.hr,{}),"\n",(0,a.jsx)(t.h2,{id:"sources-and-review-notes",children:"Sources and review notes"}),"\n",(0,a.jsxs)(t.p,{children:["The primary book sources (",(0,a.jsx)(t.code,{children:"SQs"}),"/",(0,a.jsx)(t.code,{children:"SQEs"}),", ",(0,a.jsx)(t.code,{children:"CQs"}),"/",(0,a.jsx)(t.code,{children:"CQEs"}),", ",(0,a.jsx)(t.code,{children:"SQ/CQ-to-QPair"})," 1:1 mapping, ",(0,a.jsx)(t.code,{children:"RKEYs"}),", ",(0,a.jsx)(t.code,{children:"16-VL"})," InfiniBand, ",(0,a.jsx)(t.code,{children:"JCT"})," Job Completion Time, ",(0,a.jsx)(t.code,{children:"Key-Value"})," stores) and verification notes for Chapter 12.21 are cataloged below."]}),"\n",(0,a.jsx)(t.pre,{children:(0,a.jsx)(t.code,{className:"language-text",children:'Primary Book Sources and Verification Notes for Chapter 12.21:\n1. AI Data Center Network Design and Technologies (ai-data-center-network-design-and-technologies, Chapters 9, 12, and 13):\n   - Chapter 9 (Storage Network Design and Technologies):\n     Local PCIe Gen5/Gen6 (32 GT/s per lane, ~63 Gbps unidirectional on x16, ~100 ns latency) vs network-connected storage (~300 ns InfiniBand switch latency, 700-900 ns / 800 ns Ethernet switch latency)\n     4-stage AI training storage lifecycle (ingestion, processing/curation, model training/checkpointing, data warehouse), 100 Gbps/200 Gbps (400G/800G) storage NICs\n     4 storage network topologies: Physical Fab A / Fab B, Logical Fab A / Fab B with EVPN-VXLAN RT5 / MAC-VRF and 1:3 leaf-to-spine oversubscription, Collapsed Fab A / Fab B spine with deep-buffer switches for 40 km+ links, and Hybrid Cloud with firewall IPsec/HTTPS S3 replication across Cloud 1 and Cloud 2\n     Table 9-1 (Object vs Block vs File storage), NVMe-oF architecture, NVMe-o-TCP state machine (TCP port 8009, ICReq/ICResp PDUs, Connect Req/Resp, CapsuleCmd 0x01, CapsuleResp 0x02, H2CData 0x03, C2HData 0x04, opcode 0x02 Read / 0x01 Write, NSID vs 64-bit PRP1/PRP2 vs SGL descriptors, in-capsule vs off-capsule writes with LAST-PDU, CH/PSH/HDGST/PAD/DATA/DDGST PDU format, MTU 9000 multi-PDU packing, H2CTermReq/C2HTermReq)\n     NVMe-o-RDMA (RoCEv2) state machine (66% lower write latency, TCP 8009 Discovery Log with RDMA_PRTYPE = 04 RoCEv2 / 02 IB / 05 iWARP, UDP 4420 RDMA CM Request/Reply/RTU, UDP 4791 BTH + RETH + NVM CMD QID/CMD, strict 1:1 SQ/CQ to QPair mapping, controller-initiated RDMA_READ/RDMA_WRITE)\n     Parallel file systems (WekaFS, VAST, Lustre, GPFS, BeeGFS, POSIX .pt/.npy/.ckpt/.h5/.bin Tier-1 RDMA + Tier-2 S3), GPUDirect Storage (GDS: cudaMalloc, cuFileBufRegister, PIN to direct IO, PyTorch v2.7.0+)\n     InfiniBand for storage (16-bit LID up to 48,000 nodes in LRH, GRH, BTH, ETH, ICRC/VCRC, 16 VLs, 64-byte CBFC credits in LLH, 10 km spec optics), Table 9-2\n   - Chapter 12 (Ultra Ethernet Consortium - UEC):\n     UEC Specification v1.0 (June 11, 2025, 70+ vendors, 1 million+ endpoint target), Table 12-1 motivations, 8 UEC working groups (Physical Layer FEC stats + 64B/66B PCS CtlOS, Link Layer LLR + PRI + CBFC, Transport UET + PDS/SES + TSS + NSCC/RCCC + packet trimming, Software Libfabric fi_mr/fi_collective + INC, Storage, Management, Performance & Debug, Compliance), 3 profiles (AI Base, AI Full, HPC)\n     UEC terminology (FEP, FA with IPv6 SLAAC, PDC with SPDCID/DPDCID and CCC_ID, PDS, SES, JobID, PIDonFEP, Resource Index), PDC SYN handshake (PSN 101, SPDCID 201, DPDCID 301, Clear PSN Offset)\n     UET-over-UDP (IP Protocol 17, UDP Dst Port 49150, dynamic UDP Src Port entropy) vs UET-over-IP (IP Protocol 253, PDS Entropy field within 128-byte switch parse depth), UET CRC vs TSS (AES-GCM + ICV) mutual exclusion\n     4 packet delivery modes (ROD, RUD, RUDI, UUD in Table 12-2 and selective retry vs RoCEv2 Go-Back-N), NSCC (cwnd, RTT, ECN, ACK_CC received bytes/service time/out-of-order count), RCCC (Credit Target req_cc_state, 24-bit ACK credits in 256-byte units), CBFC (32 VCs vs 16 IB VLs, CC/CF counters, PCS CtlOS CP_Update, LLDP negotiation), DSCP packet trimming, LLR (SEQ in MAC preamble + ASIC replay buffer + ACK/NACK), INC vs xCCL (Table 12-3, sFEPs, INC Manager over gRPC, root-of-tree spine aggregation), and Table 12-4 (InfiniBand vs RoCEv2 vs UET)\n   - Chapter 13 (Scale-Up Systems):\n     Scale-up vs scale-out (100-300 ns NVLink vs 500 ns-1 us PCIe 5.0 at 32 GT/s / 3.94 GB/s per lane / 64 Gbps x16, PCIe 6.0 8 GB/s per lane / ~128 Gbps bidir x16, CXL 3.0 100 ns at 32 GT/s, NVLink 5 1.8 Tbps / 1,800 Gbps per GPU across 18 NVLink switches in NVL72, B300 4 GPUs with 1,152 GB HBM3, 1-4 racks / 72 to 1,000 xPUs)\n     7 scale-up AI use cases (foundational LLMs, diffusion 1,024 images on 512 xPUs, MoE / reasoning, digital-twin physics, GNNs ~300 ns, financial modeling, edge AI), multi-plane Fabric Plane 1 | Plane 2 scale-out integration\n     OCP SUE-T (ESUN: 100G/200G SerDes, 12 SUE instances x 12 lanes, 256B flit / 4,096B SUE PDU, 6-byte compressed vs 12-byte non-compressed AFH Gen 2, RH with 10-bit xPU ID + 16-bit NPSN/APSN + VC + Partition, LLR + CBFC, on-die FIFO 10-bit xPU + 2-bit VC vs ARM AXI 4.0 5 channels AR/AW/W on VC0 and B/R on VC1)\n     UALink 1.0 (8 stations x 4 x 200 Gbps lanes = 32 lanes = 6.4 Tbps per xPU, < 4 m cables, < 1 us RTT, ULS 0..31 switches vs UALink Direct, UPLI 4 channels Req/OrigData/RD Res/WR Res, 57-bit ReqAddr, 10-bit ACC-ID for up to 1,000 accelerators, 64-byte TL flits with 16 x 4B sectors and upper/lower 32B half-flits, 640-byte DL flits packing 10 TL flits + 8B CRC + 40B FEC = 680-byte wire unit aligned 1:1 to RS(544, 514) 10-bit PCS codewords, 1-way/2-way vs 4-way codeword interleaving, GVA -> NPA -> SPA MMU + Address Handle translation, virtual pod partitioning)\n     Hardware Directory/Snoop Coherence vs Software PGAS Coherence (RMA_SYNC, NOTIFY, RMA_FENCE, RMA_COMPLETION, ATOMIC_ACK), and Table 13-1 (SUE-T vs UALink 1.0 vs NVLink)\n     Chapter 13 reference list: Arm.com, "AMBA AXI and ACE Protocol Specification," 2025, developer.arm.com/documentation/ihi0022/e; "Scale-Up Ethernet Framework Specification," 2025, docs.broadcom.com/doc/scale-up-ethernet-framework; Open Compute Project, "Introducing ESUN: Advancing Ethernet for Scale-Up AI Infrastructure at OCP," opencompute.org blog; Ultra Accelerator Link, "UALink 200G 1.0 Specification Overview and Applications," 2025 video; Nvidia, "Nvidia GB200 NVL72," nvidia.com/en-us/data-center/gb200-nvl72/; Nathan Kalyanasundharam, "Introducing UALink 200G 1.0 Specification," 2025, UALink 1.0 white paper\n2. Verification and honest-scope note:\n   - Companion simulation and 25 self-checks (code/part12/storage_uec_scaleup.py and code/part12/storage_uec_scaleup_lab.py) verified locally (25 passed, 0 failed)\n   - Cluster nvme, tcpdump, fi_info, ibstat, and gdscheck commands marked (untested here)\n   - Naming note: the source book calls the middle UEC profile AI Advanced in its working-group discussion and AI Full elsewhere. This chapter uses AI Full.\n'})})]})}function l(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(c,{...e})}):c(e)}},28453(e,t,s){s.d(t,{R:()=>o,x:()=>i});var n=s(96540);let a={},r=n.createContext(a);function o(e){let t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function i(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);